B.brg={"\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0648\u0633\u064a\u0637":0,"\u062f\u0648\u0631 \u0645\u062f\u064a\u0631 \u0645\u0643\u062a\u0628 \u0627\u0644\u062a\u062d\u0635\u064a\u0646":1,"\u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629":2,"\u0631\u0635\u062f \u0627\u0644\u062a\u063a\u0637\u064a\u0627\u062a":3,"\u062d\u0633\u0627\u0628 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646":4,"\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062a\u0633\u0631\u0628":5,"\u062a\u062a\u0628\u0639 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u064a\u0646":6,"\u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u062f\u0648\u0631\u064a\u0629":7,"\u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0635\u062d\u064a":8,"\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062f\u0642\u064a\u0642":9,"\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062e\u0632\u0648\u0646":10,"\u062e\u0637\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0633\u0646\u0648\u064a\u0629":11,"\u0627\u0644\u062c\u0644\u0633\u0627\u062a \u0627\u0644\u062b\u0627\u0628\u062a\u0629 \u0648\u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629":12,"\u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0645\u0639 \u0627\u0644\u0634\u0631\u0643\u0627\u0621":13,"\u0635\u0646\u0639 \u0627\u0644\u0642\u0631\u0627\u0631 \u0627\u0644\u0645\u0628\u0646\u064a \u0639\u0644\u0649 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a":14,"\u0627\u0644\u0625\u0634\u0631\u0627\u0641 \u0627\u0644\u062f\u0627\u0639\u0645":15,"\u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0625\u0634\u0631\u0627\u0641\u064a\u0629":16,"\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0625\u0634\u0631\u0627\u0641\u064a\u0629":17,"\u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0628\u0646\u0627\u0621\u0629":18,"\u062e\u0637\u0629 \u0627\u0644\u062a\u062d\u0633\u064a\u0646":19,"\u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646":20,"\u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0648\u0637\u0646\u064a\u0629":21,"\u062d\u0645\u0644\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0644\u0644\u0623\u0648\u0628\u0626\u0629":22,"\u0627\u0644\u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629 \u0644\u0644\u062d\u0645\u0644\u0627\u062a":23,"\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062d\u0645\u0644\u0627\u062a":24,"\u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u062d\u0645\u0644\u0627\u062a":25,"\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u062d\u0645\u0644\u0627\u062a":26,"\u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u062d\u0645\u0644\u0627\u062a":27,"\u0641\u0631\u0642 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629":28,"\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0642\u0627\u0631\u0648\u0631\u0629 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629":29,"\u062d\u0633\u0627\u0628 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c \u0645\u0646 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a":30,"\u062d\u0633\u0627\u0628 \u0627\u0644\u0647\u062f\u0631":31,"\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062b\u0644\u0627\u062c\u0627\u062a":32,"\u062a\u0639\u0628\u0626\u0629 \u062d\u0627\u0641\u0638\u0627\u062a \u0627\u0644\u0644\u0642\u0627\u062d":33,"\u062a\u062d\u0636\u064a\u0631 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u062c\u0627\u0641\u0629":34,"\u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u062d\u0642\u0646":35,"\u0627\u0644\u062a\u062e\u0644\u0635 \u0645\u0646 \u0627\u0644\u0646\u0641\u0627\u064a\u0627\u062a \u0627\u0644\u062d\u064a\u0648\u064a\u0629":36,"\u0645\u0631\u0627\u0642\u0628\u0629 \u062f\u0631\u062c\u0629 \u0627\u0644\u062d\u0631\u0627\u0631\u0629":37,"\u0635\u064a\u0627\u0646\u0629 \u0645\u0639\u062f\u0627\u062a \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f":38,"\u0646\u0642\u0644 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a":39,"\u0627\u0644\u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u0635\u062d\u064a\u062d \u0644\u0644\u0642\u0627\u062d\u0627\u062a":40,"\u0625\u062f\u0627\u0631\u0629 \u0627\u0646\u0642\u0637\u0627\u0639 \u0627\u0644\u062a\u0628\u0631\u064a\u062f":41,"\u0646\u0638\u0627\u0645 FIFO \u0648 FEFO":42,"\u0627\u0644\u062a\u0631\u0635\u062f \u0627\u0644\u0648\u0628\u0627\u0626\u064a":43,"\u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0644\u0644\u0623\u0648\u0628\u0626\u0629":44,"\u0631\u0635\u062f \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0627\u0644\u0636\u0627\u0626\u0631\u0629":45,"\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0645\u062f\u0627\u0631\u0633":46,"\u062c\u0648\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a":47,"\u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u0637\u0644\u0628":48,"\u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629":49,"\u0645\u0643\u0627\u0641\u062d\u0629 \u0627\u0644\u0634\u0627\u0626\u0639\u0627\u062a":50,"\u0627\u0644\u062a\u062b\u0642\u064a\u0641 \u0627\u0644\u0635\u062d\u064a":51,"\u0627\u0644\u062a\u0643\u0627\u0645\u0644 \u0645\u0639 \u0628\u0631\u0627\u0645\u062c \u0623\u062e\u0631\u0649":52,"\u062a\u0648\u062b\u064a\u0642 \u0627\u0644\u062a\u0637\u0639\u064a\u0645\u0627\u062a":53,"\u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0641\u064a \u0627\u0644\u0637\u0648\u0627\u0631\u0626 \u0648\u0627\u0644\u0646\u0632\u0648\u062d":54,"\u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0627\u0644\u062f\u0648\u0644\u064a\u0629 \u0644\u0644\u062a\u0637\u0639\u064a\u0645":55,"\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629":56,"\u0627\u0644\u062a\u062e\u0644\u0635 \u0645\u0646 \u0627\u0644\u0623\u0645\u0631\u0627\u0636":57,"\u0645\u0639\u0627\u0644\u062c\u0629 \u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0631\u0641\u0636":58,"\u0627\u0644\u062a\u0637\u0648\u0639 \u0641\u064a \u0627\u0644\u062a\u062d\u0635\u064a\u0646":59,"\u0627\u0644\u0634\u0631\u0627\u0643\u0629 \u0645\u0639 \u0627\u0644\u0642\u0637\u0627\u0639 \u0627\u0644\u062e\u0627\u0635":60,"\u0628\u0646\u0627\u0621 \u0642\u062f\u0631\u0627\u062a \u0627\u0644\u0639\u0627\u0645\u0644\u064a\u0646":61,"\u0627\u0644\u062a\u062d\u0641\u064a\u0632 \u0648\u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629":62,"\u0627\u062c\u062a\u0645\u0627\u0639\u0627\u062a \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629":63,"\u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0631\u0628\u0639\u064a":64,"\u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u0627\u0644\u0646\u0632\u0648\u062d":65,"\u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0634\u0627\u0645\u0644\u0629":66,"\u0635\u062d\u0629 \u0627\u0644\u0623\u0645 \u0648\u0627\u0644\u0637\u0641\u0644 \u0648\u0627\u0644\u062a\u062d\u0635\u064a\u0646":67,"\u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0641\u0639\u0627\u0644 \u0645\u0639 \u0627\u0644\u0645\u062c\u062a\u0645\u0639":68,"\u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629 \u0644\u0644\u062a\u062d\u0635\u064a\u0646":69,"\u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0639\u0646 AEFI":70,"\u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u0627\u0644\u0633\u062c\u0644 \u0627\u0644\u0645\u062f\u0646\u064a":71,"\u0645\u0624\u0634\u0631 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a":72,"\u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0639\u0627\u062f\u0644 \u0644\u0644\u0642\u0627\u062d\u0627\u062a":73,"\u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u0627\u0644\u0631\u0639\u0627\u064a\u0629 \u0627\u0644\u0623\u0648\u0644\u064a\u0629":74,"\u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0641\u064a \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u062d\u0636\u0631\u064a\u0629":75,"\u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u0645\u062e\u0641\u0641":76,"\u0623\u0646\u0648\u0627\u0639 \u0623\u0643\u064a\u0627\u0633 \u0627\u0644\u062b\u0644\u062c":77,"\u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u0627\u0644\u062a\u062d\u0648\u0644 \u0627\u0644\u0631\u0642\u0645\u064a":78,"\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0644\u0642\u0627\u062d \u0627\u0644\u0645\u062a\u062c\u0645\u062f":79,"\u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u062a\u063a\u064a\u0631 \u0627\u0644\u0645\u0646\u0627\u062e":80,"\u062c\u062f\u0648\u0644 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0645\u062d\u062f\u062b 2026":81,"\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u062d\u0645\u0644\u0627\u062a \u0641\u064a \u0627\u0644\u0646\u0632\u0627\u0639\u0627\u062a":82}
B.Za=new A.ah(B.brg,["\ud83c\udfe2 \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0648\u0633\u064a\u0637 \u0644\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u062f\u0644\u064a\u0644 \u0634\u0627\u0645\u0644:\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0648\u0633\u064a\u0637\u061f\n\u0647\u0648 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0630\u064a \u064a\u0631\u0628\u0637 \u0628\u064a\u0646 \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0627\u0644\u0639\u0644\u064a\u0627 (\u0627\u0644\u0645\u0631\u0643\u0632 \u0627\u0644\u0648\u0637\u0646\u064a) \u0648\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u064a\u062f\u0627\u0646\u064a (\u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u0627\u0644\u0635\u062d\u064a\u0629)\u060c \u0648\u064a\u0634\u0645\u0644 \u0645\u062f\u064a\u0631\u064a \u0645\u0643\u0627\u062a\u0628 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629 \u0648\u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0629.\n\n\ud83c\udfaf \u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u062e\u0637\u064a\u0637: \u0648\u0636\u0639 \u062e\u0637\u0637 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0633\u0646\u0648\u064a\u0629 \u0648\u0627\u0644\u0631\u0628\u0639\u064a\u0629 \u0648\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0648\u0627\u0644\u0645\u0624\u0634\u0631\u0627\u062a\n2\ufe0f\u20e3 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629: \u0631\u0635\u062f \u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u062a\u062d\u0644\u064a\u0644 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u062a\u0637\u0639\u064a\u0645\u064a\u0629\n3\ufe0f\u20e3 \u0627\u0644\u0625\u0634\u0631\u0627\u0641: \u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0625\u0634\u0631\u0627\u0641\u064a\u0629 \u0627\u0644\u062f\u0627\u0639\u0645\u0629 \u0648\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629\n4\ufe0f\u20e3 \u0627\u0644\u062a\u0646\u0633\u064a\u0642: \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0645\u0639 \u0627\u0644\u0634\u0631\u0643\u0627\u0621 (WHO, UNICEF, GAVI) \u0648\u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0627\u0644\u0645\u062d\u0644\u064a\n5\ufe0f\u20e3 \u0627\u0644\u0625\u0628\u0644\u0627\u063a: \u0625\u0639\u062f\u0627\u062f \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u062f\u0648\u0631\u064a\u0629 \u0648\u0631\u0641\u0639\u0647\u0627 \u0644\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0648\u0637\u0646\u064a\n\n\ud83d\udcca \u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0625\u062f\u0627\u0631\u0629 \u0641\u064a \u0627\u0644\u064a\u0645\u0646:\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0648\u0637\u0646\u064a        \u2502 \u0627\u0644\u0645\u0631\u0643\u0632 \u0627\u0644\u0648\u0637\u0646\u064a \u0644\u0644\u062a\u062d\u0635\u064a\u0646      \u2502\n\u2502 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0648\u0633\u064a\u0637        \u2502 \u0645\u0643\u0627\u062a\u0628 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0628\u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0627\u062a    \u2502\n\u2502 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u064a\u062f\u0627\u0646\u064a      \u2502 \u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u0627\u0644\u0635\u062d\u064a\u0629 \u0628\u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0627\u062a   \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n\ud83d\udca1 \u0646\u062c\u0627\u062d \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0648\u0633\u064a\u0637 = \u0646\u062c\u0627\u062d \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0643\u0643\u0644!","\ud83d\udc68\u200d\ud83d\udcbc \u062f\u0648\u0631 \u0645\u062f\u064a\u0631 \u0645\u0643\u062a\u0628 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0628\u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629/\u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0629:\n\n\ud83d\udccc \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0627\u062a \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a:\n   \u2022 \u0625\u0639\u062f\u0627\u062f \u062e\u0637\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0633\u0646\u0648\u064a\u0629 \u0644\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0633\u0627\u0628\u0642\u0629\n   \u2022 \u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0645\u0648\u0627\u0631\u062f \u0648\u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0639\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0627\u062a\n   \u2022 \u0648\u0636\u0639 \u062e\u0637\u0637 \u0644\u0644\u0645\u0646\u0627\u0637\u0642 \u0630\u0627\u062a \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0645\u0646\u062e\u0641\u0636\u0629\n\n2\ufe0f\u20e3 \u0627\u0644\u0625\u062f\u0627\u0631\u0629 \u0648\u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629:\n   \u2022 \u0645\u062a\u0627\u0628\u0639\u0629 \u0633\u064a\u0631 \u062c\u0644\u0633\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u064a\u0648\u0645\u064a\u0629\n   \u2022 \u0645\u0631\u0627\u0642\u0628\u0629 \u0645\u062e\u0632\u0648\u0646 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u0627\u0633\u062a\u0647\u0644\u0627\u0643\u0647\u0627\n   \u2022 \u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u0633\u0644\u0627\u0645\u0629 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n   \u2022 \u062a\u062d\u0644\u064a\u0644 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0623\u0633\u0628\u0648\u0639\u064a\u0627\u064b\n\n3\ufe0f\u20e3 \u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0648\u0627\u0644\u062a\u0648\u0627\u0635\u0644:\n   \u2022 \u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0645\u0639 \u0627\u0644\u0634\u0631\u0643\u0627\u0621 \u0627\u0644\u062f\u0648\u0644\u064a\u064a\u0646 (WHO, UNICEF)\n   \u2022 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0645\u0639 \u0645\u062f\u064a\u0631\u064a \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0627\u062a \u0648\u0627\u0644\u0639\u0627\u0645\u0644\u064a\u0646 \u0627\u0644\u0635\u062d\u064a\u064a\u0646\n   \u2022 \u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0627\u0644\u0645\u062d\u0644\u064a \u0648\u0642\u0627\u062f\u0629 \u0627\u0644\u0631\u0623\u064a\n   \u2022 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0641\u064a \u0627\u062c\u062a\u0645\u0627\u0639\u0627\u062a \u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u0635\u062d\u064a\n\n4\ufe0f\u20e3 \u0628\u0646\u0627\u0621 \u0627\u0644\u0642\u062f\u0631\u0627\u062a:\n   \u2022 \u062a\u0646\u0638\u064a\u0645 \u062f\u0648\u0631\u0627\u062a \u062a\u062f\u0631\u064a\u0628\u064a\u0629 \u0644\u0644\u0639\u0627\u0645\u0644\u064a\u0646 \u0627\u0644\u062c\u062f\u062f\n   \u2022 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062e\u062f\u0645\u0629 (OJT)\n   \u2022 \u062a\u0642\u064a\u064a\u0645 \u0627\u062d\u062a\u064a\u0627\u062c\u0627\u062a \u0627\u0644\u062a\u062f\u0631\u064a\u0628\n\n\ud83d\udca1 \u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0646\u0627\u062c\u062d = \u0642\u0627\u0626\u062f \u064a\u0644\u0647\u0645 \u0641\u0631\u064a\u0642\u0647 \u0644\u062a\u062d\u0642\u064a\u0642 \u0623\u0642\u0635\u0649 \u062a\u063a\u0637\u064a\u0629!","\ud83d\udcca \u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 (KPIs) \u0644\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u062a\u063a\u0637\u064a\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 \u0646\u0633\u0628\u0629 \u062a\u063a\u0637\u064a\u0629 BCG: \u0627\u0644\u0647\u062f\u0641 \u226590%\n\u2022 \u0646\u0633\u0628\u0629 \u062a\u063a\u0637\u064a\u0629 Penta3: \u0627\u0644\u0647\u062f\u0641 \u226590%\n\u2022 \u0646\u0633\u0628\u0629 \u062a\u063a\u0637\u064a\u0629 MR1: \u0627\u0644\u0647\u062f\u0641 \u226590%\n\u2022 \u0646\u0633\u0628\u0629 \u062a\u063a\u0637\u064a\u0629 MR2: \u0627\u0644\u0647\u062f\u0641 \u226580%\n\u2022 \u0646\u0633\u0628\u0629 \u062a\u063a\u0637\u064a\u0629 PCV3: \u0627\u0644\u0647\u062f\u0641 \u226590%\n\u2022 \u0646\u0633\u0628\u0629 \u062a\u063a\u0637\u064a\u0629 Rota2: \u0627\u0644\u0647\u062f\u0641 \u226590%\n\u2022 \u0646\u0633\u0628\u0629 \u062a\u063a\u0637\u064a\u0629 Td2+ \u0644\u0644\u062d\u0648\u0627\u0645\u0644: \u0627\u0644\u0647\u062f\u0641 \u226580%\n\n\ud83d\udccc \u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u062a\u0633\u0631\u0628:\n\u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u0633\u0631\u0628 Penta1\u2192Penta3: \u0627\u0644\u0645\u0642\u0628\u0648\u0644 <10%\n\u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u0633\u0631\u0628 MR1\u2192MR2: \u0627\u0644\u0645\u0642\u0628\u0648\u0644 <10%\n\u2022 \u0645\u0639\u062f\u0644 \u0627\u0644\u062a\u0633\u0631\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0631\u0639\u0627\u062a \u0627\u0644\u0645\u062a\u062a\u0627\u0644\u064a\u0629\n\n\ud83d\udccc \u0645\u0624\u0634\u0631\u0627\u062a \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062e\u0632\u0648\u0646:\n\u2022 \u0645\u0639\u062f\u0644 \u0647\u062f\u0631 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u062d\u0633\u0628 \u0627\u0644\u0646\u0648\u0639\n\u2022 \u0646\u0633\u0628\u0629 \u0646\u0641\u0627\u062f \u0627\u0644\u0645\u062e\u0632\u0648\u0646 (Stock-out rate)\n\u2022 \u062f\u0642\u0629 \u0627\u0644\u062a\u0646\u0628\u0624 \u0628\u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c\u0627\u062a\n\n\ud83d\udccc \u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u062c\u0648\u062f\u0629:\n\u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0639\u0646 AEFI\n\u2022 \u0646\u0633\u0628\u0629 \u0627\u0643\u062a\u0645\u0627\u0644 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u0634\u0647\u0631\u064a\u0629\n\u2022 \u0639\u062f\u062f \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0625\u0634\u0631\u0627\u0641\u064a\u0629 \u0627\u0644\u0634\u0647\u0631\u064a\u0629\n\u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u0627\u0644\u0645\u0644\u062a\u0632\u0645\u0629 \u0628\u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n\n\ud83d\udca1 \u062a\u062a\u0628\u0639 \u0627\u0644\u0645\u0624\u0634\u0631\u0627\u062a \u0628\u0627\u0633\u062a\u0645\u0631\u0627\u0631 = \u062a\u062d\u0633\u064a\u0646 \u0645\u0633\u062a\u0645\u0631 \u0644\u0644\u0623\u062f\u0627\u0621!","\ud83d\udcc8 \u0631\u0635\u062f \u0627\u0644\u062a\u063a\u0637\u064a\u0627\u062a \u0627\u0644\u062a\u0637\u0639\u064a\u0645\u064a\u0629 \u2014 \u062f\u0644\u064a\u0644 \u0639\u0645\u0644\u064a:\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 \u0631\u0635\u062f \u0627\u0644\u062a\u063a\u0637\u064a\u0627\u062a\u061f\n\u0647\u0648 \u0639\u0645\u0644\u064a\u0629 \u062c\u0645\u0639 \u0648\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0642\u0629 \u0628\u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0645\u0637\u0639\u0645\u064a\u0646 \u0645\u0642\u0627\u0631\u0646\u0629 \u0628\u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646\u060c \u0644\u0645\u0639\u0631\u0641\u0629 \u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0648\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0641\u062c\u0648\u0627\u062a.\n\n\ud83d\udd22 \u062d\u0633\u0627\u0628 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 \u0627\u0644\u0631\u0636\u0639 (\u0623\u0642\u0644 \u0645\u0646 \u0633\u0646\u0629) = 3.2% \u0645\u0646 \u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u0633\u0643\u0627\u0646\n\u2022 \u0627\u0644\u062d\u0648\u0627\u0645\u0644 = 4% \u0645\u0646 \u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u0633\u0643\u0627\u0646\n\u2022 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u062f\u0648\u0646 \u0633\u0646\u062a\u064a\u0646 = 6.4% \u0645\u0646 \u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u0633\u0643\u0627\u0646\n\n\ud83d\udccb \u0645\u0639\u0627\u062f\u0644\u0629 \u062d\u0633\u0627\u0628 \u0627\u0644\u062a\u063a\u0637\u064a\u0629:\n\u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 = (\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0639\u0645\u064a\u0646 \xf7 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646) \xd7 100\n\n\ud83d\udccc \u0645\u062b\u0627\u0644 \u0639\u0645\u0644\u064a:\n\u2022 \u0639\u062f\u062f \u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0629: 100,000 \u0646\u0633\u0645\u0629\n\u2022 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646 (\u0631\u0636\u0639): 100,000 \xd7 3.2% = 3,200 \u0631\u0636\u064a\u0639\n\u2022 \u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0639\u0645\u064a\u0646 \u0628\u0640 Penta3: 2,700 \u0637\u0641\u0644\n\u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u063a\u0637\u064a\u0629: (2,700 \xf7 3,200) \xd7 100 = 84.4%\n\n\ud83d\udcca \u0645\u0635\u0627\u062f\u0631 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a:\n\u2022 \u0633\u062c\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u064a\u0648\u0645\u064a\u0629 \u0628\u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u0627\u0644\u0635\u062d\u064a\u0629\n\u2022 \u0646\u0638\u0627\u0645 DHIS2 \u0644\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0635\u062d\u064a\u0629\n\u2022 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u0634\u0647\u0631\u064a\u0629 \u0645\u0646 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0627\u062a\n\u2022 \u0645\u0633\u0648\u062d \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0628\u0627\u0644\u0639\u0646\u0627\u0642\u064a\u062f (Coverage Cluster Survey)\n\n\u26a0\ufe0f \u0623\u0647\u0645\u064a\u0629 \u062f\u0642\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a:\n\u2022 \u0628\u064a\u0627\u0646\u0627\u062a \u062e\u0627\u0637\u0626\u0629 \u2190 \u0642\u0631\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629\n\u2022 \u062a\u062d\u062f\u064a\u062b \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646 \u0633\u0646\u0648\u064a\u0627\u064b \u0636\u0631\u0648\u0631\u064a\n\u2022 \u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u062a\u0646\u0627\u0633\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0631\u0639\u0627\u062a (consistency check)","\ud83d\udc65 \u062d\u0633\u0627\u0628 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646 \u0644\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u0646\u062d\u062a\u0627\u062c \u062d\u0633\u0627\u0628 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646\u061f\n\u2022 \u0644\u0645\u0639\u0631\u0641\u0629 \u0639\u062f\u062f \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629\n\u2022 \u0644\u062d\u0633\u0627\u0628 \u0646\u0633\u0628 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0628\u062f\u0642\u0629\n\u2022 \u0644\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062f\u0642\u064a\u0642 \u0644\u0644\u062c\u0644\u0633\u0627\u062a \u0648\u0627\u0644\u0645\u0648\u0627\u0631\u062f\n\n\ud83d\udd22 \u0627\u0644\u0646\u0633\u0628 \u0627\u0644\u0645\u0639\u062a\u0645\u062f\u0629 (WHO/\u0627\u0644\u064a\u0645\u0646):\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 \u0627\u0644\u0641\u0626\u0629 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629            \u2502 \u0627\u0644\u0646\u0633\u0628\u0629       \u2502\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\n\u2502 \u0627\u0644\u0631\u0636\u0639 (\u0623\u0642\u0644 \u0645\u0646 \u0633\u0646\u0629)         \u2502 3.2%         \u2502\n\u2502 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0623\u0642\u0644 \u0645\u0646 \u0633\u0646\u062a\u064a\u0646       \u2502 6.4%         \u2502\n\u2502 \u0627\u0644\u062d\u0648\u0627\u0645\u0644                    \u2502 4.0%         \u2502\n\u2502 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 2-5 \u0633\u0646\u0648\u0627\u062a          \u2502 16.0%        \u2502\n\u2502 \u0627\u0644\u0646\u0633\u0627\u0621 \u0641\u064a \u0633\u0646 \u0627\u0644\u0625\u0646\u062c\u0627\u0628       \u2502 22.0%        \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n\ud83d\udccb \u0623\u0645\u062b\u0644\u0629 \u0639\u0645\u0644\u064a\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u0645\u062b\u0627\u0644 1: \u0645\u062f\u064a\u0631\u064a\u0629 \u0639\u062f\u062f \u0633\u0643\u0627\u0646\u0647\u0627 50,000\n\u2022 \u0627\u0644\u0631\u0636\u0639: 50,000 \xd7 0.032 = 1,600 \u0631\u0636\u064a\u0639\n\u2022 \u0627\u0644\u062d\u0648\u0627\u0645\u0644: 50,000 \xd7 0.04 = 2,000 \u062d\u0627\u0645\u0644\n\u2022 \u062c\u0631\u0639\u0627\u062a Penta \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629: 1,600 \xd7 3 \xd7 1.1 = 5,280 \u062c\u0631\u0639\u0629\n\n\u0645\u062b\u0627\u0644 2: \u0645\u062f\u064a\u0631\u064a\u0629 \u0639\u062f\u062f \u0633\u0643\u0627\u0646\u0647\u0627 200,000\n\u2022 \u0627\u0644\u0631\u0636\u0639: 200,000 \xd7 0.032 = 6,400 \u0631\u0636\u064a\u0639\n\u2022 \u0627\u0644\u062d\u0648\u0627\u0645\u0644: 200,000 \xd7 0.04 = 8,000 \u062d\u0627\u0645\u0644\n\u2022 \u062c\u0631\u0639\u0627\u062a MR \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629: 6,400 \xd7 2 \xd7 1.5 = 19,200 \u062c\u0631\u0639\u0629\n\n\u26a0\ufe0f \u062a\u0646\u0628\u064a\u0647\u0627\u062a:\n\u2022 \u062d\u062f\u0651\u062b \u0627\u0644\u062a\u0639\u062f\u0627\u062f \u0627\u0644\u0633\u0643\u0627\u0646\u064a \u0633\u0646\u0648\u064a\u0627\u064b\n\u2022 \u0627\u0639\u062a\u0628\u0631 \u0627\u0644\u0646\u0627\u0632\u062d\u064a\u0646 \u0648\u0627\u0644\u0648\u0627\u0641\u062f\u064a\u0646 \u0641\u064a \u0627\u0644\u062d\u0633\u0627\u0628\n\u2022 \u0631\u0627\u062c\u0639 \u0627\u0644\u062a\u0639\u062f\u0627\u062f \u0645\u0639 \u0627\u0644\u0633\u062c\u0644 \u0627\u0644\u0645\u062f\u0646\u064a \u0648\u0627\u0644\u0645\u0633\u0648\u062d \u0627\u0644\u0645\u064a\u062f\u0627\u0646\u064a\u0629","\ud83d\udcc9 \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062a\u0633\u0631\u0628 \u0628\u064a\u0646 \u062c\u0631\u0639\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 \u0627\u0644\u062a\u0633\u0631\u0628 (Dropout)\u061f\n\u0647\u0648 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \u0639\u062f\u062f \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0630\u064a\u0646 \u062a\u0644\u0642\u0648\u0627 \u062c\u0631\u0639\u0629 \u0623\u0648\u0644\u0649 \u0648\u0639\u062f\u062f \u0645\u0646 \u0623\u0643\u0645\u0644\u0648\u0627 \u0627\u0644\u062c\u0631\u0639\u0627\u062a \u0627\u0644\u0644\u0627\u062d\u0642\u0629. \u0627\u0644\u062a\u0633\u0631\u0628 \u064a\u0634\u064a\u0631 \u0625\u0644\u0649 \u0623\u0637\u0641\u0627\u0644 \u0628\u062f\u0623\u0648\u0627 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u0644\u0645 \u064a\u0643\u0645\u0644\u0648\u0647.\n\n\ud83d\udd22 \u0645\u0639\u0627\u062f\u0644\u0629 \u062d\u0633\u0627\u0628 \u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u0633\u0631\u0628:\n\u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u0633\u0631\u0628 = [(\u0639\u062f\u062f \u0627\u0644\u062c\u0631\u0639\u06291 - \u0639\u062f\u062f \u0627\u0644\u062c\u0631\u0639\u06293) \xf7 \u0639\u062f\u062f \u0627\u0644\u062c\u0631\u0639\u06291] \xd7 100\n\n\ud83d\udcca \u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u062a\u0633\u0631\u0628 \u0627\u0644\u0645\u0647\u0645\u0629:\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 \u0627\u0644\u0645\u0624\u0634\u0631                     \u2502 \u0627\u0644\u062d\u062f \u0627\u0644\u0645\u0642\u0628\u0648\u0644    \u2502\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\n\u2502 \u062a\u0633\u0631\u0628 Penta1\u2192Penta3        \u2502 \u0623\u0642\u0644 \u0645\u0646 10%      \u2502\n\u2502 \u062a\u0633\u0631\u0628 Penta1\u2192Penta2        \u2502 \u0623\u0642\u0644 \u0645\u0646 5%       \u2502\n\u2502 \u062a\u0633\u0631\u0628 Penta2\u2192Penta3        \u2502 \u0623\u0642\u0644 \u0645\u0646 5%       \u2502\n\u2502 \u062a\u0633\u0631\u0628 MR1\u2192MR2              \u2502 \u0623\u0642\u0644 \u0645\u0646 10%      \u2502\n\u2502 \u062a\u0633\u0631\u0628 PCV1\u2192PCV3            \u2502 \u0623\u0642\u0644 \u0645\u0646 10%      \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n\ud83d\udccc \u0645\u062b\u0627\u0644 \u0639\u0645\u0644\u064a:\n\u2022 \u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0639\u0645\u064a\u0646 \u0628\u0640 Penta1: 1,000 \u0637\u0641\u0644\n\u2022 \u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0639\u0645\u064a\u0646 \u0628\u0640 Penta3: 850 \u0637\u0641\u0644\n\u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u0633\u0631\u0628: [(1,000 - 850) \xf7 1,000] \xd7 100 = 15% \u274c\n\u2022 \u0627\u0644\u0646\u0633\u0628\u0629 \u0623\u0639\u0644\u0649 \u0645\u0646 10% \u2190 \u062a\u062a\u0637\u0644\u0628 \u062a\u062d\u0642\u064a\u0642\u0627\u064b \u0648\u062a\u062f\u062e\u0644\u0627\u064b!\n\n\ud83d\udd0d \u0623\u0633\u0628\u0627\u0628 \u0627\u0644\u062a\u0633\u0631\u0628:\n\u2022 \u0639\u062f\u0645 \u0648\u0639\u064a \u0627\u0644\u0623\u0647\u0627\u0644\u064a \u0628\u0623\u0647\u0645\u064a\u0629 \u0625\u0643\u0645\u0627\u0644 \u0627\u0644\u062c\u0631\u0639\u0627\u062a\n\u2022 \u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u0635\u062d\u064a\u0629\n\u2022 \u0623\u0648\u0642\u0627\u062a \u0627\u0644\u062c\u0644\u0633\u0627\u062a \u063a\u064a\u0631 \u0645\u0646\u0627\u0633\u0628\u0629\n\u2022 \u0639\u062f\u0645 \u062a\u062a\u0628\u0639 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u064a\u0646\n\u2022 \u0646\u0642\u0635 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a (Stock-out)\n\n\ud83d\udca1 \u062d\u0644\u0648\u0644: \u062a\u062a\u0628\u0639 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u064a\u0646 + \u0627\u0644\u062a\u0648\u0639\u064a\u0629 + \u062a\u0648\u0633\u064a\u0639 \u062c\u0644\u0633\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646","\ud83d\udd0d \u062a\u062a\u0628\u0639 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u064a\u0646 \u0639\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0639\u0645\u0644\u064a\u0629:\n\n\ud83d\udccc \u0645\u0646 \u0647\u0645 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u0648\u0646\u061f\n\u0647\u0645 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0630\u064a\u0646 \u0628\u062f\u0623\u0648\u0627 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u0644\u0645 \u064a\u0643\u0645\u0644\u0648\u0627 \u0627\u0644\u062c\u0631\u0639\u0627\u062a \u0627\u0644\u0645\u062a\u0628\u0642\u064a\u0629\u060c \u0623\u0648 \u0627\u0644\u0630\u064a\u0646 \u0644\u0645 \u064a\u062a\u0644\u0642\u0648\u0627 \u0623\u064a \u062c\u0631\u0639\u0629 \u0639\u0644\u0649 \u0627\u0644\u0625\u0637\u0644\u0627\u0642 (Zero-dose children).\n\n\ud83c\udfaf \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u062a\u062a\u0628\u0639 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u064a\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0646\u0638\u0627\u0645 \u0627\u0644\u062a\u062a\u0628\u0639 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a:\n   \u2022 \u062a\u062d\u062f\u064a\u062b \u0642\u0648\u0627\u0626\u0645 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646 \u0634\u0647\u0631\u064a\u0627\u064b\n   \u2022 \u0645\u0642\u0627\u0631\u0646\u0629 \u0627\u0644\u0642\u0648\u0627\u0626\u0645 \u0645\u0639 \u0633\u062c\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0625\u0639\u062f\u0627\u062f \u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u064a\u0646 \u0644\u0643\u0644 \u0642\u0631\u064a\u0629/\u062d\u064a\n   \u2022 \u062a\u0643\u0644\u064a\u0641 \u0627\u0644\u0645\u062a\u0637\u0648\u0639\u064a\u0646 \u0628\u0632\u064a\u0627\u0631\u0629 \u0627\u0644\u0623\u0633\u0631\n\n2\ufe0f\u20e3 \u0646\u0638\u0627\u0645 \u0627\u0644\u0625\u062d\u0627\u0644\u0629:\n   \u2022 \u062a\u0633\u062c\u064a\u0644 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0637\u0641\u0644 \u0639\u0646\u062f \u0627\u0644\u0632\u064a\u0627\u0631\u0629 \u0627\u0644\u0623\u0648\u0644\u0649\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0645\u0648\u0639\u062f \u0627\u0644\u062c\u0631\u0639\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629 \u0648\u062a\u0630\u0643\u064a\u0631 \u0627\u0644\u0623\u0633\u0631\u0629\n   \u2022 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0647\u0627\u062a\u0641\u064a \u0623\u0648 \u0639\u0628\u0631 SMS \u0642\u0628\u0644 \u0627\u0644\u0645\u0648\u0639\u062f\n   \u2022 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0628\u0637\u0627\u0642\u0627\u062a \u0627\u0644\u062a\u0630\u0643\u064a\u0631 \u0628\u0627\u0644\u0623\u0644\u0648\u0627\u0646\n\n3\ufe0f\u20e3 \u062d\u0635\u0631 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0628\u062c\u0631\u0639\u0629 \u0635\u0641\u0631 (Zero-dose):\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0630\u0627\u062a \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0645\u0646\u062e\u0641\u0636\u0629\n   \u2022 \u0627\u0644\u0639\u0645\u0644 \u0645\u0639 \u0627\u0644\u0642\u0627\u0628\u0644\u0627\u062a \u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0645\u0648\u0627\u0644\u064a\u062f \u0627\u0644\u062c\u062f\u062f\n   \u2022 \u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0645\u0639 \u0627\u0644\u0633\u062c\u0644 \u0627\u0644\u0645\u062f\u0646\u064a\n\n4\ufe0f\u20e3 \u0627\u0644\u062c\u0644\u0633\u0627\u062a \u0627\u0644\u062a\u0646\u0634\u064a\u0637\u064a\u0629:\n   \u2022 \u062a\u0646\u0638\u064a\u0645 \u062c\u0644\u0633\u0627\u062a \u062e\u0627\u0635\u0629 \u0644\u0644\u0645\u062a\u062e\u0644\u0641\u064a\u0646\n   \u2022 \u0641\u0631\u0642 \u0645\u062a\u0646\u0642\u0644\u0629 \u0644\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0646\u0627\u0626\u064a\u0629\n   \u2022 \u062c\u0644\u0633\u0627\u062a \u0645\u0633\u0627\u0626\u064a\u0629 \u0644\u0644\u0639\u0627\u0645\u0644\u064a\u0646\n\n\ud83d\udcca \u0642\u0627\u0639\u062f\u0629 \u0630\u0647\u0628\u064a\u0629:\n\u0643\u0644 \u0637\u0641\u0644 \u0645\u062a\u062e\u0644\u0641 = \u0637\u0641\u0644 \u0628\u062f\u0648\u0646 \u062d\u0645\u0627\u064a\u0629 \u0643\u0627\u0645\u0644\u0629!","\ud83d\udccb \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u062f\u0648\u0631\u064a\u0629 \u0644\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u062f\u0644\u064a\u0644 \u0634\u0627\u0645\u0644:\n\n\ud83d\udccc \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u0634\u0647\u0631\u064a\u0629:\n   \u2022 \u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0645\u0637\u0639\u0645\u064a\u0646 \u062d\u0633\u0628 \u0627\u0644\u0644\u0642\u0627\u062d \u0648\u0627\u0644\u062c\u0631\u0639\u0629\n   \u2022 \u0627\u0633\u062a\u0647\u0644\u0627\u0643 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u0627\u0644\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a\n   \u2022 \u062d\u0627\u0644\u0627\u062a AEFI \u0627\u0644\u0645\u0628\u0644\u063a\u0629\n   \u2022 \u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062a\u0633\u0631\u0628 \u0648\u0627\u0644\u0646\u0641\u0627\u062f\n\n2\ufe0f\u20e3 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u0631\u0628\u0639\u064a\u0629:\n   \u2022 \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u062a\u0637\u0639\u064a\u0645\u064a\u0629\n   \u2022 \u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629\n   \u2022 \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062a\u0633\u0631\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0631\u0639\u0627\u062a\n   \u2022 \u062e\u0637\u0629 \u0627\u0644\u062a\u062d\u0633\u064a\u0646 \u0644\u0644\u0631\u0628\u0639 \u0627\u0644\u0642\u0627\u062f\u0645\n\n3\ufe0f\u20e3 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u0633\u0646\u0648\u064a\u0629:\n   \u2022 \u0645\u0644\u062e\u0635 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0633\u0646\u0648\u064a\u0629\n   \u2022 \u0627\u0644\u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0648\u0627\u0644\u062a\u062d\u062f\u064a\u0627\u062a\n   \u2022 \u0627\u0644\u062a\u0648\u0635\u064a\u0627\u062a \u0644\u0644\u0639\u0627\u0645 \u0627\u0644\u0642\u0627\u062f\u0645\n   \u2022 \u0627\u062d\u062a\u064a\u0627\u062c\u0627\u062a \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0648\u0627\u0644\u0645\u0648\u0627\u0631\u062f\n\n\ud83d\udcca \u062a\u062f\u0641\u0642 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a:\n\u0627\u0644\u0645\u0631\u0641\u0642 \u0627\u0644\u0635\u062d\u064a \u2190 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0629 \u2190 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629 \u2190 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0648\u0637\u0646\u064a\n\n\u26a0\ufe0f \u0634\u0631\u0648\u0637 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u062c\u064a\u062f:\n\u2022 \u0627\u0644\u062f\u0642\u0629: \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0635\u062d\u064a\u062d\u0629 \u0648\u0645\u062d\u0642\u0642\u0629\n\u2022 \u0627\u0644\u0627\u0643\u062a\u0645\u0627\u0644: \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0642\u0648\u0644 \u0645\u0645\u0644\u0648\u0621\u0629\n\u2022 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645: \u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u0641\u064a \u0627\u0644\u0645\u0648\u0639\u062f \u0627\u0644\u0645\u062d\u062f\u062f\n\u2022 \u0627\u0644\u062a\u062d\u0644\u064a\u0644: \u0644\u064a\u0633 \u0641\u0642\u0637 \u0623\u0631\u0642\u0627\u0645 \u0628\u0644 \u062a\u062d\u0644\u064a\u0644 \u0648\u062a\u0648\u0635\u064a\u0627\u062a","\ud83d\udcbb \u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0635\u062d\u064a (DHIS2) \u0644\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 DHIS2\u061f\nDistrict Health Information Software 2 \u2014 \u0646\u0638\u0627\u0645 \u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a \u0644\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0635\u062d\u064a\u0629 \u062a\u0633\u062a\u062e\u062f\u0645\u0647 \u0648\u0632\u0627\u0631\u0629 \u0627\u0644\u0635\u062d\u0629 \u0627\u0644\u064a\u0645\u0646\u064a\u0629 \u0628\u062f\u0639\u0645 \u0645\u0646 WHO \u0648UNICEF.\n\n\ud83c\udfaf \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0627\u062a DHIS2 \u0641\u064a \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a:\n   \u2022 \u062a\u0633\u062c\u064a\u0644 \u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0645\u0637\u0639\u0645\u064a\u0646 \u0634\u0647\u0631\u064a\u0627\u064b\n   \u2022 \u062a\u0633\u062c\u064a\u0644 \u0627\u0633\u062a\u0647\u0644\u0627\u0643 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a\n   \u2022 \u062a\u0633\u062c\u064a\u0644 \u062d\u0627\u0644\u0627\u062a AEFI\n   \u2022 \u062a\u0633\u062c\u064a\u0644 \u0645\u062e\u0632\u0648\u0646 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a\n\n2\ufe0f\u20e3 \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a:\n   \u2022 \u062d\u0633\u0627\u0628 \u0646\u0633\u0628 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b\n   \u2022 \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062a\u0633\u0631\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0631\u0639\u0627\u062a\n   \u2022 \u0645\u0642\u0627\u0631\u0646\u0629 \u0627\u0644\u0623\u062f\u0627\u0621 \u0628\u064a\u0646 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0627\u062a\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0627\u062a\u062c\u0627\u0647\u0627\u062a \u0627\u0644\u0632\u0645\u0646\u064a\u0629 (Trends)\n\n3\ufe0f\u20e3 \u0644\u0648\u062d\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a (Dashboards):\n   \u2022 \u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0628\u0627\u0644\u062e\u0631\u0627\u0626\u0637\n   \u2022 \u0631\u0633\u0648\u0645 \u0628\u064a\u0627\u0646\u064a\u0629 \u0644\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0634\u0647\u0631\u064a\n   \u2022 \u062a\u0646\u0628\u064a\u0647\u0627\u062a \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0645\u062a\u062f\u0646\u064a\u0629\n   \u2022 \u062a\u0642\u0627\u0631\u064a\u0631 \u062c\u0627\u0647\u0632\u0629 \u0644\u0644\u0637\u0628\u0627\u0639\u0629\n\n4\ufe0f\u20e3 \u0641\u062d\u0648\u0635 \u062c\u0648\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a:\n   \u2022 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u062a\u0646\u0627\u0633\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0631\u0639\u0627\u062a\n   \u2022 \u0643\u0634\u0641 \u0627\u0644\u0642\u064a\u0645 \u0627\u0644\u0634\u0627\u0630\u0629 (Outliers)\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u0627\u0643\u062a\u0645\u0627\u0644 \u0648\u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u062a\u0633\u0644\u064a\u0645\n\n\ud83d\udca1 \u0645\u062f\u064a\u0631 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u064a\u062c\u0628 \u0623\u0646 \u064a\u0631\u0627\u062c\u0639 DHIS2 \u0623\u0633\u0628\u0648\u0639\u064a\u0627\u064b!","\ud83d\uddfa\ufe0f \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062f\u0642\u064a\u0642 (Microplanning) \u0644\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062f\u0642\u064a\u0642\u061f\n\u0647\u0648 \u0639\u0645\u0644\u064a\u0629 \u062a\u062e\u0637\u064a\u0637 \u0645\u0641\u0635\u0644\u0629 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0631\u0641\u0642 \u0627\u0644\u0635\u062d\u064a \u0623\u0648 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0629 \u0644\u0636\u0645\u0627\u0646 \u0648\u0635\u0648\u0644 \u062e\u062f\u0645\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0644\u0643\u0644 \u0637\u0641\u0644 \u0641\u064a \u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629.\n\n\ud83c\udfaf \u062e\u0637\u0648\u0627\u062a \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062f\u0642\u064a\u0642:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646:\n   \u2022 \u062d\u0635\u0631 \u0627\u0644\u0645\u0648\u0627\u0644\u064a\u062f \u0627\u0644\u062c\u062f\u062f \u0648\u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u062a\u062d\u062a \u0633\u0646\u0629\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u062a\u062c\u0645\u0639\u0627\u062a \u0627\u0644\u0633\u0643\u0627\u0646\u064a\u0629 \u0648\u0627\u0644\u0642\u0631\u0649\n   \u2022 \u0645\u0631\u0627\u0639\u0627\u0629 \u0627\u0644\u0646\u0627\u0632\u062d\u064a\u0646 \u0648\u0627\u0644\u0631\u0639\u0627\u0629 \u0627\u0644\u0631\u062d\u0644\n\n2\ufe0f\u20e3 \u0631\u0633\u0645 \u062e\u0631\u064a\u0637\u0629 \u0627\u0644\u0645\u0646\u0637\u0642\u0629:\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u0627\u0644\u0635\u062d\u064a\u0629\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0642\u0631\u0649 \u0627\u0644\u0628\u0639\u064a\u062f\u0629 \u0648\u0627\u0644\u0645\u062d\u0631\u0648\u0645\u0629\n   \u2022 \u062d\u0633\u0627\u0628 \u0627\u0644\u0645\u0633\u0627\u0641\u0627\u062a \u0648\u0623\u0648\u0642\u0627\u062a \u0627\u0644\u0648\u0635\u0648\u0644\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0622\u0645\u0646\u0629 \u0648\u0627\u0644\u062e\u0637\u0631\u0629\n\n3\ufe0f\u20e3 \u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062c\u0644\u0633\u0627\u062a:\n   \u2022 \u062c\u0644\u0633\u0627\u062a \u062b\u0627\u0628\u062a\u0629: \u0641\u064a \u0627\u0644\u0645\u0631\u0641\u0642 \u0627\u0644\u0635\u062d\u064a (\u0623\u0633\u0628\u0648\u0639\u064a\u0629)\n   \u2022 \u062c\u0644\u0633\u0627\u062a \u0645\u062a\u0646\u0642\u0644\u0629: \u0644\u0644\u0642\u0631\u0649 \u0627\u0644\u0628\u0639\u064a\u062f\u0629 (\u0634\u0647\u0631\u064a\u0629)\n   \u2022 \u062c\u0644\u0633\u0627\u062a \u062e\u0627\u0631\u062c\u064a\u0629 (Outreach): \u0644\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0646\u0627\u0626\u064a\u0629\n   \u2022 \u0641\u0631\u0642 \u0645\u062a\u0646\u0642\u0644\u0629: \u0644\u0644\u0645\u0646\u0627\u0637\u0642 \u0630\u0627\u062a \u0627\u0644\u0648\u0635\u0648\u0644 \u0627\u0644\u0635\u0639\u0628\n\n4\ufe0f\u20e3 \u062a\u0642\u062f\u064a\u0631 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c:\n   \u2022 \u0643\u0645\u064a\u0629 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u0627\u0644\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a\n   \u2022 \u0639\u062f\u062f \u0627\u0644\u0639\u0627\u0645\u0644\u064a\u0646 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u064a\u0646\n   \u2022 \u062e\u0637\u0629 \u0627\u0644\u0646\u0642\u0644 \u0648\u0627\u0644\u062a\u0646\u0642\u0644\n\n\ud83d\udca1 \u0627\u0644\u062e\u0637\u0629 \u0627\u0644\u062c\u064a\u062f\u0629 = \u062a\u063a\u0637\u064a\u0629 \u0623\u0639\u0644\u0649 + \u0647\u062f\u0631 \u0623\u0642\u0644!","\ud83d\udce6 \u0625\u062f\u0627\u0631\u0629 \u0645\u062e\u0632\u0648\u0646 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u2014 \u062f\u0644\u064a\u0644 \u0639\u0645\u0644\u064a:\n\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u0645\u0647\u0645\u0629\u061f\n\u2022 \u0645\u0646\u0639 \u0646\u0641\u0627\u062f \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a (Stock-out)\n\u2022 \u0645\u0646\u0639 \u0627\u0646\u062a\u0647\u0627\u0621 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629 \u062f\u0648\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\n\u2022 \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u0647\u062f\u0631\n\u2022 \u0636\u0645\u0627\u0646 \u062a\u0648\u0641\u0631 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0641\u064a \u0643\u0644 \u062c\u0644\u0633\u0629 \u062a\u062d\u0635\u064a\u0646\n\n\ud83d\udd22 \u062d\u0633\u0627\u0628 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c \u0627\u0644\u0633\u0646\u0648\u064a:\n\u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c = \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0648\u0646 \xd7 \u0639\u062f\u062f \u0627\u0644\u062c\u0631\u0639\u0627\u062a \xd7 \u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u0647\u062f\u0631\n\n\ud83d\udcca \u0645\u0639\u0627\u0645\u0644\u0627\u062a \u0627\u0644\u0647\u062f\u0631 \u0627\u0644\u0645\u0639\u062a\u0645\u062f\u0629:\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 \u0646\u0648\u0639 \u0627\u0644\u0644\u0642\u0627\u062d                 \u2502 \u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u0647\u062f\u0631  \u2502\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\n\u2502 \u0644\u0642\u0627\u062d\u0627\u062a \u0633\u0627\u0626\u0644\u0629 (Penta,PCV)   \u2502 1.1 (10%)    \u2502\n\u2502 \u0644\u0642\u0627\u062d\u0627\u062a \u0645\u062c\u0641\u0641\u0629 (BCG,MR)     \u2502 1.5 (50%)    \u2502\n\u2502 OPV                        \u2502 1.1 (10%)    \u2502\n\u2502 Rota                       \u2502 1.1 (10%)    \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n\ud83d\udccb \u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0645\u062e\u0632\u0648\u0646:\n\u2022 \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u062f\u0646\u0649: \u0643\u0645\u064a\u0629 \u062a\u0643\u0641\u064a \u0644\u0634\u0647\u0631 \u0648\u0627\u062d\u062f (\u0644\u0627 \u062a\u0646\u0641\u062f \u0623\u0628\u062f\u0627\u064b!)\n\u2022 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0637\u064a: 25% \u0625\u0636\u0627\u0641\u064a\u0629 \u0644\u0644\u0637\u0648\u0627\u0631\u0626\n\u2022 \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u0642\u0635\u0649: \u0643\u0645\u064a\u0629 \u062a\u0643\u0641\u064a \u0644\u0640 3 \u0623\u0634\u0647\u0631 (\u0644\u0627 \u062a\u062e\u0632\u0646 \u0623\u0643\u062b\u0631!)\n\n\ud83d\udccc \u0642\u0627\u0639\u062f\u0629 FIFO/FEFO:\n\u2022 FIFO: \u0623\u0648\u0644 \u0645\u0646 \u064a\u062f\u062e\u0644 = \u0623\u0648\u0644 \u0645\u0646 \u064a\u062e\u0631\u062c\n\u2022 FEFO: \u0623\u0648\u0644 \u0645\u0646 \u062a\u0646\u062a\u0647\u064a \u0635\u0644\u0627\u062d\u064a\u062a\u0647 = \u0623\u0648\u0644 \u0645\u0646 \u064a\u064f\u0633\u062a\u062e\u062f\u0645\n\n\ud83d\udca1 \u0631\u0627\u062c\u0639 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u0623\u0633\u0628\u0648\u0639\u064a\u0627\u064b \u0648\u0627\u0637\u0644\u0628 \u0642\u0628\u0644 \u0627\u0644\u0646\u0641\u0627\u062f \u0628\u0634\u0647\u0631!","\ud83d\udcc5 \u062e\u0637\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0633\u0646\u0648\u064a\u0629 \u0644\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a \u062e\u0637\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0633\u0646\u0648\u064a\u0629\u061f\n\u0648\u062b\u064a\u0642\u0629 \u062a\u062e\u0637\u064a\u0637\u064a\u0629 \u0634\u0627\u0645\u0644\u0629 \u062a\u062d\u062f\u062f \u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u0623\u0647\u062f\u0627\u0641\u0647 \u0648\u0645\u0648\u0627\u0631\u062f\u0647 \u0644\u0645\u062f\u0629 \u0633\u0646\u0629 \u0643\u0627\u0645\u0644\u0629\u060c \u062a\u064f\u0639\u062f \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629 \u0648\u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0629.\n\n\ud83c\udfaf \u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u062e\u0637\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0648\u0628\u0627\u0626\u064a:\n   \u2022 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u062d\u0627\u0644\u064a\u0629 \u0648\u0646\u0642\u0627\u0637 \u0627\u0644\u0636\u0639\u0641\n   \u2022 \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062a\u0633\u0631\u0628 \u0648\u0623\u0633\u0628\u0627\u0628\u0647\n   \u2022 \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0630\u0627\u062a \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0645\u0646\u062e\u0641\u0636\u0629\n   \u2022 \u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0648\u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0645\u0628\u0644\u063a\u0629\n\n2\ufe0f\u20e3 \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0633\u0646\u0648\u064a\u0629:\n   \u2022 \u0646\u0633\u0628 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0644\u0643\u0644 \u0644\u0642\u0627\u062d\n   \u2022 \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u062a\u0633\u0631\u0628 \u0644\u0623\u0642\u0644 \u0645\u0646 10%\n   \u2022 \u0639\u062f\u062f \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0625\u0634\u0631\u0627\u0641\u064a\u0629 \u0627\u0644\u0645\u062e\u0637\u0637\u0629\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0643\u062a\u0645\u0627\u0644 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631\n\n3\ufe0f\u20e3 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0627\u0644\u062c\u062f\u0648\u0644 \u0627\u0644\u0632\u0645\u0646\u064a:\n   \u2022 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0631\u0648\u062a\u064a\u0646\u064a\u0629 (\u062c\u0644\u0633\u0627\u062a\u060c \u0625\u0634\u0631\u0627\u0641\u060c \u062a\u062f\u0631\u064a\u0628)\n   \u2022 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0643\u0645\u064a\u0644\u064a\u0629 (\u062d\u0645\u0644\u0627\u062a\u060c \u0623\u064a\u0627\u0645 \u062a\u062d\u0635\u064a\u0646)\n   \u2022 \u0627\u0644\u062c\u062f\u0648\u0644 \u0627\u0644\u0632\u0645\u0646\u064a \u0627\u0644\u0634\u0647\u0631\u064a\n\n4\ufe0f\u20e3 \u0627\u0644\u0645\u064a\u0632\u0627\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u0648\u0627\u0631\u062f:\n   \u2022 \u062a\u0643\u0644\u0641\u0629 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u0627\u0644\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a\n   \u2022 \u062a\u0643\u0627\u0644\u064a\u0641 \u0627\u0644\u062a\u0634\u063a\u064a\u0644 (\u0646\u0642\u0644\u060c \u062a\u062f\u0631\u064a\u0628)\n   \u2022 \u0645\u0633\u0627\u0647\u0645\u0629 \u0627\u0644\u0634\u0631\u0643\u0627\u0621\n\n\ud83d\udca1 \u062e\u0637\u0629 \u0628\u062f\u0648\u0646 \u0645\u062a\u0627\u0628\u0639\u0629 = \u0648\u062b\u064a\u0642\u0629 \u0639\u0644\u0649 \u0627\u0644\u0631\u0641!","\ud83c\udfe5 \u0627\u0644\u062c\u0644\u0633\u0627\u062a \u0627\u0644\u062b\u0627\u0628\u062a\u0629 \u0648\u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629 \u0644\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0623\u0646\u0648\u0627\u0639 \u062c\u0644\u0633\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062c\u0644\u0633\u0627\u062a \u0627\u0644\u062b\u0627\u0628\u062a\u0629:\n   \u2022 \u0641\u064a \u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u0627\u0644\u0635\u062d\u064a\u0629 \u0628\u0634\u0643\u0644 \u0645\u0646\u062a\u0638\u0645\n   \u2022 \u0645\u0648\u0627\u0639\u064a\u062f \u0645\u062d\u062f\u062f\u0629 \u0648\u0623\u0648\u0642\u0627\u062a \u0645\u0639\u0644\u0646\u0629\n   \u2022 \u062a\u062a\u0648\u0641\u0631 \u0641\u064a\u0647\u0627 \u062c\u0645\u064a\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a\n   \u2022 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f \u0645\u062a\u0648\u0641\u0631\u0629 \u0628\u0634\u0643\u0644 \u062f\u0627\u0626\u0645\n   \u2022 \u062a\u062e\u062f\u0645 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0642\u0631\u064a\u0628\u064a\u0646 (\u0646\u0637\u0627\u0642 5 \u0643\u0645)\n\n2\ufe0f\u20e3 \u0627\u0644\u062c\u0644\u0633\u0627\u062a \u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629 (Outreach):\n   \u2022 \u0641\u0631\u0642 \u062a\u0630\u0647\u0628 \u0644\u0644\u0642\u0631\u0649 \u0627\u0644\u0628\u0639\u064a\u062f\u0629 \u0628\u0634\u0643\u0644 \u062f\u0648\u0631\u064a\n   \u2022 \u062c\u062f\u0648\u0644 \u0632\u064a\u0627\u0631\u0627\u062a \u0645\u062d\u062f\u062f \u0645\u0633\u0628\u0642\u0627\u064b (\u0634\u0647\u0631\u064a/\u0623\u0633\u0628\u0648\u0639\u064a)\n   \u2022 \u062a\u062d\u0645\u0644 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0641\u064a \u062d\u0627\u0641\u0638\u0627\u062a \u0645\u0639\u0628\u0623\u0629 \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d\n   \u2022 \u062a\u062e\u062f\u0645 \u0645\u0646\u0627\u0637\u0642 \u062a\u0628\u0639\u062f \u0623\u0643\u062b\u0631 \u0645\u0646 5 \u0643\u0645 \u0639\u0646 \u0627\u0644\u0645\u0631\u0641\u0642\n   \u2022 \u062a\u062d\u062a\u0627\u062c \u062a\u0646\u0633\u064a\u0642\u0627\u064b \u0645\u0639 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0627\u0644\u0645\u062d\u0644\u064a\n\n3\ufe0f\u20e3 \u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629 (Mobile Teams):\n   \u2022 \u0644\u0644\u0645\u0646\u0627\u0637\u0642 \u0630\u0627\u062a \u0627\u0644\u0648\u0635\u0648\u0644 \u0627\u0644\u0635\u0639\u0628 \u062c\u062f\u0627\u064b\n   \u2022 \u062a\u062e\u062f\u0645 \u0627\u0644\u0631\u062d\u0644 \u0648\u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u062c\u0628\u0644\u064a\u0629\n   \u2022 \u062a\u062d\u062a\u0627\u062c \u062f\u0639\u0645\u0627\u064b \u0644\u0648\u062c\u0633\u062a\u064a\u0627\u064b \u0625\u0636\u0627\u0641\u064a\u0627\u064b\n   \u2022 \u063a\u0627\u0644\u0628\u0627\u064b \u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u062d\u0645\u0644\u0627\u062a \u062a\u062d\u0635\u064a\u0646\n\n\ud83d\udcca \u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0623\u0645\u062b\u0644:\n\u2022 70% \u0645\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0639\u0628\u0631 \u0627\u0644\u062c\u0644\u0633\u0627\u062a \u0627\u0644\u062b\u0627\u0628\u062a\u0629\n\u2022 20% \u0639\u0628\u0631 \u0627\u0644\u062c\u0644\u0633\u0627\u062a \u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629\n\u2022 10% \u0639\u0628\u0631 \u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629\n\n\ud83d\udca1 \u0627\u0644\u0647\u062f\u0641: \u0643\u0644 \u0637\u0641\u0644 \u064a\u062c\u0628 \u0623\u0646 \u064a\u0635\u0644 \u0644\u0644\u062a\u062d\u0635\u064a\u0646 \u0628\u0633\u0647\u0648\u0644\u0629!","\ud83e\udd1d \u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0645\u0639 \u0627\u0644\u0634\u0631\u0643\u0627\u0621 \u0641\u064a \u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0627\u0644\u0634\u0631\u0643\u0627\u0621 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0648\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0645\u0646\u0638\u0645\u0629 \u0627\u0644\u0635\u062d\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0629 (WHO):\n   \u2022 \u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0641\u0646\u064a \u0648\u0627\u0644\u062a\u0648\u062c\u064a\u0647\n   \u2022 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u0642\u062f\u0631\u0627\u062a\n   \u2022 \u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0635\u062f \u0627\u0644\u0648\u0628\u0627\u0626\u064a\n   \u2022 \u062f\u0639\u0645 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\n2\ufe0f\u20e3 \u0627\u0644\u064a\u0648\u0646\u064a\u0633\u064a\u0641 (UNICEF):\n   \u2022 \u062a\u0648\u0641\u064a\u0631 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u0627\u0644\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a\n   \u2022 \u062f\u0639\u0645 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n   \u2022 \u0627\u0644\u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629 \u0648\u0627\u0644\u062a\u0648\u0639\u064a\u0629\n   \u2022 \u062f\u0639\u0645 \u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a\n\n3\ufe0f\u20e3 \u0627\u0644\u062a\u062d\u0627\u0644\u0641 \u0627\u0644\u0639\u0627\u0644\u0645\u064a \u0644\u0644\u0642\u0627\u062d\u0627\u062a (GAVI):\n   \u2022 \u062a\u0645\u0648\u064a\u0644 \u0625\u062f\u062e\u0627\u0644 \u0644\u0642\u0627\u062d\u0627\u062a \u062c\u062f\u064a\u062f\u0629\n   \u2022 \u062f\u0639\u0645 \u062a\u0642\u0648\u064a\u0629 \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0635\u062d\u064a\n   \u2022 \u062a\u0645\u0648\u064a\u0644 \u0627\u0644\u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u0643\u0645\u064a\u0644\u064a\u0629\n\n4\ufe0f\u20e3 \u0627\u0644\u0645\u0646\u0638\u0645\u0627\u062a \u063a\u064a\u0631 \u0627\u0644\u062d\u0643\u0648\u0645\u064a\u0629:\n   \u2022 \u062f\u0639\u0645 \u0627\u0644\u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u0645\u064a\u062f\u0627\u0646\u064a\n   \u2022 \u0627\u0644\u062a\u0648\u0635\u064a\u0644 \u0644\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0646\u0627\u0626\u064a\u0629\n   \u2022 \u0627\u0644\u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629\n\n\ud83d\udca1 \u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u0641\u0639\u0627\u0644 = \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u062a\u0643\u0631\u0627\u0631 + \u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u062a\u0623\u062b\u064a\u0631!","\ud83d\udcca \u0635\u0646\u0639 \u0627\u0644\u0642\u0631\u0627\u0631 \u0627\u0644\u0645\u0628\u0646\u064a \u0639\u0644\u0649 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a (Data-Driven Decision Making):\n\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u0627\u0644\u0642\u0631\u0627\u0631 \u0627\u0644\u0645\u0628\u0646\u064a \u0639\u0644\u0649 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\u061f\n\u2022 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u062a\u064f\u0638\u0647\u0631 \u0627\u0644\u0645\u0634\u0643\u0644\u0629 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u0629 \u0648\u0644\u064a\u0633 \u0627\u0644\u0627\u0646\u0637\u0628\u0627\u0639\n\u2022 \u062a\u0633\u0627\u0639\u062f \u0641\u064a \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u0648\u0644\u0648\u064a\u0627\u062a\n\u2022 \u062a\u064f\u0645\u0643\u0646 \u0645\u0646 \u0642\u064a\u0627\u0633 \u0623\u062b\u0631 \u0627\u0644\u062a\u062f\u062e\u0644\u0627\u062a\n\u2022 \u062a\u062f\u0639\u0645 \u0637\u0644\u0628 \u0627\u0644\u0645\u0648\u0627\u0631\u062f \u0648\u0627\u0644\u062a\u0645\u0648\u064a\u0644\n\n\ud83c\udfaf \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0642\u0631\u0627\u0631\u0627\u062a:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0642\u0631\u0627\u0631\u0627\u062a \u062a\u0634\u063a\u064a\u0644\u064a\u0629 (\u064a\u0648\u0645\u064a\u0629):\n   \u2022 \u0646\u0642\u0644 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0628\u064a\u0646 \u0627\u0644\u0645\u0631\u0627\u0641\u0642\n   \u2022 \u0625\u0636\u0627\u0641\u0629 \u062c\u0644\u0633\u0627\u062a \u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0645\u0639\u0627\u0644\u062c\u0629 \u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0646\u0641\u0627\u062f\n\n2\ufe0f\u20e3 \u0642\u0631\u0627\u0631\u0627\u062a \u062a\u0643\u062a\u064a\u0643\u064a\u0629 (\u0634\u0647\u0631\u064a\u0629/\u0631\u0628\u0639\u064a\u0629):\n   \u2022 \u062a\u0639\u062f\u064a\u0644 \u062e\u0637\u0629 \u0627\u0644\u0639\u0645\u0644\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u062a\u062f\u062e\u0644\n   \u2022 \u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0645\u0648\u0627\u0631\u062f\n\n3\ufe0f\u20e3 \u0642\u0631\u0627\u0631\u0627\u062a \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 (\u0633\u0646\u0648\u064a\u0629):\n   \u2022 \u0625\u062f\u062e\u0627\u0644 \u0644\u0642\u0627\u062d\u0627\u062a \u062c\u062f\u064a\u062f\u0629\n   \u2022 \u062a\u063a\u064a\u064a\u0631 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u062a\u0646\u0641\u064a\u0630\n   \u2022 \u0634\u0631\u0627\u0643\u0627\u062a \u062c\u062f\u064a\u062f\u0629\n\n\ud83d\udccb \u0623\u062f\u0648\u0627\u062a \u062f\u0639\u0645 \u0627\u0644\u0642\u0631\u0627\u0631:\n\u2022 \u0644\u0648\u062d\u0627\u062a \u0645\u0639\u0644\u0648\u0645\u0627\u062a DHIS2\n\u2022 \u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u0631\u0635\u062f \u0627\u0644\u062f\u0648\u0631\u064a\n\u2022 \u062e\u0631\u0627\u0626\u0637 \u0627\u0644\u062a\u063a\u0637\u064a\u0629\n\u2022 \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0641\u062c\u0648\u0627\u062a (Gap Analysis)\n\n\ud83d\udca1 \u0627\u0644\u0642\u0631\u0627\u0631 \u0627\u0644\u062c\u064a\u062f = \u0628\u064a\u0627\u0646\u0627\u062a + \u062a\u062d\u0644\u064a\u0644 + \u062d\u0643\u0645\u0629!","\ud83d\udd0d \u0627\u0644\u0625\u0634\u0631\u0627\u0641 \u0627\u0644\u062f\u0627\u0639\u0645 \u0644\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0648\u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629:\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 \u0627\u0644\u0625\u0634\u0631\u0627\u0641 \u0627\u0644\u062f\u0627\u0639\u0645\u061f\n\u0647\u0648 \u0639\u0645\u0644\u064a\u0629 \u0645\u0646\u062a\u0638\u0645\u0629 \u062a\u0647\u062f\u0641 \u0625\u0644\u0649 \u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0639\u0627\u0645\u0644\u064a\u0646 \u0627\u0644\u0635\u062d\u064a\u064a\u0646 \u0639\u0644\u0649 \u062a\u062d\u0633\u064a\u0646 \u0623\u062f\u0627\u0626\u0647\u0645 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0648\u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0648\u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0628\u0646\u0627\u0621\u0629\u060c \u0648\u0644\u064a\u0633 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 \u0623\u0648 \u0627\u0644\u0639\u0642\u0627\u0628.\n\n\ud83c\udfaf \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \u0627\u0644\u0625\u0634\u0631\u0627\u0641 \u0627\u0644\u062f\u0627\u0639\u0645 \u0648\u0627\u0644\u062a\u0641\u062a\u064a\u0634:\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 \u0627\u0644\u0645\u0639\u064a\u0627\u0631           \u2502 \u0627\u0644\u0625\u0634\u0631\u0627\u0641 \u0627\u0644\u062f\u0627\u0639\u0645       \u2502 \u0627\u0644\u062a\u0641\u062a\u064a\u0634              \u2502\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\n\u2502 \u0627\u0644\u0647\u062f\u0641            \u2502 \u0627\u0644\u062a\u062d\u0633\u064a\u0646 \u0648\u0627\u0644\u062a\u0637\u0648\u064a\u0631     \u2502 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 \u0648\u0627\u0644\u0639\u0642\u0627\u0628     \u2502\n\u2502 \u0627\u0644\u0639\u0644\u0627\u0642\u0629           \u2502 \u0634\u0631\u0627\u0643\u0629 \u0648\u062a\u0639\u0627\u0648\u0646        \u2502 \u0633\u0644\u0637\u0629 \u0648\u0633\u064a\u0637\u0631\u0629         \u2502\n\u2502 \u0627\u0644\u0623\u0633\u0644\u0648\u0628          \u2502 \u062a\u0634\u062c\u064a\u0639 \u0648\u062a\u0648\u062c\u064a\u0647        \u2502 \u0644\u0648\u0645 \u0648\u062a\u0647\u062f\u064a\u062f          \u2502\n\u2502 \u0627\u0644\u0646\u062a\u064a\u062c\u0629           \u2502 \u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0623\u062f\u0627\u0621         \u2502 \u0625\u062d\u0628\u0627\u0637 \u0627\u0644\u0639\u0627\u0645\u0644\u064a\u0646      \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n\ud83d\udccb \u0641\u0648\u0627\u0626\u062f \u0627\u0644\u0625\u0634\u0631\u0627\u0641 \u0627\u0644\u062f\u0627\u0639\u0645:\n\u2022 \u0631\u0641\u0639 \u062c\u0648\u062f\u0629 \u062e\u062f\u0645\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\u2022 \u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u062a\u0637\u0639\u064a\u0645\u064a\u0629\n\u2022 \u062a\u0639\u0632\u064a\u0632 \u062b\u0642\u0629 \u0627\u0644\u0639\u0627\u0645\u0644\u064a\u0646 \u0628\u0623\u0646\u0641\u0633\u0647\u0645\n\u2022 \u0627\u0643\u062a\u0634\u0627\u0641 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0648\u0645\u0639\u0627\u0644\u062c\u062a\u0647\u0627 \u0645\u0628\u0643\u0631\u0627\u064b\n\u2022 \u0636\u0645\u0627\u0646 \u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u0627\u0644\u0623\u0637\u0641\u0627\u0644\n\n\ud83d\udca1 \u0627\u0644\u0625\u0634\u0631\u0627\u0641 \u0627\u0644\u062f\u0627\u0639\u0645 = \u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0641\u064a \u0627\u0644\u062c\u0648\u062f\u0629!","\ud83d\ude97 \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0625\u0634\u0631\u0627\u0641\u064a\u0629 \u0627\u0644\u062f\u0627\u0639\u0645\u0629 \u2014 \u062f\u0644\u064a\u0644 \u0639\u0645\u0644\u064a:\n\n\ud83d\udccc \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0632\u064a\u0627\u0631\u0627\u062a \u0642\u0628\u0644 \u0627\u0644\u062a\u0646\u0641\u064a\u0630 (Pre-implementation):\n   \u2022 \u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u062c\u0627\u0647\u0632\u064a\u0629 \u0627\u0644\u0645\u0631\u0641\u0642\n   \u2022 \u062a\u0648\u0641\u0631 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u0627\u0644\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a\n   \u2022 \u0633\u0644\u0627\u0645\u0629 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n   \u2022 \u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0639\u0627\u0645\u0644\u064a\u0646 \u0627\u0644\u062c\u062f\u062f\n\n2\ufe0f\u20e3 \u0632\u064a\u0627\u0631\u0627\u062a \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062a\u0646\u0641\u064a\u0630 (During implementation):\n   \u2022 \u0645\u0644\u0627\u062d\u0638\u0629 \u0623\u062f\u0627\u0621 \u0627\u0644\u0639\u0627\u0645\u0644\u064a\u0646\n   \u2022 \u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0627\u062a \u0627\u0644\u0635\u062d\u064a\u062d\u0629\n   \u2022 \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0639\u0645\u0644\n   \u2022 \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a \u0627\u0644\u0641\u0648\u0631\u064a\u0629\n\n3\ufe0f\u20e3 \u0632\u064a\u0627\u0631\u0627\u062a \u0628\u0639\u062f \u0627\u0644\u062a\u0646\u0641\u064a\u0630 (Post-implementation):\n   \u2022 \u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631\n   \u2022 \u062a\u0642\u064a\u064a\u0645 \u0623\u062b\u0631 \u0627\u0644\u062a\u062f\u062e\u0644\u0627\u062a \u0627\u0644\u0633\u0627\u0628\u0642\u0629\n   \u2022 \u0645\u062a\u0627\u0628\u0639\u0629 \u062e\u0637\u0629 \u0627\u0644\u062a\u062d\u0633\u064a\u0646\n\n\ud83d\udcca \u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a:\n\u2022 \u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u0630\u0627\u062a \u0627\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u062c\u064a\u062f: \u0645\u0631\u0629 \u0643\u0644 3 \u0623\u0634\u0647\u0631\n\u2022 \u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u0627\u0644\u0645\u062a\u0648\u0633\u0637\u0629: \u0645\u0631\u0629 \u0634\u0647\u0631\u064a\u0627\u064b\n\u2022 \u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u0636\u0639\u064a\u0641\u0629 \u0627\u0644\u0623\u062f\u0627\u0621: \u0645\u0631\u0629 \u0643\u0644 \u0623\u0633\u0628\u0648\u0639\u064a\u0646\n\n\ud83d\udca1 \u0627\u0644\u0632\u064a\u0627\u0631\u0629 \u063a\u064a\u0631 \u0627\u0644\u0645\u0639\u0644\u0646\u0629 \u062a\u0639\u0643\u0633 \u0627\u0644\u0648\u0627\u0642\u0639 \u0627\u0644\u062d\u0642\u064a\u0642\u064a!","\u2611\ufe0f \u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0625\u0634\u0631\u0627\u0641\u064a\u0629 (Supervision Checklist):\n\n\ud83d\udccc \u0645\u062d\u0627\u0648\u0631 \u0627\u0644\u0642\u0627\u0626\u0645\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f:\n   \u25a1 \u062f\u0631\u062c\u0629 \u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u062b\u0644\u0627\u062c\u0629 2-8\xb0\u0645\u061f\n   \u25a1 \u0633\u062c\u0644 \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u064a\u064f\u062d\u062f\u0651\u062b \u0645\u0631\u062a\u064a\u0646 \u064a\u0648\u0645\u064a\u0627\u064b\u061f\n   \u25a1 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0645\u0631\u062a\u0628\u0629 \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d\u061f\n   \u25a1 VVM \u0644\u0643\u0644 \u0639\u0628\u0648\u0629 \u0641\u064f\u062d\u0635\u061f\n   \u25a1 \u0644\u0627 \u062a\u0648\u062c\u062f \u0644\u0642\u0627\u062d\u0627\u062a \u0645\u062a\u062c\u0645\u062f\u0629 \u0623\u0648 \u0645\u0646\u062a\u0647\u064a\u0629 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629\u061f\n\n2\ufe0f\u20e3 \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u062c\u0644\u0633\u0627\u062a:\n   \u25a1 \u062c\u062f\u0648\u0644 \u0627\u0644\u062c\u0644\u0633\u0627\u062a \u0645\u0639\u0644\u0646 \u0648\u0645\u064f\u0644\u062a\u0632\u0645 \u0628\u0647\u061f\n   \u25a1 \u062c\u0645\u064a\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0645\u062a\u0648\u0641\u0631\u0629\u061f\n   \u25a1 \u0627\u0644\u0645\u062d\u0627\u0642\u0646 ADS \u0645\u062a\u0648\u0641\u0631\u0629\u061f\n   \u25a1 \u0628\u0637\u0627\u0642\u0627\u062a \u0627\u0644\u062a\u0637\u0639\u064a\u0645 \u0645\u062a\u0648\u0641\u0631\u0629\u061f\n\n3\ufe0f\u20e3 \u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u062d\u0642\u0646:\n   \u25a1 \u063a\u0633\u0644 \u0627\u0644\u064a\u062f\u064a\u0646 \u0642\u0628\u0644 \u0627\u0644\u0625\u0639\u0637\u0627\u0621\u061f\n   \u25a1 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u062d\u0642\u0646\u0629 \u062c\u062f\u064a\u062f\u0629 \u0644\u0643\u0644 \u0637\u0641\u0644\u061f\n   \u25a1 \u0639\u062f\u0645 \u0625\u0639\u0627\u062f\u0629 \u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0625\u0628\u0631\u061f\n   \u25a1 \u062d\u0646\u0627\u062f\u064a\u0642 \u0627\u0644\u0623\u0645\u0627\u0646 \u0645\u062a\u0648\u0641\u0631\u0629 \u0648\u0644\u0645 \u062a\u0645\u0644\u0623 \u0623\u0643\u062b\u0631 \u0645\u0646 3/4\u061f\n\n4\ufe0f\u20e3 \u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a:\n   \u25a1 \u0633\u062c\u0644 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0645\u062d\u062f\u0651\u062b\u061f\n   \u25a1 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0645\u062a\u0637\u0627\u0628\u0642\u0629 \u0645\u0639 DHIS2\u061f\n   \u25a1 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u0648\u0646 \u0645\u064f\u062a\u062a\u0628\u0639\u0648\u0646\u061f\n\n5\ufe0f\u20e3 AEFI:\n   \u25a1 \u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0645\u062a\u0648\u0641\u0631\u061f\n   \u25a1 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0645\u064f\u0633\u062c\u0644\u0629 \u0648\u0645\u064f\u0628\u0644\u063a \u0639\u0646\u0647\u0627\u061f\n\n\ud83d\udca1 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0623\u062f\u0627\u0629 \u0648\u0644\u064a\u0633\u062a \u0647\u062f\u0641\u0627\u064b \u2014 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0645\u0633\u062a\u0645\u0631!",'\ud83d\udcac \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0628\u0646\u0627\u0621\u0629 \u0641\u064a \u0627\u0644\u0625\u0634\u0631\u0627\u0641 \u0627\u0644\u062f\u0627\u0639\u0645:\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0628\u0646\u0627\u0621\u0629\u061f\n\u0647\u064a \u0639\u0645\u0644\u064a\u0629 \u0646\u0642\u0644 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0644\u0644\u0639\u0627\u0645\u0644 \u0627\u0644\u0635\u062d\u064a \u062d\u0648\u0644 \u0623\u062f\u0627\u0626\u0647 \u0628\u0637\u0631\u064a\u0642\u0629 \u0625\u064a\u062c\u0627\u0628\u064a\u0629 \u062a\u064f\u0634\u062c\u0639 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0633\u064a\u0646 \u0648\u0644\u064a\u0633 \u0627\u0644\u0625\u062d\u0628\u0627\u0637.\n\n\ud83c\udfaf \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0641\u0639\u0627\u0644\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0641\u0648\u0631\u064a\u0629: \u0642\u062f\u0651\u0645 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0641\u0648\u0631 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629\n2\ufe0f\u20e3 \u0645\u062d\u062f\u062f\u0629: \u0627\u0630\u0643\u0631 \u0627\u0644\u0646\u0642\u0637\u0629 \u0628\u0627\u0644\u0636\u0628\u0637 (\u0644\u064a\u0633 "\u0639\u0645\u0644\u0643 \u0633\u064a\u0621")\n3\ufe0f\u20e3 \u0628\u0646\u0627\u0621\u0629: \u0642\u062f\u0651\u0645 \u0627\u0644\u062d\u0644 \u0645\u0639 \u0627\u0644\u0645\u0634\u0643\u0644\u0629\n4\ufe0f\u20e3 \u0645\u062a\u0648\u0627\u0632\u0646\u0629: \u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0625\u064a\u062c\u0627\u0628\u064a \u062b\u0645 \u0627\u0644\u0633\u0644\u0628\u064a \u062b\u0645 \u0627\u0644\u062d\u0644\n5\ufe0f\u20e3 \u0627\u062d\u062a\u0631\u0627\u0645\u064a\u0629: \u0644\u0627 \u062a\u064f\u0647\u064a\u0646 \u0623\u0648 \u062a\u064f\u062d\u0631\u062c \u0623\u0645\u0627\u0645 \u0627\u0644\u0622\u062e\u0631\u064a\u0646\n\n\ud83d\udccb \u0646\u0645\u0648\u0630\u062c \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2705 \u0645\u0627 \u064a\u064f\u0639\u0645\u0644 \u0628\u0634\u0643\u0644 \u062c\u064a\u062f: "\u0645\u0645\u062a\u0627\u0632 \u0641\u064a \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a"\n\u26a0\ufe0f \u0645\u0627 \u064a\u062d\u062a\u0627\u062c \u062a\u062d\u0633\u064a\u0646: "\u0644\u0643\u0646 \u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0641\u064a \u0627\u0644\u062b\u0644\u0627\u062c\u0629 \u064a\u062d\u062a\u0627\u062c \u0645\u0631\u0627\u062c\u0639\u0629"\n\ud83d\udca1 \u0627\u0644\u062a\u0648\u0635\u064a\u0629: "\u0631\u062a\u0628 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u062d\u0633\u0628 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0627\u0646\u062a\u0647\u0627\u0621 \u2014 \u0627\u0644\u0623\u0642\u0631\u0628 \u0641\u064a \u0627\u0644\u0645\u0642\u062f\u0645\u0629"\n\ud83d\udcc5 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629: "\u0633\u0623\u0631\u0627\u062c\u0639 \u0630\u0644\u0643 \u0641\u064a \u0627\u0644\u0632\u064a\u0627\u0631\u0629 \u0627\u0644\u0642\u0627\u062f\u0645\u0629"\n\n\ud83d\udeab \u0623\u062e\u0637\u0627\u0621 \u0634\u0627\u0626\u0639\u0629:\n\u2022 \u062a\u0642\u062f\u064a\u0645 \u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0633\u0644\u0628\u064a\u0629 \u0641\u0642\u0637\n\u2022 \u0627\u0646\u062a\u0642\u0627\u062f \u0623\u0645\u0627\u0645 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u064a\u0646\n\u2022 \u0639\u062f\u0645 \u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u062a\u062d\u0633\u064a\u0646\u0627\u062a\n\n\ud83d\udca1 \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u062c\u064a\u062f\u0629 \u062a\u064f\u062d\u0641\u0651\u0632 \u0644\u0627 \u062a\u064f\u062b\u0628\u0650\u0637!',"\ud83d\udcc8 \u062e\u0637\u0629 \u0627\u0644\u062a\u062d\u0633\u064a\u0646 (Improvement Plan):\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a \u062e\u0637\u0629 \u0627\u0644\u062a\u062d\u0633\u064a\u0646\u061f\n\u0648\u062b\u064a\u0642\u0629 \u062a\u064f\u0639\u062f \u0628\u0639\u062f \u0643\u0644 \u0632\u064a\u0627\u0631\u0629 \u0625\u0634\u0631\u0627\u0641\u064a\u0629\u060c \u062a\u062d\u062f\u062f \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a \u0627\u0644\u0645\u0643\u062a\u0634\u0641\u0629 \u0648\u0627\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u062a\u0635\u062d\u064a\u062d\u064a\u0629 \u0648\u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0627\u062a \u0648\u0627\u0644\u062c\u062f\u0648\u0644 \u0627\u0644\u0632\u0645\u0646\u064a.\n\n\ud83d\udccb \u0645\u0643\u0648\u0646\u0627\u062a \u062e\u0637\u0629 \u0627\u0644\u062a\u062d\u0633\u064a\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 \u0627\u0644\u0645\u0634\u0643\u0644\u0629    \u2502 \u0627\u0644\u0625\u062c\u0631\u0627\u0621      \u2502 \u0627\u0644\u0645\u0633\u0624\u0648\u0644      \u2502 \u0627\u0644\u0645\u0648\u0639\u062f       \u2502\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\n\u2502 \u062d\u0631\u0627\u0631\u0629      \u2502 \u0635\u064a\u0627\u0646\u0629        \u2502 \u0641\u0646\u064a \u0627\u0644\u062a\u0628\u0631\u064a\u062f  \u2502 \u062e\u0644\u0627\u0644 \u0623\u0633\u0628\u0648\u0639   \u2502\n\u2502 \u0627\u0644\u062b\u0644\u0627\u062c\u0629    \u2502 \u0627\u0644\u062b\u0644\u0627\u062c\u0629      \u2502              \u2502              \u2502\n\u2502 \u0645\u0631\u062a\u0641\u0639\u0629     \u2502              \u2502              \u2502              \u2502\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\n\u2502 \u062a\u0633\u062c\u064a\u0644     \u2502 \u062a\u062f\u0631\u064a\u0628       \u2502 \u0627\u0644\u0645\u0634\u0631\u0641       \u2502 \u0641\u0648\u0631\u064a         \u2502\n\u2502 \u063a\u064a\u0631 \u0645\u0643\u062a\u0645\u0644 \u2502 \u0627\u0644\u0645\u0643\u0644\u0641      \u2502 \u0627\u0644\u0645\u062d\u0644\u064a       \u2502              \u2502\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\n\u2502 \u0647\u062f\u0631 \u0645\u0631\u062a\u0641\u0639 \u2502 \u062a\u0637\u0628\u064a\u0642 \u0633\u064a\u0627\u0633\u0629 \u2502 \u0627\u0644\u0645\u0645\u0631\u0636\u0629      \u2502 \u062e\u0644\u0627\u0644 \u0634\u0647\u0631     \u2502\n\u2502 \u0641\u064a BCG    \u2502 \u0627\u0644\u0642\u0627\u0631\u0648\u0631\u0629     \u2502              \u2502              \u2502\n\u2502           \u2502 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629     \u2502              \u2502              \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n\ud83c\udfaf \u0645\u0628\u0627\u062f\u0626 \u062e\u0637\u0629 \u0627\u0644\u062a\u062d\u0633\u064a\u0646:\n\u2022 \u0645\u062d\u062f\u062f\u0629 \u0648\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0642\u064a\u0627\u0633\n\u2022 \u0648\u0627\u0642\u0639\u064a\u0629 \u0648\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062a\u0646\u0641\u064a\u0630\n\u2022 \u0645\u062d\u062f\u062f\u0629 \u0628\u062c\u062f\u0648\u0644 \u0632\u0645\u0646\u064a\n\u2022 \u0645\u062d\u062f\u062f\u0629 \u0628\u0645\u0633\u0624\u0648\u0644\n\u2022 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0645\u062a\u0627\u0628\u0639\u0629 \u0648\u0627\u0644\u062a\u0642\u064a\u064a\u0645\n\n\ud83d\udca1 \u062e\u0637\u0629 \u0628\u062f\u0648\u0646 \u0645\u062a\u0627\u0628\u0639\u0629 = \u062d\u0628\u0631 \u0639\u0644\u0649 \u0648\u0631\u0642!","\ud83d\ude90 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u062f\u0644\u064a\u0644 \u0634\u0627\u0645\u0644:\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646\u061f\n\u0623\u0646\u0634\u0637\u0629 \u062a\u062d\u0635\u064a\u0646 \u062a\u0643\u0645\u064a\u0644\u064a\u0629 \u062a\u064f\u0646\u0641\u0630 \u062e\u0627\u0631\u062c \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0631\u0648\u062a\u064a\u0646\u064a \u0628\u0647\u062f\u0641 \u062a\u062d\u0642\u064a\u0642 \u062a\u063a\u0637\u064a\u0629 \u0639\u0627\u0644\u064a\u0629 \u062e\u0644\u0627\u0644 \u0641\u062a\u0631\u0629 \u0642\u0635\u064a\u0631\u0629\u060c \u0623\u0648 \u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0644\u0648\u0628\u0627\u0621\u060c \u0623\u0648 \u0644\u0644\u0642\u0636\u0627\u0621 \u0639\u0644\u0649 \u0645\u0631\u0636 \u0645\u0639\u064a\u0646.\n\n\ud83c\udfaf \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062d\u0645\u0644\u0627\u062a:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0648\u0637\u0646\u064a\u0629 (NIDs):\n   \u2022 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0627\u062a\n   \u2022 \u062a\u0633\u062a\u0647\u062f\u0641 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0641\u064a \u0627\u0644\u0641\u0626\u0629 \u0627\u0644\u0639\u0645\u0631\u064a\u0629 \u0627\u0644\u0645\u062d\u062f\u062f\u0629\n   \u2022 \u0645\u062b\u0627\u0644: \u062d\u0645\u0644\u0627\u062a \u0634\u0644\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0648\u0637\u0646\u064a\u0629\n\n2\ufe0f\u20e3 \u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0625\u0642\u0644\u064a\u0645\u064a\u0629 (SNIDs):\n   \u2022 \u0641\u064a \u0645\u062d\u0627\u0641\u0638\u0627\u062a \u0645\u062d\u062f\u062f\u0629 \u0641\u0642\u0637\n   \u2022 \u062a\u0633\u062a\u0647\u062f\u0641 \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0639\u0627\u0644\u064a\u0629 \u0627\u0644\u0645\u062e\u0627\u0637\u0631\n   \u2022 \u0645\u062b\u0627\u0644: \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062d\u0635\u0628\u0629 \u0641\u064a \u0645\u062d\u0627\u0641\u0638\u0627\u062a \u0645\u0639\u064a\u0646\u0629\n\n3\ufe0f\u20e3 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u0646\u0634\u064a\u0637 (Catch-up):\n   \u2022 \u0644\u062a\u0639\u0648\u064a\u0636 \u0627\u0644\u062a\u0623\u062e\u0631 \u0628\u0633\u0628\u0628 \u062c\u0627\u0626\u062d\u0629 \u0643\u0648\u0631\u0648\u0646\u0627 \u0623\u0648 \u0627\u0644\u0646\u0632\u0627\u0639\u0627\u062a\n   \u2022 \u062a\u0633\u062a\u0647\u062f\u0641 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u064a\u0646 \u0639\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\n4\ufe0f\u20e3 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0644\u0644\u0623\u0648\u0628\u0626\u0629:\n   \u2022 \u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0633\u0631\u064a\u0639\u0629 \u0644\u062a\u0641\u0634\u064a \u0645\u0631\u0636\n   \u2022 \u062a\u062d\u0635\u064a\u0646 \u062d\u0644\u0642\u064a \u062d\u0648\u0644 \u062d\u0627\u0644\u0629 \u0645\u0624\u0643\u062f\u0629\n\n\ud83d\udcca \u062e\u0637\u0648\u0627\u062a \u0627\u0644\u062a\u062e\u0637\u064a\u0637:\n1. \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0648\u0627\u0644\u0641\u0626\u0629 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629\n2. \u062a\u0642\u062f\u064a\u0631 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c \u0645\u0646 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a\n3. \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0648\u0627\u0644\u0641\u0631\u0642\n4. \u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0643\u0648\u0627\u062f\u0631\n5. \u0627\u0644\u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629\n6. \u0627\u0644\u062a\u0646\u0641\u064a\u0630 \u0648\u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629\n7. \u0627\u0644\u062a\u0642\u064a\u064a\u0645 \u0648\u0627\u0644\u062a\u0642\u0631\u064a\u0631","\ud83c\uddfe\ud83c\uddea \u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0648\u0637\u0646\u064a\u0629 (NIDs):\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a NIDs\u061f\nNational Immunization Days \u2014 \u062d\u0645\u0644\u0627\u062a \u0648\u0637\u0646\u064a\u0629 \u0634\u0627\u0645\u0644\u0629 \u062a\u0633\u062a\u0647\u062f\u0641 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0641\u064a \u0641\u0626\u0629 \u0639\u0645\u0631\u064a\u0629 \u0645\u062d\u062f\u062f\u0629 \u062e\u0644\u0627\u0644 \u0623\u064a\u0627\u0645 \u0645\u062d\u062f\u062f\u0629\u060c \u0628\u0647\u062f\u0641 \u0627\u0644\u0642\u0636\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0623\u0648 \u0631\u0641\u0639 \u0627\u0644\u062a\u063a\u0637\u064a\u0629.\n\n\ud83c\udfaf \u0623\u0647\u062f\u0627\u0641 NIDs:\n\u2022 \u0642\u0637\u0639 \u0633\u0644\u0633\u0644\u0629 \u0627\u0646\u062a\u0642\u0627\u0644 \u0627\u0644\u0641\u064a\u0631\u0648\u0633 (\u0634\u0644\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644)\n\u2022 \u0631\u0641\u0639 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0641\u0648\u0642 95% \u0641\u064a \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0627\u062a\n\u2022 \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0623\u0637\u0641\u0627\u0644 \u063a\u064a\u0631\u0627\u0644\u0645\u063a\u0637\u064a\u0646 \u0628\u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0631\u0648\u062a\u064a\u0646\u064a\n\u2022 \u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u0645\u0646\u0627\u0639\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629\n\n\ud83d\udccb \u062e\u0637\u0648\u0627\u062a \u0627\u0644\u062a\u0646\u0641\u064a\u0630:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u062d\u0645\u0644\u0629 (4-6 \u0623\u0633\u0627\u0628\u064a\u0639):\n   \u2022 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u062a\u0642\u062f\u064a\u0631 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c\n   \u2022 \u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0641\u0631\u0642 (\u0645\u0626\u0627\u062a \u0627\u0644\u0641\u0631\u0642)\n   \u2022 \u0627\u0644\u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629 (\u0625\u0639\u0644\u0627\u0646\u0627\u062a\u060c \u0645\u0633\u0627\u062c\u062f)\n   \u2022 \u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u0627\u0644\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a\n\n2\ufe0f\u20e3 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062d\u0645\u0644\u0629 (3-5 \u0623\u064a\u0627\u0645):\n   \u2022 \u0641\u0631\u0642 \u062b\u0627\u0628\u062a\u0629 \u0641\u064a \u0627\u0644\u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u0635\u062d\u064a\u0629\n   \u2022 \u0641\u0631\u0642 \u0645\u062a\u0646\u0642\u0644\u0629 \u0645\u0646 \u0628\u064a\u062a \u0644\u0628\u064a\u062a\n   \u2022 \u0645\u0631\u0627\u0642\u0628\u0648 \u0645\u0633\u062a\u0642\u0644\u0648\u0646 (Independent Monitors)\n   \u2022 \u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u064a\u0648\u0645\u064a\u0627\u064b\n\n3\ufe0f\u20e3 \u0628\u0639\u062f \u0627\u0644\u062d\u0645\u0644\u0629:\n   \u2022 \u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629\n   \u2022 \u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 (LQAS)\n   \u2022 \u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0646\u0638\u064a\u0641 (Mop-up)\n   \u2022 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u0646\u0647\u0627\u0626\u064a","\ud83d\udea8 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0644\u0644\u0623\u0648\u0628\u0626\u0629 (Outbreak Response):\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629\u061f\n\u062d\u0645\u0644\u0627\u062a \u062a\u062d\u0635\u064a\u0646 \u0633\u0631\u064a\u0639\u0629 \u062a\u064f\u0646\u0641\u0630 \u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0644\u062a\u0641\u0634\u064a \u0645\u0631\u0636 \u0642\u0627\u0628\u0644 \u0644\u0644\u0648\u0642\u0627\u064a\u0629 \u0628\u0627\u0644\u062a\u062d\u0635\u064a\u0646\u060c \u0628\u0647\u062f\u0641 \u0627\u062d\u062a\u0648\u0627\u0621 \u0627\u0644\u0648\u0628\u0627\u0621 \u0648\u0645\u0646\u0639 \u0627\u0646\u062a\u0634\u0627\u0631\u0647.\n\n\ud83c\udfaf \u062e\u0637\u0648\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u0627\u0644\u0648\u0628\u0627\u0621:\n   \u2022 \u062a\u0623\u0643\u064a\u062f \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0645\u062e\u062a\u0628\u0631\u064a\u0627\u064b\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0639\u062f\u062f \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0648\u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0645\u062a\u0623\u062b\u0631\u0629\n   \u2022 \u062a\u0642\u064a\u064a\u0645 \u062e\u0637\u0648\u0631\u0629 \u0627\u0644\u0648\u0636\u0639\n\n2\ufe0f\u20e3 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0633\u0631\u064a\u0639:\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0646\u0637\u0627\u0642 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 (\u062d\u0644\u0642\u064a/\u0645\u0646\u0637\u0642\u0629)\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0641\u0626\u0629 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629\n   \u2022 \u062a\u0648\u0641\u064a\u0631 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u0627\u0644\u0641\u0631\u0642\n   \u2022 \u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0645\u0639 \u0627\u0644\u0634\u0631\u0643\u0627\u0621\n\n3\ufe0f\u20e3 \u0627\u0644\u062a\u0646\u0641\u064a\u0630:\n   \u2022 \u062a\u062d\u0635\u064a\u0646 \u062d\u0644\u0642\u064a (Ring Vaccination) \u062d\u0648\u0644 \u0627\u0644\u062d\u0627\u0644\u0627\u062a\n   \u2022 \u062a\u063a\u0637\u064a\u0629 \u0643\u0627\u0645\u0644\u0629 \u0644\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0645\u062a\u0623\u062b\u0631\u0629\n   \u2022 \u0627\u0644\u062a\u0631\u0635\u062f \u0627\u0644\u0645\u0643\u062b\u0641 \u0644\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062c\u062f\u064a\u062f\u0629\n\n4\ufe0f\u20e3 \u0627\u0644\u062a\u0642\u064a\u064a\u0645:\n   \u2022 \u0645\u0631\u0627\u0642\u0628\u0629 \u0638\u0647\u0648\u0631 \u062d\u0627\u0644\u0627\u062a \u062c\u062f\u064a\u062f\u0629\n   \u2022 \u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0645\u062d\u0642\u0642\u0629\n   \u2022 \u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u062f\u0631\u0648\u0633 \u0627\u0644\u0645\u0633\u062a\u0641\u0627\u062f\u0629\n\n\u26a0\ufe0f \u0627\u0644\u0633\u0631\u0639\u0629 \u0647\u064a \u0627\u0644\u0639\u0627\u0645\u0644 \u0627\u0644\u0623\u0647\u0645 \u0641\u064a \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629!","\ud83d\udce2 \u0627\u0644\u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629 \u0644\u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a \u0627\u0644\u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629\u061f\n\u0647\u064a \u0639\u0645\u0644\u064a\u0629 \u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0627\u0644\u0645\u062d\u0644\u064a \u0648\u0642\u0627\u062f\u0629 \u0627\u0644\u0631\u0623\u064a \u0644\u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u0648\u0639\u064a \u0628\u0623\u0647\u0645\u064a\u0629 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u0625\u0642\u0628\u0627\u0644 \u0639\u0644\u0649 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u0637\u0639\u064a\u0645.\n\n\ud83c\udfaf \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0628\u0626\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u0625\u0639\u0644\u0627\u0645 \u0648\u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a:\n   \u2022 \u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0627\u0644\u0631\u0627\u062f\u064a\u0648 \u0648\u0627\u0644\u062a\u0644\u0641\u0632\u064a\u0648\u0646\n   \u2022 \u0627\u0644\u0645\u0644\u0635\u0642\u0627\u062a \u0648\u0627\u0644\u0644\u0627\u0641\u062a\u0627\u062a \u0641\u064a \u0627\u0644\u0623\u062d\u064a\u0627\u0621\n   \u2022 \u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0646\u0635\u064a\u0629 (SMS)\n   \u2022 \u0627\u0644\u0625\u0639\u0644\u0627\u0646 \u0639\u0628\u0631 \u0645\u0643\u0628\u0631\u0627\u062a \u0627\u0644\u0635\u0648\u062a\n\n2\ufe0f\u20e3 \u0625\u0634\u0631\u0627\u0643 \u0642\u0627\u062f\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639:\n   \u2022 \u0627\u0644\u0645\u0634\u0627\u064a\u062e \u0648\u0627\u0644\u0623\u0626\u0645\u0629 (\u0627\u0644\u062e\u0637\u0628 \u0627\u0644\u062c\u0645\u0639\u0629)\n   \u2022 \u0627\u0644\u0645\u0639\u0644\u0645\u0648\u0646 \u0648\u0627\u0644\u0645\u0639\u0644\u0645\u0627\u062a\n   \u2022 \u0631\u0624\u0633\u0627\u0621 \u0627\u0644\u0623\u062d\u064a\u0627\u0621 \u0648\u0627\u0644\u0642\u0631\u0649\n   \u2022 \u0627\u0644\u0642\u0627\u0628\u0644\u0627\u062a \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a\u0627\u062a\n\n3\ufe0f\u20e3 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629:\n   \u2022 \u0645\u0633\u0631\u062d\u064a\u0627\u062a \u0648\u0645\u0634\u0627\u0647\u062f \u062a\u0648\u0639\u0648\u064a\u0629\n   \u2022 \u0646\u062f\u0648\u0627\u062a \u0648\u0645\u062d\u0627\u0636\u0631\u0627\u062a \u0635\u062d\u064a\u0629\n   \u2022 \u0645\u0633\u0627\u0628\u0642\u0627\u062a \u0644\u0644\u0637\u0644\u0627\u0628 \u0639\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\n4\ufe0f\u20e3 \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u062a\u0631\u062f\u062f\u064a\u0646:\n   \u2022 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0644\u0645\u062e\u0627\u0648\u0641\u0647\u0645 \u0628\u0627\u062d\u062a\u0631\u0627\u0645\n   \u2022 \u062a\u0642\u062f\u064a\u0645 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0639\u0644\u0645\u064a\u0629 \u0645\u0628\u0633\u0637\u0629\n   \u2022 \u0625\u0634\u0631\u0627\u0643 \u0623\u0637\u0628\u0627\u0621 \u0648\u0645\u0634\u0627\u064a\u062e \u0645\u0648\u062b\u0648\u0642\u064a\u0646\n\n\ud83d\udca1 \u0645\u062c\u062a\u0645\u0639 \u0645\u064f\u0639\u0628\u0623 = \u062d\u0645\u0644\u0629 \u0646\u0627\u062c\u062d\u0629 = \u0623\u0637\u0641\u0627\u0644 \u0645\u062d\u0645\u064a\u0648\u0646!","\ud83d\udccb \u062a\u062e\u0637\u064a\u0637 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u062f\u0644\u064a\u0644 \u062e\u0637\u0648\u0629 \u0628\u062e\u0637\u0648\u0629:\n\n\ud83d\udccc \u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u062a\u062e\u0637\u064a\u0637:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0625\u0639\u062f\u0627\u062f (4-6 \u0623\u0633\u0627\u0628\u064a\u0639 \u0642\u0628\u0644):\n   \u2022 \u062a\u0634\u0643\u064a\u0644 \u0644\u062c\u0646\u0629 \u0627\u0644\u062a\u062e\u0637\u064a\u0637\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0648\u0627\u0644\u0641\u0626\u0629 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629\n   \u2022 \u062a\u0642\u062f\u064a\u0631 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c \u0645\u0646 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u0627\u0644\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a\n   \u2022 \u0631\u0633\u0645 \u062e\u0631\u064a\u0637\u0629 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 (Micro-plan)\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0639\u062f\u062f \u0627\u0644\u0641\u0631\u0642 \u0648\u062a\u0648\u0632\u064a\u0639\u0647\u0627\n\n2\ufe0f\u20e3 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 (2-3 \u0623\u0633\u0627\u0628\u064a\u0639 \u0642\u0628\u0644):\n   \u2022 \u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0645\u0634\u0631\u0641\u064a\u0646 \u0648\u0627\u0644\u0641\u0631\u0642\n   \u2022 \u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u064a\u0646 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u064a\u0646\n   \u2022 \u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0645\u062a\u0637\u0648\u0639\u064a\u0646 \u0648\u0627\u0644\u0645\u0639\u0628\u0626\u064a\u0646\n\n3\ufe0f\u20e3 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0639\u0628\u0626\u0629 (1-2 \u0623\u0633\u0628\u0648\u0639 \u0642\u0628\u0644):\n   \u2022 \u0625\u0637\u0644\u0627\u0642 \u0627\u0644\u062d\u0645\u0644\u0629 \u0625\u0639\u0644\u0627\u0645\u064a\u0627\u064b\n   \u2022 \u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u062a\u0648\u0639\u0648\u064a\u0629\n   \u2022 \u0625\u0628\u0644\u0627\u063a \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0628\u0627\u0644\u0645\u0648\u0627\u0639\u064a\u062f \u0648\u0627\u0644\u0623\u0645\u0627\u0643\u0646\n\n4\ufe0f\u20e3 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0648\u0632\u064a\u0639 (3-5 \u0623\u064a\u0627\u0645 \u0642\u0628\u0644):\n   \u2022 \u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u0627\u0644\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a\n   \u2022 \u062a\u0648\u0632\u064a\u0639 \u0646\u0645\u0627\u0630\u062c \u0627\u0644\u062a\u0633\u062c\u064a\u0644\n   \u2022 \u0627\u062e\u062a\u0628\u0627\u0631 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n\n\ud83d\udca1 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062c\u064a\u062f = 80% \u0645\u0646 \u0646\u062c\u0627\u062d \u0627\u0644\u062d\u0645\u0644\u0629!","\u2699\ufe0f \u062a\u0646\u0641\u064a\u0630 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u0627\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u0645\u064a\u062f\u0627\u0646\u064a\u0629:\n\n\ud83d\udccc \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062a\u0646\u0641\u064a\u0630:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0645\u0648\u0642\u0639:\n   \u2022 \u0627\u062e\u062a\u064a\u0627\u0631 \u0645\u0643\u0627\u0646 \u0648\u0627\u0636\u062d \u0648\u0622\u0645\u0646\n   \u2022 \u062a\u0631\u062a\u064a\u0628 \u0645\u062d\u0637\u0627\u062a \u0627\u0644\u0639\u0645\u0644 (\u062a\u0633\u062c\u064a\u0644 \u2190 \u062a\u0637\u0639\u064a\u0645 \u2190 \u0645\u0631\u0627\u0642\u0628\u0629)\n   \u2022 \u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u062a\u0628\u0631\u064a\u062f \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a\n   \u2022 \u062a\u0648\u0641\u064a\u0631 \u0627\u0644\u062a\u0647\u0648\u064a\u0629 \u0648\u0627\u0644\u0638\u0644\n\n2\ufe0f\u20e3 \u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n   \u2022 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0623\u0646 \u0627\u0644\u0637\u0641\u0644 \u0641\u064a \u0627\u0644\u0641\u0626\u0629 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629\n   \u2022 \u0641\u062d\u0635 VVM \u0642\u0628\u0644 \u0643\u0644 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\n   \u2022 \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0644\u0642\u0627\u062d \u0628\u0627\u0644\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629\n   \u2022 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0641\u0648\u0631\u0627\u064b\n   \u2022 \u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0623\u0645 \u0628\u0627\u0644\u0622\u062b\u0627\u0631 \u0627\u0644\u0645\u062a\u0648\u0642\u0639\u0629\n\n3\ufe0f\u20e3 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062d\u0645\u0644\u0629:\n   \u2022 \u0645\u0631\u0627\u0642\u0628\u0648\u0646 \u0645\u0633\u062a\u0642\u0644\u0648\u0646 \u0641\u064a 10% \u0645\u0646 \u0627\u0644\u0645\u0648\u0627\u0642\u0639\n   \u2022 \u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0646\u0647\u0627\u064a\u0629 \u0643\u0644 \u064a\u0648\u0645\n   \u2022 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0639\u0646 \u0623\u064a \u0645\u0634\u0643\u0644\u0627\u062a \u0641\u0648\u0631\u0627\u064b\n   \u2022 \u0645\u062a\u0627\u0628\u0639\u0629 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n\n4\ufe0f\u20e3 \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u064a\u0648\u0645:\n   \u2022 \u0625\u062d\u0635\u0627\u0621 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0645\u0637\u0639\u0645\u064a\u0646\n   \u2022 \u062d\u0633\u0627\u0628 \u0627\u0644\u0628\u0627\u0642\u064a \u0645\u0646 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a\n   \u2022 \u062d\u0641\u0638 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0641\u064a \u0627\u0644\u062b\u0644\u0627\u062c\u0629\n   \u2022 \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u064a\u0648\u0645\u064a","\ud83d\udc41\ufe0f \u0645\u0631\u0627\u0642\u0628\u0629 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u062f\u0644\u064a\u0644 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u064a\u0646:\n\n\ud83d\udccc \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629:\n   \u2022 \u064a\u0642\u0648\u0645 \u0628\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0641\u0648\u0646 \u0648\u0627\u0644\u0645\u0646\u0633\u0642\u0648\u0646\n   \u2022 \u062a\u063a\u0637\u064a \u062c\u0645\u064a\u0639 \u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u062d\u0645\u0644\u0629\n   \u2022 \u0645\u0633\u062a\u0645\u0631\u0629 \u0637\u0648\u0627\u0644 \u0641\u062a\u0631\u0629 \u0627\u0644\u062d\u0645\u0644\u0629\n\n2\ufe0f\u20e3 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629:\n   \u2022 \u064a\u0642\u0648\u0645 \u0628\u0647\u0627 \u0645\u0631\u0627\u0642\u0628\u0648\u0646 \u0645\u0646 \u062e\u0627\u0631\u062c \u0627\u0644\u0641\u0631\u0642\n   \u2022 \u0641\u064a 10% \u0645\u0646 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0639\u0634\u0648\u0627\u0626\u064a\u0627\u064b\n   \u2022 \u062a\u0642\u064a\u064a\u0645 \u062c\u0648\u062f\u0629 \u0627\u0644\u062a\u0646\u0641\u064a\u0630\n\n3\ufe0f\u20e3 \u0645\u0631\u0627\u0642\u0628\u0629 \u0645\u0627 \u0628\u0639\u062f \u0627\u0644\u062d\u0645\u0644\u0629 (LQAS):\n   \u2022 Lot Quality Assurance Sampling\n   \u2022 \u0639\u064a\u0646\u0629 \u0639\u0634\u0648\u0627\u0626\u064a\u0629 \u0645\u0646 \u0627\u0644\u0623\u0633\u0631\n   \u2022 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0641\u0639\u0644\u064a\u0629\n\n\ud83d\udccb \u0645\u0627\u0630\u0627 \u064a\u0631\u0627\u0642\u0628 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u061f\n\u2022 \u0637\u0631\u064a\u0642\u0629 \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0644\u0642\u0627\u062d \u0635\u062d\u064a\u062d\u0629\u061f\n\u2022 VVM \u064a\u064f\u0641\u062d\u0635 \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645\u061f\n\u2022 \u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u062f\u0642\u064a\u0642\u061f\n\u2022 \u062d\u0646\u0627\u062f\u064a\u0642 \u0627\u0644\u0623\u0645\u0627\u0646 \u062a\u064f\u0633\u062a\u062e\u062f\u0645\u061f\n\u2022 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0645\u064f\u0628\u0644\u0651\u063a \u0628\u0627\u0644\u0645\u0648\u0627\u0639\u064a\u062f\u061f\n\n\ud83d\udca1 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 = \u0636\u0645\u0627\u0646 \u0627\u0644\u062c\u0648\u062f\u0629 \u0648\u0627\u0644\u0645\u0635\u062f\u0627\u0642\u064a\u0629!","\ud83d\udcca \u062a\u0642\u064a\u064a\u0645 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u0645\u0624\u0634\u0631\u0627\u062a \u0648\u062f\u0631\u0648\u0633:\n\n\ud83d\udccc \u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u062a\u0642\u064a\u064a\u0645:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u062a\u063a\u0637\u064a\u0629:\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0625\u062f\u0627\u0631\u064a\u0629 (\u0627\u0644\u0645\u0637\u0639\u0645\u064a\u0646 \xf7 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646 \xd7 100)\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0645\u0646 \u0645\u0633\u062d LQAS\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u0645\u0646\u0627\u0632\u0644 \u0627\u0644\u0645\u063a\u0637\u0627\u0629 (\u0641\u064a \u062d\u0645\u0644\u0627\u062a \u0628\u064a\u062a \u0644\u0628\u064a\u062a)\n\n2\ufe0f\u20e3 \u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u062c\u0648\u062f\u0629:\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u062a\u064a \u0627\u0643\u062a\u0645\u0644\u062a \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u062d\u062f\u062f\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u0641\u0631\u0627\u063a \u0645\u0646 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a (Stock-out)\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u063a\u064a\u0631 \u0627\u0644\u0645\u0637\u0639\u0645\u064a\u0646 \u0631\u063a\u0645 \u0648\u062c\u0648\u062f\u0647\u0645\n   \u2022 \u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0631\u0641\u0636 \u0648\u0639\u062f\u0645 \u0627\u0644\u0642\u0628\u0648\u0644\n\n3\ufe0f\u20e3 \u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u0633\u0644\u0627\u0645\u0629:\n   \u2022 \u062d\u0627\u0644\u0627\u062a AEFI \u0627\u0644\u0645\u0628\u0644\u063a\u0629\n   \u2022 \u062d\u0627\u0644\u0627\u062a \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0644\u0642\u0627\u062d\u0627\u062a \u063a\u064a\u0631 \u0635\u0627\u0644\u062d\u0629\n   \u2022 \u062d\u0648\u0627\u062f\u062b \u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u062d\u0642\u0646\n\n4\ufe0f\u20e3 \u0627\u0644\u062f\u0631\u0648\u0633 \u0627\u0644\u0645\u0633\u062a\u0641\u0627\u062f\u0629:\n   \u2022 \u0645\u0627 \u0646\u062c\u062d \u0648\u0645\u0627 \u0644\u0645 \u064a\u0646\u062c\u062d\n   \u2022 \u0627\u0644\u062a\u062d\u062f\u064a\u0627\u062a \u0648\u0637\u0631\u0642 \u0645\u0639\u0627\u0644\u062c\u062a\u0647\u0627\n   \u2022 \u062a\u0648\u0635\u064a\u0627\u062a \u0644\u0644\u062d\u0645\u0644\u0627\u062a \u0627\u0644\u0642\u0627\u062f\u0645\u0629\n\n\ud83d\udca1 \u0643\u0644 \u062d\u0645\u0644\u0629 \u0647\u064a \u0641\u0631\u0635\u0629 \u0644\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u062a\u062d\u0633\u064a\u0646!","\ud83d\ude91 \u0641\u0631\u0642 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629 (Mobile Teams):\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a \u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629\u061f\n\u0641\u0631\u0642 \u0635\u062d\u064a\u0629 \u0645\u062f\u0631\u0628\u0629 \u062a\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0628\u0639\u064a\u062f\u0629 \u0648\u0627\u0644\u0645\u062d\u0631\u0648\u0645\u0629 \u0627\u0644\u062a\u064a \u0644\u0627 \u062a\u0635\u0644\u0647\u0627 \u062e\u062f\u0645\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0631\u0648\u062a\u064a\u0646\u064a\u0629\u060c \u0644\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062a\u0637\u0639\u064a\u0645\u0627\u062a \u0645\u0628\u0627\u0634\u0631\u0629 \u0644\u0644\u0623\u0637\u0641\u0627\u0644.\n\n\ud83c\udfaf \u0645\u062a\u0649 \u0646\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629\u061f\n\u2022 \u0645\u0646\u0627\u0637\u0642 \u0644\u0627 \u064a\u0648\u062c\u062f \u0641\u064a\u0647\u0627 \u0645\u0631\u0641\u0642 \u0635\u062d\u064a \u062b\u0627\u0628\u062a\n\u2022 \u0642\u0631\u0649 \u062a\u0628\u0639\u062f \u0623\u0643\u062b\u0631 \u0645\u0646 10 \u0643\u0645 \u0639\u0646 \u0623\u0642\u0631\u0628 \u0645\u0631\u0643\u0632\n\u2022 \u0645\u062e\u064a\u0645\u0627\u062a \u0627\u0644\u0646\u0627\u0632\u062d\u064a\u0646\n\u2022 \u0645\u062c\u062a\u0645\u0639\u0627\u062a \u0627\u0644\u0631\u0639\u0627\u0629 \u0627\u0644\u0631\u062d\u0644\n\u2022 \u0645\u0646\u0627\u0637\u0642 \u064a\u0635\u0639\u0628 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647\u0627 \u062c\u063a\u0631\u0627\u0641\u064a\u0627\u064b\n\n\ud83d\udccb \u062a\u0643\u0648\u064a\u0646 \u0627\u0644\u0641\u0631\u064a\u0642:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 \u0645\u064f\u0637\u0639\u0651\u0645 \u0645\u064f\u062f\u0631\u0651\u0628 (2 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644)\n\u2022 \u0645\u064f\u0633\u062c\u0651\u0644 (\u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a)\n\u2022 \u0645\u0639\u0628\u0651\u0626 \u0645\u062c\u062a\u0645\u0639\u064a (\u0645\u062d\u0644\u064a \u0645\u0646 \u0627\u0644\u0645\u0646\u0637\u0642\u0629)\n\u2022 \u0633\u0627\u0626\u0642 (\u0625\u0646 \u0644\u0632\u0645 \u0627\u0644\u0623\u0645\u0631)\n\n\ud83d\udce6 \u0627\u0644\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629:\n\u2022 \u062d\u0627\u0641\u0638\u0627\u062a \u0644\u0642\u0627\u062d \u0645\u0639\u0628\u0623\u0629 \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d\n\u2022 \u0623\u0643\u064a\u0627\u0633 \u062b\u0644\u062c \u0645\u0634\u0631\u0648\u0637\u0629\n\u2022 \u0645\u062d\u0627\u0642\u0646 ADS \u0648\u0633\u0644\u0627\u0645\u0629\n\u2022 \u0646\u0645\u0627\u0630\u062c \u062a\u0633\u062c\u064a\u0644\n\u2022 \u0628\u0637\u0627\u0642\u0627\u062a \u062a\u0637\u0639\u064a\u0645\n\n\ud83d\udca1 \u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629 \u062a\u0635\u0644 \u062d\u064a\u062b \u0644\u0627 \u064a\u0635\u0644 \u0623\u062d\u062f!","\ud83d\udd13 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0642\u0627\u0631\u0648\u0631\u0629 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629 (Open Vial Policy):\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0642\u0627\u0631\u0648\u0631\u0629 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629\u061f\n\u0647\u064a \u0633\u064a\u0627\u0633\u0629 \u062a\u0633\u0645\u062d \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0642\u0648\u0627\u0631\u064a\u0631 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u062f\u062f\u0629 \u0627\u0644\u062c\u0631\u0639\u0627\u062a \u0641\u064a \u062c\u0644\u0633\u0627\u062a \u0644\u0627\u062d\u0642\u0629 \u0625\u0630\u0627 \u062a\u0645 \u0627\u0633\u062a\u064a\u0641\u0627\u0621 \u0634\u0631\u0648\u0637 \u0645\u0639\u064a\u0646\u0629\u060c \u0628\u0647\u062f\u0641 \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u0647\u062f\u0631.\n\n\u2705 \u0644\u0642\u0627\u062d\u0627\u062a \u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u0627 \u0628\u0639\u062f \u0627\u0644\u0641\u062a\u062d (\u062d\u062a\u0649 28 \u064a\u0648\u0645\u0627\u064b):\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 OPV (\u0634\u0644\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0641\u0645\u0648\u064a)\n\u2022 MR (\u0627\u0644\u062d\u0635\u0628\u0629 \u0648\u0627\u0644\u062d\u0635\u0628\u0629 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064a\u0629) \u2728 \u0641\u0642\u0637 \u0625\u0630\u0627 \u0643\u0627\u0646 VVM \u0633\u0644\u064a\u0645\u0627\u064b\n\u2022 PCV (\u0627\u0644\u0645\u0643\u0648\u0631\u0627\u062a \u0627\u0644\u0631\u0626\u0648\u064a\u0629)\n\n\u26a0\ufe0f \u0634\u0631\u0648\u0637 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0641\u064a \u062c\u0644\u0633\u0627\u062a \u0644\u0627\u062d\u0642\u0629:\n   1. VVM \u0641\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 1 \u0623\u0648 2 (\u0644\u0645 \u064a\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u062d\u062f)\n   2. \u0627\u0644\u0644\u0642\u0627\u062d \u0645\u062d\u0641\u0648\u0638 \u0641\u064a \u062f\u0631\u062c\u0629 2-8\xb0\u0645\n   3. \u0644\u0645 \u062a\u0646\u062a\u0647\u0650 \u0635\u0644\u0627\u062d\u064a\u0629 \u0627\u0644\u0644\u0642\u0627\u062d\n   4. \u062a\u0645 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u062d\u0642\u0646\u0629 \u062c\u062f\u064a\u062f\u0629 \u0641\u064a \u0643\u0644 \u062c\u0631\u0639\u0629\n   5. \u0627\u0644\u0642\u0627\u0631\u0648\u0631\u0629 \u0645\u062d\u0641\u0648\u0638\u0629 \u0641\u064a \u0627\u0644\u062b\u0644\u0627\u062c\u0629 \u0628\u064a\u0646 \u0627\u0644\u062c\u0644\u0633\u0627\u062a\n\n\ud83d\udeab \u0644\u0642\u0627\u062d\u0627\u062a \u064a\u062c\u0628 \u0627\u0644\u062a\u062e\u0644\u0635 \u0645\u0646\u0647\u0627 \u0628\u0639\u062f \u0627\u0644\u0641\u062a\u062d (\u062e\u0644\u0627\u0644 6 \u0633\u0627\u0639\u0627\u062a):\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 BCG (\u0627\u0644\u0633\u0644) \u2014 \u0644\u0642\u0627\u062d \u0645\u062c\u0641\u0641 \u064a\u062d\u062a\u0627\u062c \u0625\u0639\u0627\u062f\u0629 \u062a\u062d\u0636\u064a\u0631\n\u2022 Rota (\u0627\u0644\u0631\u0648\u062a\u0627) \u2014 \u0644\u0627 \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0628\u0639\u062f 6 \u0633\u0627\u0639\u0627\u062a\n\u2022 \u0623\u064a \u0644\u0642\u0627\u062d \u0645\u0634\u0643\u0648\u0643 \u0641\u064a \u0633\u0644\u0627\u0645\u062a\u0647\n\n\ud83d\udca1 \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u064a\u0642\u0644\u0644 \u0627\u0644\u0647\u062f\u0631 \u0628\u0646\u0633\u0628\u0629 30-50%!","\ud83e\uddee \u062d\u0633\u0627\u0628 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c \u0645\u0646 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u2014 \u0645\u0639\u0627\u062f\u0644\u0627\u062a \u0648\u0623\u0645\u062b\u0644\u0629:\n\n\ud83d\udccc \u0627\u0644\u0645\u0639\u0627\u062f\u0644\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629:\n\u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c = \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0648\u0646 \xd7 \u0639\u062f\u062f \u0627\u0644\u062c\u0631\u0639\u0627\u062a \xd7 \u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u0647\u062f\u0631\n\n\ud83d\udcca \u0645\u0639\u0627\u0645\u0644\u0627\u062a \u0627\u0644\u0647\u062f\u0631 (Wastage Factor):\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 \u0627\u0644\u0644\u0642\u0627\u062d                     \u2502 \u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u0647\u062f\u0631  \u2502 \u0646\u0633\u0628\u0629 \u0627\u0644\u0647\u062f\u0631   \u2502\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\n\u2502 \u0644\u0642\u0627\u062d\u0627\u062a \u0633\u0627\u0626\u0644\u0629 (Penta,PCV,  \u2502 1.1          \u2502 10%          \u2502\n\u2502 OPV, Rota, IPV, HepB, Td) \u2502              \u2502              \u2502\n\u2502 \u0644\u0642\u0627\u062d\u0627\u062a \u0645\u062c\u0641\u0641\u0629 (BCG, MR)   \u2502 1.5          \u2502 50%          \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n\ud83d\udccb \u0623\u0645\u062b\u0644\u0629 \u062d\u0633\u0627\u0628\u064a\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u0645\u062b\u0627\u0644 1: \u062d\u0633\u0627\u0628 \u0627\u062d\u062a\u064a\u0627\u062c Penta \u0644\u0645\u062f\u064a\u0631\u064a\u0629\n\u2022 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0648\u0646 (\u0631\u0636\u0639): 3,200\n\u2022 \u0639\u062f\u062f \u0627\u0644\u062c\u0631\u0639\u0627\u062a: 3\n\u2022 \u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u0647\u062f\u0631: 1.1\n\u2022 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c = 3,200 \xd7 3 \xd7 1.1 = 10,560 \u062c\u0631\u0639\u0629\n\n\u0645\u062b\u0627\u0644 2: \u062d\u0633\u0627\u0628 \u0627\u062d\u062a\u064a\u0627\u062c BCG\n\u2022 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0648\u0646: 3,200\n\u2022 \u0639\u062f\u062f \u0627\u0644\u062c\u0631\u0639\u0627\u062a: 1\n\u2022 \u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u0647\u062f\u0631: 1.5\n\u2022 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c = 3,200 \xd7 1 \xd7 1.5 = 4,800 \u062c\u0631\u0639\u0629\n\n\u0645\u062b\u0627\u0644 3: \u062d\u0633\u0627\u0628 \u0627\u062d\u062a\u064a\u0627\u062c MR\n\u2022 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0648\u0646: 3,200\n\u2022 \u0639\u062f\u062f \u0627\u0644\u062c\u0631\u0639\u0627\u062a: 2\n\u2022 \u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u0647\u062f\u0631: 1.5\n\u2022 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c = 3,200 \xd7 2 \xd7 1.5 = 9,600 \u062c\u0631\u0639\u0629\n\n\ud83d\udca1 \u0627\u0644\u062f\u0642\u0629 \u0641\u064a \u0627\u0644\u062d\u0633\u0627\u0628 = \u0644\u0627 \u0646\u0641\u0627\u062f \u0648\u0644\u0627 \u0625\u0647\u062f\u0627\u0631!","\ud83d\udcc9 \u062d\u0633\u0627\u0628 \u0647\u062f\u0631 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u062a\u0642\u0644\u064a\u0644\u0647:\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 \u0647\u062f\u0631 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a\u061f\n\u0647\u0648 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \u0643\u0645\u064a\u0629 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0645\u0648\u0632\u0639\u0629 \u0648\u0643\u0645\u064a\u0629 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u0629 \u0641\u0639\u0644\u064a\u0627\u064b \u0644\u0644\u062a\u0637\u0639\u064a\u0645.\n\n\ud83d\udd22 \u0645\u0639\u0627\u062f\u0644\u0629 \u062d\u0633\u0627\u0628 \u0646\u0633\u0628\u0629 \u0627\u0644\u0647\u062f\u0631:\n\u0646\u0633\u0628\u0629 \u0627\u0644\u0647\u062f\u0631 = [(\u0627\u0644\u062c\u0631\u0639\u0627\u062a \u0627\u0644\u0645\u0648\u0632\u0639\u0629 - \u0627\u0644\u062c\u0631\u0639\u0627\u062a \u0627\u0644\u0645\u0639\u0637\u0627\u0629) \xf7 \u0627\u0644\u062c\u0631\u0639\u0627\u062a \u0627\u0644\u0645\u0648\u0632\u0639\u0629] \xd7 100\n\n\ud83d\udcca \u0646\u0633\u0628 \u0627\u0644\u0647\u062f\u0631 \u0627\u0644\u0645\u0642\u0628\u0648\u0644\u0629 (WHO):\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 \u0627\u0644\u0644\u0642\u0627\u062d                     \u2502 \u0627\u0644\u0647\u062f\u0631 \u0627\u0644\u0645\u0642\u0628\u0648\u0644\u2502\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\n\u2502 BCG (10 \u062c\u0631\u0639\u0627\u062a/\u0639\u0628\u0648\u0629)       \u2502 50%          \u2502\n\u2502 MR (10 \u062c\u0631\u0639\u0627\u062a/\u0639\u0628\u0648\u0629)        \u2502 50%          \u2502\n\u2502 Penta (1 \u062c\u0631\u0639\u0629/\u0639\u0628\u0648\u0629 ADS)   \u2502 10%          \u2502\n\u2502 PCV (1 \u062c\u0631\u0639\u0629/\u0639\u0628\u0648\u0629 ADS)     \u2502 10%          \u2502\n\u2502 OPV (10-20 \u062c\u0631\u0639\u0629/\u0639\u0628\u0648\u0629)     \u2502 10%          \u2502\n\u2502 Rota (1-2 \u062c\u0631\u0639\u0629/\u0639\u0628\u0648\u0629)      \u2502 10%          \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n\ud83d\udd0d \u0623\u0633\u0628\u0627\u0628 \u0627\u0644\u0647\u062f\u0631:\n\u2022 \u0641\u062a\u062d \u0639\u0628\u0648\u0627\u062a \u0644\u0639\u062f\u062f \u0642\u0644\u064a\u0644 \u0645\u0646 \u0627\u0644\u0623\u0637\u0641\u0627\u0644\n\u2022 \u0627\u0646\u062a\u0647\u0627\u0621 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629\n\u2022 \u062a\u062c\u0645\u062f \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0623\u0648 \u062a\u0639\u0631\u0636\u0647\u0627 \u0644\u0644\u062d\u0631\u0627\u0631\u0629\n\u2022 VVM \u0648\u0635\u0644 \u0644\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629\n\u2022 \u0639\u062f\u0645 \u062a\u0637\u0628\u064a\u0642 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0642\u0627\u0631\u0648\u0631\u0629 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629\n\n\ud83d\udca1 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u0647\u062f\u0631:\n\u2022 \u062a\u0637\u0628\u064a\u0642 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0642\u0627\u0631\u0648\u0631\u0629 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629\n\u2022 \u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0642\u0628\u0644 \u0641\u062a\u062d \u0639\u0628\u0648\u0629 \u062c\u062f\u064a\u062f\u0629\n\u2022 \u062c\u062f\u0648\u0644\u0629 \u0627\u0644\u062c\u0644\u0633\u0627\u062a \u0644\u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u0625\u0642\u0628\u0627\u0644\n\u2022 \u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u0623\u0633\u0628\u0648\u0639\u064a\u0627\u064b"," freezer \u0623\u0646\u0648\u0627\u0639 \u062b\u0644\u0627\u062c\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u0645\u0639\u062f\u0627\u062a \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f:\n\n\ud83d\udccc \u062a\u0635\u0646\u064a\u0641 \u0627\u0644\u062b\u0644\u0627\u062c\u0627\u062a:\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 \u0627\u0644\u0646\u0648\u0639       \u2502 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645             \u2502 \u0627\u0644\u0633\u0639\u0629        \u2502\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\n\u2502 TZA        \u2502 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0646\u0637\u0642\u0629/\u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629\u2502 \u0643\u0628\u064a\u0631\u0629 \u062c\u062f\u0627\u064b   \u2502\n\u2502 HZA        \u2502 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629        \u2502 \u0643\u0628\u064a\u0631\u0629        \u2502\n\u2502 CZA        \u2502 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0629/\u0627\u0644\u0645\u0631\u0641\u0642 \u2502 \u0645\u062a\u0648\u0633\u0637\u0629       \u2502\n\u2502 RCW        \u2502 \u0635\u0646\u062f\u0648\u0642 \u0646\u0642\u0644 \u0645\u0628\u0631\u062f       \u2502 \u0635\u063a\u064a\u0631\u0629        \u2502\n\u2502 Vaccine    \u2502 \u062d\u0627\u0641\u0638\u0629 \u0644\u0642\u0627\u062d \u0644\u0644\u062a\u0646\u0642\u0644     \u2502 2-4 \u0633\u0627\u0639\u0627\u062a    \u2502\n\u2502 Carrier    \u2502                      \u2502              \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n\ud83d\udccb \u0645\u0648\u0627\u0635\u0641\u0627\u062a \u0645\u0647\u0645\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 \u0645\u062c\u0627\u0644 \u0627\u0644\u062d\u0631\u0627\u0631\u0629: 2\xb0\u0645 \u0625\u0644\u0649 8\xb0\u0645 (\u0644\u0642\u0627\u062d\u0627\u062a)\n\u2022 \u0642\u0633\u0645 \u0627\u0644\u062a\u062c\u0645\u064a\u062f: -15\xb0\u0645 \u0625\u0644\u0649 -25\xb0\u0645 (\u0623\u0643\u064a\u0627\u0633 \u062b\u0644\u062c)\n\u2022 \u064a\u062c\u0628 \u0623\u0646 \u0644\u0627 \u062a\u062a\u062c\u0645\u062f \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0623\u0628\u062f\u0627\u064b!\n\u2022 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u0645\u0631\u062a\u064a\u0646 \u064a\u0648\u0645\u064a\u0627\u064b \u0635\u0628\u0627\u062d\u0627\u064b \u0648\u0645\u0633\u0627\u0621\u064b\n\n\u26a0\ufe0f \u0646\u0635\u0627\u0626\u062d \u0627\u0644\u062a\u062e\u0632\u064a\u0646:\n\u2022 \u0644\u0627 \u062a\u0645\u0644\u0623 \u0627\u0644\u062b\u0644\u0627\u062c\u0629 \u0623\u0643\u062b\u0631 \u0645\u0646 75% \u0645\u0646 \u0633\u0639\u062a\u0647\u0627\n\u2022 \u0627\u062a\u0631\u0643 \u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0639\u0628\u0648\u0627\u062a \u0644\u0644\u0647\u0648\u0627\u0621 \u0627\u0644\u0628\u0627\u0631\u062f\n\u2022 \u0644\u0627 \u062a\u0636\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0641\u064a \u0628\u0627\u0628 \u0627\u0644\u062b\u0644\u0627\u062c\u0629\n\u2022 \u0644\u0627 \u062a\u0636\u0639 \u0637\u0639\u0627\u0645 \u0623\u0648 \u0623\u062f\u0648\u064a\u0629 \u0623\u062e\u0631\u0649 \u0645\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a\n\n\ud83d\udca1 \u062b\u0644\u0627\u062c\u0629 \u0645\u0646\u0638\u0645\u0629 = \u0644\u0642\u0627\u062d\u0627\u062a \u0622\u0645\u0646\u0629!","\ud83c\udf92 \u062a\u0639\u0628\u0626\u0629 \u062d\u0627\u0641\u0638\u0627\u062a \u0627\u0644\u0644\u0642\u0627\u062d (Vaccine Carriers) \u2014 \u062f\u0644\u064a\u0644 \u062e\u0637\u0648\u0629 \u0628\u062e\u0637\u0648\u0629:\n\n\ud83d\udccc \u062e\u0637\u0648\u0627\u062a \u0627\u0644\u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u062a\u0631\u0648\u064a\u0636 \u0623\u0643\u064a\u0627\u0633 \u0627\u0644\u062b\u0644\u062c (Conditioning):\n   \u2022 \u0623\u062e\u0631\u062c \u0627\u0644\u0623\u0643\u064a\u0627\u0633 \u0645\u0646 \u0627\u0644\u0641\u0631\u064a\u0632\u0631 (-20\xb0\u0645)\n   \u2022 \u0627\u062a\u0631\u0643\u0647\u0627 \u0641\u064a \u062f\u0631\u062c\u0629 \u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u063a\u0631\u0641\u0629 \u062d\u062a\u0649 \u064a\u0630\u0648\u0628 \u0627\u0644\u062c\u0644\u064a\u062f \u0627\u0644\u0633\u0637\u062d\u064a\n   \u2022 \u0627\u062e\u062a\u0628\u0631: \u0647\u0632 \u0627\u0644\u0643\u064a\u0633 \u2014 \u064a\u062c\u0628 \u0623\u0646 \u062a\u062a\u062d\u0631\u0643 \u0642\u0637\u0639\u0629 \u0627\u0644\u062b\u0644\u062c \u062f\u0627\u062e\u0644\u0647\n   \u2022 \u26a0\ufe0f \u0647\u0630\u0627 \u064a\u0645\u0646\u0639 \u062a\u062c\u0645\u062f \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0646\u0642\u0644!\n   \u2022 \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u062a\u0642\u0631\u064a\u0628\u064a: 60-90 \u062f\u0642\u064a\u0642\u0629 \u0641\u064a \u062c\u0648 \u062d\u0627\u0631\n\n2\ufe0f\u20e3 \u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u062d\u0627\u0641\u0638\u0629:\n   \u2022 \u0636\u0639 4 \u0623\u0643\u064a\u0627\u0633 \u062b\u0644\u062c \u0645\u0634\u0631\u0648\u0637\u0629 \u0641\u064a \u0627\u0644\u0642\u0627\u0639 \u0648\u0627\u0644\u062c\u0648\u0627\u0646\u0628\n   \u2022 \u0636\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0641\u064a \u0627\u0644\u0645\u0646\u062a\u0635\u0641\n   \u2022 \u0636\u0639 \u0643\u064a\u0633\u064a\u0646 \u062b\u0644\u062c \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\n   \u2022 \u0623\u063a\u0644\u0642 \u0627\u0644\u063a\u0637\u0627\u0621 \u0628\u0625\u062d\u0643\u0627\u0645\n\n3\ufe0f\u20e3 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645:\n   \u2022 \u0644\u0627 \u062a\u0641\u062a\u062d \u0627\u0644\u062d\u0627\u0641\u0638\u0629 \u0625\u0644\u0627 \u0639\u0646\u062f \u0627\u0644\u062d\u0627\u062c\u0629\n   \u2022 \u0623\u062e\u0631\u062c \u0641\u0642\u0637 \u0645\u0627 \u062a\u062d\u062a\u0627\u062c\u0647 \u0641\u0648\u0631\u0627\u064b\n   \u2022 \u0623\u0639\u062f \u0627\u0644\u0625\u063a\u0644\u0627\u0642 \u0628\u0633\u0631\u0639\u0629\n   \u2022 \u0644\u0627 \u062a\u0639\u0631\u0636 \u0627\u0644\u0644\u0642\u0627\u062d \u0644\u0623\u0634\u0639\u0629 \u0627\u0644\u0634\u0645\u0633\n\n\u23f0 \u0645\u062f\u0629 \u0627\u0644\u062d\u0641\u0638:\n\u2022 \u062d\u0627\u0641\u0638\u0629 \u0645\u064f\u0639\u0628\u0623\u0629 \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d: 2-4 \u0633\u0627\u0639\u0627\u062a\n\u2022 \u0635\u0646\u062f\u0648\u0642 \u062a\u0628\u0631\u064a\u062f (Cold box): 2-7 \u0623\u064a\u0627\u0645\n\n\ud83d\udca1 \u0627\u0644\u062e\u0637\u0648\u0629 \u0627\u0644\u0623\u0647\u0645: \u062a\u0631\u0648\u064a\u0636 \u0627\u0644\u062b\u0644\u062c \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645!","\ud83e\uddea \u062a\u062d\u0636\u064a\u0631 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u062c\u0627\u0641\u0629 (Lyophilized Vaccines):\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u062c\u0627\u0641\u0629\u061f\n\u0644\u0642\u0627\u062d\u0627\u062a \u0645\u062c\u0641\u0641\u0629 \u0628\u0627\u0644\u062a\u062c\u0645\u064a\u062f \u062a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u0625\u0639\u0627\u062f\u0629 \u062a\u062d\u0636\u064a\u0631 (Reconstitution) \u0628\u0645\u062d\u0644\u0648\u0644 \u0645\u062e\u0641\u0641 (Diluent) \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645.\n\n\ud83d\udccb \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u062d\u062a\u0627\u062c \u062a\u062d\u0636\u064a\u0631:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 BCG:\n   \u2022 \u064a\u064f\u062d\u0636\u0651\u0631 \u0628\u0645\u062d\u0644\u0648\u0644 \u0645\u062e\u0641\u0641 \u062e\u0627\u0635 (Sodium Chloride)\n   \u2022 \u062d\u062c\u0645 \u0627\u0644\u0645\u062e\u0641\u0641: \u064a\u062e\u062a\u0644\u0641 \u062d\u0633\u0628 \u0627\u0644\u0634\u0631\u0643\u0629 \u0627\u0644\u0645\u0635\u0646\u0639\u0629\n   \u2022 \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u062e\u0644\u0627\u0644 6 \u0633\u0627\u0639\u0627\u062a \u0628\u0639\u062f \u0627\u0644\u062a\u062d\u0636\u064a\u0631\n   \u2022 \u26a0\ufe0f \u0644\u0627 \u062a\u064f\u062c\u0645\u0651\u062f \u0627\u0644\u0645\u062e\u0641\u0641 \u0623\u0628\u062f\u0627\u064b!\n\n2\ufe0f\u20e3 MR (\u0627\u0644\u062d\u0635\u0628\u0629 \u0648\u0627\u0644\u062d\u0635\u0628\u0629 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064a\u0629):\n   \u2022 \u064a\u064f\u062d\u0636\u0651\u0631 \u0628\u0645\u062d\u0644\u0648\u0644 \u0645\u062e\u0641\u0641 \u062e\u0627\u0635 (Sterile Water)\n   \u2022 \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u062e\u0644\u0627\u0644 6 \u0633\u0627\u0639\u0627\u062a \u0628\u0639\u062f \u0627\u0644\u062a\u062d\u0636\u064a\u0631\n   \u2022 \u0625\u0630\u0627 \u0637\u064f\u0628\u0642\u062a \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0642\u0627\u0631\u0648\u0631\u0629 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629: \u062d\u062a\u0649 28 \u064a\u0648\u0645\u0627\u064b\n   \u2022 \u26a0\ufe0f \u0644\u0627 \u062a\u064f\u062c\u0645\u0651\u062f \u0627\u0644\u0645\u062e\u0641\u0641 \u0623\u0628\u062f\u0627\u064b!\n\n\u26a0\ufe0f \u0642\u0648\u0627\u0639\u062f \u0645\u0647\u0645\u0629:\n\u2022 \u0627\u0633\u062a\u062e\u062f\u0645 \u0641\u0642\u0637 \u0627\u0644\u0645\u062e\u0641\u0641 \u0627\u0644\u0645\u062e\u0635\u0635 \u0644\u0643\u0644 \u0644\u0642\u0627\u062d\n\u2022 \u0644\u0627 \u062a\u0633\u062a\u062e\u062f\u0645 \u0645\u062e\u0641\u0641 \u0644\u0642\u0627\u062d \u0645\u0639 \u0644\u0642\u0627\u062d \u0622\u062e\u0631 \u0623\u0628\u062f\u0627\u064b!\n\u2022 \u0627\u062d\u0641\u0638 \u0627\u0644\u0645\u062e\u0641\u0641 \u0641\u064a \u0627\u0644\u062b\u0644\u0627\u062c\u0629 (2-8\xb0\u0645) \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645\n\u2022 \u0644\u0627 \u062a\u064f\u062c\u0645\u0651\u062f \u0627\u0644\u0645\u062e\u0641\u0641 \u2014 \u0627\u0644\u062a\u062c\u0645\u064a\u062f \u064a\u0641\u0633\u062f\u0647!\n\u2022 \u062f\u0648\u0651\u0646 \u0648\u0642\u062a \u0627\u0644\u062a\u062d\u0636\u064a\u0631 \u0639\u0644\u0649 \u0627\u0644\u0639\u0628\u0648\u0629\n\u2022 \u062a\u062e\u0644\u0635 \u0645\u0646 \u0627\u0644\u0644\u0642\u0627\u062d \u0627\u0644\u0645\u062d\u0636\u0651\u0631 \u0628\u0639\u062f 6 \u0633\u0627\u0639\u0627\u062a (\u0625\u0646 \u0644\u0645 \u062a\u0637\u0628\u0642 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0642\u0627\u0631\u0648\u0631\u0629 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629)\n\n\ud83d\udca1 \u062e\u0637\u0623 \u0641\u064a \u0627\u0644\u062a\u062d\u0636\u064a\u0631 = \u0644\u0642\u0627\u062d \u063a\u064a\u0631 \u0641\u0639\u0627\u0644!","\ud83d\udc89 \u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u062d\u0642\u0646 (Injection Safety) \u2014 \u062f\u0644\u064a\u0644 \u0634\u0627\u0645\u0644:\n\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u062d\u0642\u0646 \u0645\u0647\u0645\u0629\u061f\n\u2022 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0637\u0641\u0644 \u0645\u0646 \u0627\u0644\u0639\u062f\u0648\u0649\n\u2022 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0639\u0627\u0645\u0644 \u0627\u0644\u0635\u062d\u064a \u0645\u0646 \u0627\u0644\u0625\u0635\u0627\u0628\u0629 \u0628\u0627\u0644\u0625\u0628\u0631\n\u2022 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0645\u0646 \u0627\u0644\u0646\u0641\u0627\u064a\u0627\u062a \u0627\u0644\u062e\u0637\u0631\u0629\n\n\ud83d\udccb \u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u062d\u0642\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0642\u0628\u0644 \u0627\u0644\u062d\u0642\u0646:\n   \u2022 \u063a\u0633\u0644 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0627\u0644\u0645\u0627\u0621 \u0648\u0627\u0644\u0635\u0627\u0628\u0648\u0646\n   \u2022 \u0641\u062d\u0635 VVM \u0648\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629\n   \u2022 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u062d\u0642\u0646\u0629 ADS \u062c\u062f\u064a\u062f\u0629 \u0644\u0643\u0644 \u0637\u0641\u0644\n   \u2022 \u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u0646\u0648\u0639 \u0627\u0644\u0645\u062d\u0642\u0646\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\n\n2\ufe0f\u20e3 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062d\u0642\u0646:\n   \u2022 \u0627\u062e\u062a\u064a\u0627\u0631 \u0645\u0643\u0627\u0646 \u0627\u0644\u062d\u0642\u0646 \u0627\u0644\u0635\u062d\u064a\u062d\n   \u2022 \u062a\u0637\u0647\u064a\u0631 \u0627\u0644\u062c\u0644\u062f \u0628\u0642\u0637\u0646\u0629 \u0648\u0643\u062d\u0648\u0644 (\u0625\u0646 \u0648\u064f\u062c\u062f)\n   \u2022 \u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u0625\u0628\u0631\u0629 \u0628\u0627\u0644\u0632\u0627\u0648\u064a\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629\n   \u2022 \u0639\u062f\u0645 \u0625\u0639\u0627\u062f\u0629 \u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0625\u0628\u0631\u0629 \u064a\u062f\u0648\u064a\u0627\u064b!\n\n3\ufe0f\u20e3 \u0628\u0639\u062f \u0627\u0644\u062d\u0642\u0646:\n   \u2022 \u0627\u0644\u062a\u062e\u0644\u0635 \u0645\u0646 \u0627\u0644\u0645\u062d\u0642\u0646\u0629 \u0641\u0648\u0631\u0627\u064b \u0641\u064a \u062d\u0646\u062f\u064a\u0642 \u0627\u0644\u0623\u0645\u0627\u0646\n   \u2022 \u0639\u062f\u0645 \u0641\u0643 \u0627\u0644\u0625\u0628\u0631\u0629 \u0639\u0646 \u0627\u0644\u0645\u062d\u0642\u0646\u0629\n   \u2022 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0645\u0643\u0627\u0646 \u0627\u0644\u062d\u0642\u0646 \u0628\u0642\u0637\u0646\u0629 \u0646\u0638\u064a\u0641\u0629\n\n\ud83d\udeab \u0645\u0645\u0646\u0648\u0639\u0627\u062a:\n\u2022 \u0644\u0627 \u062a\u064f\u0639\u062f \u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0625\u0628\u0631\u0629 \u0628\u064a\u062f\u0643 (Two-hand recapping)\n\u2022 \u0644\u0627 \u062a\u0633\u062a\u062e\u062f\u0645 \u0645\u062d\u0642\u0646\u0629 \u0648\u0627\u062d\u062f\u0629 \u0644\u0623\u0643\u062b\u0631 \u0645\u0646 \u0637\u0641\u0644\n\u2022 \u0644\u0627 \u062a\u0631\u0645\u064a \u0627\u0644\u0645\u062d\u0627\u0642\u0646 \u0641\u064a \u0627\u0644\u0642\u0645\u0627\u0645\u0629 \u0627\u0644\u0639\u0627\u062f\u064a\u0629\n\n\ud83d\udca1 \u0645\u062d\u0642\u0646\u0629 \u0648\u0627\u062d\u062f\u0629 = \u0637\u0641\u0644 \u0648\u0627\u062d\u062f = \u0622\u0645\u0646!","\ud83d\uddd1\ufe0f \u0627\u0644\u062a\u062e\u0644\u0635 \u0645\u0646 \u0627\u0644\u0646\u0641\u0627\u064a\u0627\u062a \u0627\u0644\u062d\u064a\u0648\u064a\u0629 (Medical Waste Disposal):\n\n\ud83d\udccc \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0646\u0641\u0627\u064a\u0627\u062a \u0627\u0644\u0637\u0628\u064a\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0646\u0641\u0627\u064a\u0627\u062a \u062d\u0627\u062f\u0629 (Sharps):\n   \u2022 \u0645\u062d\u0627\u0642\u0646 ADS \u0645\u0633\u062a\u0639\u0645\u0644\u0629\n   \u2022 \u0623\u0645\u0628\u0648\u0644\u0627\u062a \u0632\u062c\u0627\u062c\u064a\u0629\n   \u2022 \u0632\u062c\u0627\u062c\u0627\u062a \u0644\u0642\u0627\u062d \u0645\u0643\u0633\u0648\u0631\u0629\n\n2\ufe0f\u20e3 \u0646\u0641\u0627\u064a\u0627\u062a \u0645\u0639\u062f\u064a\u0629:\n   \u2022 \u0642\u0637\u0646 \u0645\u0644\u0648\u062b \u0628\u0627\u0644\u062f\u0645\n   \u2022 \u0642\u0641\u0627\u0632\u0627\u062a \u0645\u0633\u062a\u0639\u0645\u0644\u0629\n   \u2022 \u0639\u0628\u0648\u0627\u062a \u0644\u0642\u0627\u062d \u0641\u0627\u0631\u063a\u0629\n\n\ud83d\udccb \u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u062a\u062e\u0644\u0635:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u062d\u0646\u0627\u062f\u064a\u0642 \u0627\u0644\u0623\u0645\u0627\u0646 (Safety Boxes):\n   \u2022 \u0636\u0639 \u0627\u0644\u0645\u062d\u0642\u0646\u0629 \u0641\u0648\u0631\u0627\u064b \u0628\u0639\u062f \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645\n   \u2022 \u0644\u0627 \u062a\u0645\u0644\u0623 \u0623\u0643\u062b\u0631 \u0645\u0646 3/4 \u0627\u0644\u0633\u0639\u0629\n   \u2022 \u0623\u063a\u0644\u0642 \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0628\u0625\u062d\u0643\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0627\u0645\u062a\u0644\u0627\u0621\n   \u2022 \u062f\u0648\u0651\u0646 \u0627\u0644\u062a\u0627\u0631\u064a\u062e \u0648\u0627\u0644\u0645\u0631\u0641\u0642 \u0639\u0644\u0649 \u0627\u0644\u0635\u0646\u062f\u0648\u0642\n\n2\ufe0f\u20e3 \u0637\u0631\u0642 \u0627\u0644\u062a\u062e\u0644\u0635 \u0627\u0644\u0646\u0647\u0627\u0626\u064a:\n   \u2022 \u0627\u0644\u062d\u0631\u0642 (Incineration): \u0639\u0646\u062f \u062f\u0631\u062c\u0629 800\xb0\u0645+\n   \u2022 \u0627\u0644\u062f\u0641\u0646 \u0627\u0644\u0622\u0645\u0646 (Safe Burial): \u062d\u0641\u0631\u0629 \u0645\u0628\u0637\u0646\u0629 \u0628\u0639\u0645\u0642 1\u0645+\n   \u2022 \u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u0644\u0645\u0631\u0641\u0642 \u0627\u0644\u062a\u062e\u0644\u0635 \u0627\u0644\u0645\u0639\u062a\u0645\u062f\n\n\u26a0\ufe0f \u0645\u062d\u0638\u0648\u0631\u0627\u062a:\n\u2022 \u0644\u0627 \u062a\u0631\u0645\u064a \u0627\u0644\u0646\u0641\u0627\u064a\u0627\u062a \u0627\u0644\u062d\u064a\u0648\u064a\u0629 \u0641\u064a \u0627\u0644\u0642\u0645\u0627\u0645\u0629 \u0627\u0644\u0639\u0627\u062f\u064a\u0629\n\u2022 \u0644\u0627 \u062a\u062d\u0631\u0642 \u0627\u0644\u0646\u0641\u0627\u064a\u0627\u062a \u0641\u064a \u0627\u0644\u0639\u0631\u0627\u0621\n\u2022 \u0644\u0627 \u062a\u0639\u064a\u062f \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0645\u062d\u0627\u0642\u0646\n\n\ud83d\udca1 \u0627\u0644\u062a\u062e\u0644\u0635 \u0627\u0644\u0622\u0645\u0646 \u064a\u062d\u0645\u064a \u0627\u0644\u062c\u0645\u064a\u0639!","\ud83c\udf21\ufe0f \u0645\u0631\u0627\u0642\u0628\u0629 \u062f\u0631\u062c\u0629 \u062d\u0631\u0627\u0631\u0629 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f:\n\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u0646\u0631\u0627\u0642\u0628 \u0627\u0644\u062d\u0631\u0627\u0631\u0629\u061f\n\u2022 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u062d\u0633\u0627\u0633\u0629 \u062c\u062f\u0627\u064b \u0644\u0644\u062d\u0631\u0627\u0631\u0629 \u0648\u0627\u0644\u062a\u062c\u0645\u062f\n\u2022 \u0627\u0644\u0644\u0642\u0627\u062d \u0627\u0644\u0645\u0639\u0631\u0636 \u0644\u0644\u062d\u0631\u0627\u0631\u0629 \u064a\u0641\u0642\u062f \u0641\u0639\u0627\u0644\u064a\u062a\u0647\n\u2022 \u0627\u0644\u0644\u0642\u0627\u062d \u0627\u0644\u0645\u062a\u062c\u0645\u062f \u064a\u0641\u0642\u062f \u0641\u0639\u0627\u0644\u064a\u062a\u0647 \u0648\u0642\u062f \u064a\u0633\u0628\u0628 \u0623\u0636\u0631\u0627\u0631\u0627\u064b\n\n\ud83d\udccb \u0623\u062f\u0648\u0627\u062a \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0645\u064a\u0632\u0627\u0646 \u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u062b\u0644\u0627\u062c\u0629:\n   \u2022 \u064a\u064f\u0642\u0631\u0623 \u0645\u0631\u062a\u064a\u0646 \u064a\u0648\u0645\u064a\u0627\u064b (\u0635\u0628\u0627\u062d\u0627\u064b \u0648\u0645\u0633\u0627\u0621\u064b)\n   \u2022 \u0627\u0644\u0645\u062f\u0649 \u0627\u0644\u0645\u0637\u0644\u0648\u0628: 2\xb0\u0645 - 8\xb0\u0645\n   \u2022 \u064a\u064f\u0633\u062c\u0644 \u0641\u064a \u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u064a\u0648\u0645\u064a\n\n2\ufe0f\u20e3 VVM (\u0645\u0624\u0634\u0631 \u0635\u0644\u0627\u062d\u064a\u0629 \u0627\u0644\u0644\u0642\u0627\u062d):\n   \u2022 \u064a\u064f\u0641\u062d\u0635 \u0642\u0628\u0644 \u0643\u0644 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\n   \u2022 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 1-2: \u0635\u0627\u0644\u062d \u2705\n   \u2022 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 3-4: \u063a\u064a\u0631 \u0635\u0627\u0644\u062d \u274c\n\n3\ufe0f\u20e3 \u0645\u0624\u0634\u0631 \u0627\u0644\u062a\u062c\u0645\u062f (Freeze Indicator):\n   \u2022 \u064a\u0643\u0634\u0641 \u0625\u0630\u0627 \u062a\u062c\u0645\u062f \u0627\u0644\u0644\u0642\u0627\u062d\n   \u2022 \u0625\u0630\u0627 \u062a\u063a\u064a\u0631 \u0627\u0644\u0644\u0648\u0646 \u2190 \u0627\u0644\u0644\u0642\u0627\u062d \u0645\u062a\u062c\u0645\u062f \u2190 \u0644\u0627 \u062a\u0633\u062a\u062e\u062f\u0645\u0647!\n\n4\ufe0f\u20e3 \u0645\u0633\u062c\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a (Data Logger):\n   \u2022 \u064a\u0633\u062c\u0644 \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b \u0643\u0644 10-30 \u062f\u0642\u064a\u0642\u0629\n   \u2022 \u064a\u064f\u062d\u0645\u0651\u0644 \u0639\u0644\u0649 \u0627\u0644\u0643\u0645\u0628\u064a\u0648\u062a\u0631 \u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0627\u062a\u062c\u0627\u0647\u0627\u062a\n\n\u26a0\ufe0f \u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u0637\u0648\u0627\u0631\u0626:\n\u2022 \u0625\u0630\u0627 \u0627\u0646\u0642\u0637\u0639\u062a \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621: \u0644\u0627 \u062a\u0641\u062a\u062d \u0627\u0644\u062b\u0644\u0627\u062c\u0629!\n\u2022 \u062d\u0627\u0641\u0638\u0629 \u0645\u063a\u0644\u0642\u0629 \u062a\u062d\u0641\u0638 \u0627\u0644\u0628\u0631\u0648\u062f\u0629 6-8 \u0633\u0627\u0639\u0627\u062a\n\u2022 \u0627\u0646\u0642\u0644 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0644\u062b\u0644\u0627\u062c\u0629 \u0623\u062e\u0631\u0649 \u0623\u0648 \u0635\u0646\u062f\u0648\u0642 \u062a\u0628\u0631\u064a\u062f","\ud83d\udd27 \u0635\u064a\u0627\u0646\u0629 \u0645\u0639\u062f\u0627\u062a \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f:\n\n\ud83d\udccc \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0635\u064a\u0627\u0646\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u0635\u064a\u0627\u0646\u0629 \u0627\u0644\u064a\u0648\u0645\u064a\u0629:\n   \u2022 \u0642\u0631\u0627\u0621\u0629 \u0648\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u0645\u0631\u062a\u064a\u0646\n   \u2022 \u0641\u062d\u0635 \u0639\u0645\u0644 \u0627\u0644\u062b\u0644\u0627\u062c\u0629 (\u0635\u0648\u062a\u060c \u0627\u0647\u062a\u0632\u0627\u0632)\n   \u2022 \u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u0628\u0627\u0628 \u0628\u0625\u062d\u0643\u0627\u0645\n   \u2022 \u0646\u0638\u0627\u0641\u0629 \u0627\u0644\u0645\u062d\u064a\u0637 \u062d\u0648\u0644 \u0627\u0644\u062b\u0644\u0627\u062c\u0629\n\n2\ufe0f\u20e3 \u0627\u0644\u0635\u064a\u0627\u0646\u0629 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a\u0629:\n   \u2022 \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0635\u0642\u064a\u0639 (Defrost) \u0625\u0630\u0627 \u062a\u0631\u0627\u0643\u0645 \u0623\u0643\u062b\u0631 \u0645\u0646 5 \u0645\u0645\n   \u2022 \u062a\u0646\u0638\u064a\u0641 \u0627\u0644\u062b\u0644\u0627\u062c\u0629 \u0645\u0646 \u0627\u0644\u062f\u0627\u062e\u0644\n   \u2022 \u0641\u062d\u0635 \u0625\u0637\u0627\u0631 \u0627\u0644\u0628\u0627\u0628 (Gasket)\n   \u2022 \u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u062a\u0647\u0648\u064a\u0629 \u062e\u0644\u0641 \u0627\u0644\u062b\u0644\u0627\u062c\u0629\n\n3\ufe0f\u20e3 \u0627\u0644\u0635\u064a\u0627\u0646\u0629 \u0627\u0644\u0634\u0647\u0631\u064a\u0629:\n   \u2022 \u0641\u062d\u0635 \u0643\u0627\u0628\u0644\u0627\u062a \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621\n   \u2022 \u062a\u0646\u0638\u064a\u0641 \u0645\u0644\u0641\u0627\u062a \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n   \u2022 \u0641\u062d\u0635 \u0645\u0648\u0644\u062f \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621 (\u0625\u0646 \u0648\u064f\u062c\u062f)\n   \u2022 \u0645\u0631\u0627\u062c\u0639\u0629 \u0633\u062c\u0644 \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u0634\u0647\u0631\u064a\n\n4\ufe0f\u20e3 \u0627\u0644\u0635\u064a\u0627\u0646\u0629 \u0627\u0644\u0633\u0646\u0648\u064a\u0629:\n   \u2022 \u0641\u062d\u0635 \u0634\u0627\u0645\u0644 \u0645\u0646 \u0641\u0646\u064a \u0645\u062e\u062a\u0635\n   \u2022 \u0627\u062e\u062a\u0628\u0627\u0631 \u0643\u0641\u0627\u0621\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n   \u2022 \u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0627\u0644\u0623\u062c\u0632\u0627\u0621 \u0627\u0644\u062a\u0627\u0644\u0641\u0629\n   \u2022 \u0645\u0639\u0627\u064a\u0631\u0629 \u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u062d\u0631\u0627\u0631\u0629\n\n\ud83d\udca1 \u062b\u0644\u0627\u062c\u0629 \u0645\u0647\u0645\u0644\u0629 = \u0644\u0642\u0627\u062d\u0627\u062a \u0645\u0647\u062f\u062f\u0629 = \u0623\u0637\u0641\u0627\u0644 \u0641\u064a \u062e\u0637\u0631!","\ud83d\ude9a \u0646\u0642\u0644 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u2014 \u062f\u0644\u064a\u0644 \u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0622\u0645\u0646:\n\n\ud83d\udccc \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u0646\u0642\u0644 \u0627\u0644\u0622\u0645\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629:\n   \u2022 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0635\u0646\u0627\u062f\u064a\u0642 \u0627\u0644\u062a\u0628\u0631\u064a\u062f (Cold Boxes)\n   \u2022 \u0623\u0643\u064a\u0627\u0633 \u062b\u0644\u062c \u0645\u0634\u0631\u0648\u0637\u0629 (\u0645\u0631\u0648\u0636\u0629)\n   \u2022 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0641\u064a \u0627\u0644\u0645\u0646\u062a\u0635\u0641\n   \u2022 \u0623\u0643\u064a\u0627\u0633 \u0627\u0644\u062b\u0644\u062c \u0645\u0646 \u0627\u0644\u0623\u0639\u0644\u0649 \u0648\u0627\u0644\u062c\u0648\u0627\u0646\u0628\n\n2\ufe0f\u20e3 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0646\u0642\u0644:\n   \u2022 \u062a\u062c\u0646\u0628 \u0627\u0644\u062a\u0639\u0631\u0636 \u0644\u0623\u0634\u0639\u0629 \u0627\u0644\u0634\u0645\u0633 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629\n   \u2022 \u0644\u0627 \u062a\u0636\u0639 \u0635\u0646\u0627\u062f\u064a\u0642 \u0627\u0644\u0644\u0642\u0627\u062d \u0641\u064a \u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0633\u064a\u0627\u0631\u0629 \u0627\u0644\u062d\u0627\u0631\n   \u2022 \u0636\u0639\u0647\u0627 \u0641\u064a \u0627\u0644\u0645\u0642\u0635\u0648\u0631\u0629 \u0627\u0644\u0645\u0643\u064a\u0651\u0641\u0629\n   \u2022 \u0644\u0627 \u062a\u062a\u0631\u0643\u0647\u0627 \u0641\u064a \u0627\u0644\u0633\u064a\u0627\u0631\u0629 \u0627\u0644\u0645\u062a\u0648\u0642\u0641\u0629\n\n3\ufe0f\u20e3 \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0648\u0644:\n   \u2022 \u0636\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0641\u064a \u0627\u0644\u062b\u0644\u0627\u062c\u0629 \u0641\u0648\u0631\u0627\u064b\n   \u2022 \u0633\u062c\u0651\u0644 \u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0645 \u0641\u064a \u0633\u062c\u0644 \u0627\u0644\u0645\u062e\u0632\u0648\u0646\n   \u2022 \u0641\u062d\u0635 VVM \u0644\u0643\u0644 \u0634\u062d\u0646\u0629\n   \u2022 \u062a\u062d\u0642\u0642 \u0645\u0646 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629\n\n\ud83d\udcca \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0648\u0632\u064a\u0639:\n\u0627\u0644\u0645\u0633\u062a\u0648\u062f\u0639 \u0627\u0644\u0648\u0637\u0646\u064a \u2190 \u0627\u0644\u0645\u0633\u062a\u0648\u062f\u0639 \u0627\u0644\u0625\u0642\u0644\u064a\u0645\u064a \u2190 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629 \u2190 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0629 \u2190 \u0627\u0644\u0645\u0631\u0641\u0642\n\n\ud83d\udca1 \u0623\u064a \u0627\u0646\u0642\u0637\u0627\u0639 \u0641\u064a \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f = \u062e\u0637\u0631 \u0639\u0644\u0649 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a!","\ud83c\udfe5 \u0627\u0644\u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u0635\u062d\u064a\u062d \u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0641\u064a \u0627\u0644\u062b\u0644\u0627\u062c\u0629:\n\n\ud83d\udccc \u0642\u0648\u0627\u0639\u062f \u0627\u0644\u062a\u062e\u0632\u064a\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a:\n   \u2022 \u0643\u0644 \u0644\u0642\u0627\u062d \u0641\u064a \u0631\u0641 \u0645\u062e\u0635\u0635 \u0648\u0648\u0627\u0636\u062d \u0627\u0644\u062a\u0633\u0645\u064a\u0629\n   \u2022 \u062a\u0631\u062a\u064a\u0628 \u062d\u0633\u0628 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0627\u0646\u062a\u0647\u0627\u0621 (\u0627\u0644\u0623\u0642\u0631\u0628 \u0641\u064a \u0627\u0644\u0645\u0642\u062f\u0645\u0629 \u2014 FEFO)\n   \u2022 \u0644\u0627 \u062a\u062e\u0644\u0637 \u0644\u0642\u0627\u062d\u0627\u062a \u0645\u0646 \u0634\u062d\u0646\u0627\u062a \u0645\u062e\u062a\u0644\u0641\u0629\n   \u2022 \u0644\u0627 \u062a\u0636\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0641\u064a \u0628\u0627\u0628 \u0627\u0644\u062b\u0644\u0627\u062c\u0629!\n\n2\ufe0f\u20e3 \u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u062a\u062e\u0632\u064a\u0646:\n   \u2022 \u0644\u0627 \u062a\u0645\u0644\u0623 \u0623\u0643\u062b\u0631 \u0645\u0646 75% \u0645\u0646 \u0633\u0639\u0629 \u0627\u0644\u062b\u0644\u0627\u062c\u0629\n   \u2022 \u0627\u062a\u0631\u0643 \u0645\u0633\u0627\u0641\u0627\u062a \u0628\u064a\u0646 \u0627\u0644\u0639\u0628\u0648\u0627\u062a \u0644\u0644\u062f\u0648\u0631\u0629 \u0627\u0644\u0647\u0648\u0627\u0626\u064a\u0629\n   \u2022 \u0644\u0627 \u062a\u0644\u0645\u0633 \u0627\u0644\u0639\u0628\u0648\u0627\u062a \u062c\u062f\u0627\u0631 \u0627\u0644\u062b\u0644\u0627\u062c\u0629\n\n3\ufe0f\u20e3 \u0641\u0635\u0644 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a:\n   \u2022 \u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0641\u064a \u0631\u0641 \u0645\u0646\u0641\u0635\u0644\n   \u2022 \u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0646\u0633\u0627\u0621 (Td) \u0641\u064a \u0631\u0641 \u0645\u0646\u0641\u0635\u0644\n   \u2022 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0645\u062d\u0636\u0651\u0631\u0629 (BCG, MR) \u0641\u064a \u0643\u064a\u0633 \u0645\u064f\u0639\u0644\u0651\u0645\n\n4\ufe0f\u20e3 \u0627\u0644\u0645\u062d\u0638\u0648\u0631\u0627\u062a:\n   \u2022 \u0644\u0627 \u062a\u0636\u0639 \u0637\u0639\u0627\u0645\u0627\u064b \u0623\u0648 \u0623\u062f\u0648\u064a\u0629 \u0623\u062e\u0631\u0649 \u0645\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a\n   \u2022 \u0644\u0627 \u062a\u0636\u0639 \u0639\u064a\u0646\u0627\u062a \u0627\u0644\u062f\u0645 \u0623\u0648 \u0627\u0644\u0628\u0648\u0644 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u062b\u0644\u0627\u062c\u0629\n   \u2022 \u0644\u0627 \u062a\u0641\u062a\u062d \u0627\u0644\u0628\u0627\u0628 \u0628\u0634\u0643\u0644 \u0645\u062a\u0643\u0631\u0631\n\n\ud83d\udca1 \u062b\u0644\u0627\u062c\u0629 \u0645\u0646\u0638\u0645\u0629 = \u0644\u0642\u0627\u062d\u0627\u062a \u0622\u0645\u0646\u0629 = \u0623\u0637\u0641\u0627\u0644 \u0645\u062d\u0645\u064a\u0648\u0646!","\u26a1 \u0625\u062f\u0627\u0631\u0629 \u0627\u0646\u0642\u0637\u0627\u0639 \u0627\u0644\u062a\u0628\u0631\u064a\u062f (Cold Chain Break):\n\n\ud83d\udccc \u0645\u0627\u0630\u0627 \u062a\u0641\u0639\u0644 \u0639\u0646\u062f \u0627\u0646\u0642\u0637\u0627\u0639 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621 \u0623\u0648 \u062a\u0639\u0637\u0644 \u0627\u0644\u062b\u0644\u0627\u062c\u0629\u061f\n\n\ud83d\udea8 \u062e\u0637\u0648\u0627\u062a \u0627\u0644\u0637\u0648\u0627\u0631\u0626:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0641\u0648\u0631\u0627\u064b (\u062e\u0644\u0627\u0644 15 \u062f\u0642\u064a\u0642\u0629):\n   \u2022 \u0644\u0627 \u062a\u0641\u062a\u062d \u0628\u0627\u0628 \u0627\u0644\u062b\u0644\u0627\u062c\u0629!\n   \u2022 \u0627\u0644\u062b\u0644\u0627\u062c\u0629 \u0627\u0644\u0645\u063a\u0644\u0642\u0629 \u062a\u062d\u0641\u0638 \u0627\u0644\u0628\u0631\u0648\u062f\u0629 6-8 \u0633\u0627\u0639\u0627\u062a\n   \u2022 \u0628\u0644\u0651\u063a \u0627\u0644\u0645\u0634\u0631\u0641 \u0623\u0648 \u0645\u062f\u064a\u0631 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\n2\ufe0f\u20e3 \u0625\u0630\u0627 \u0627\u0633\u062a\u0645\u0631 \u0627\u0644\u0627\u0646\u0642\u0637\u0627\u0639 \u0623\u0643\u062b\u0631 \u0645\u0646 8 \u0633\u0627\u0639\u0627\u062a:\n   \u2022 \u0627\u0646\u0642\u0644 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0644\u062b\u0644\u0627\u062c\u0629 \u0623\u062e\u0631\u0649 \u0639\u0627\u0645\u0644\u0629\n   \u2022 \u0623\u0648 \u0627\u0633\u062a\u062e\u062f\u0645 \u0635\u0646\u0627\u062f\u064a\u0642 \u0627\u0644\u062a\u0628\u0631\u064a\u062f \u0645\u0639 \u0623\u0643\u064a\u0627\u0633 \u062b\u0644\u062c \u0645\u0634\u0631\u0648\u0637\u0629\n   \u2022 \u0636\u0639 \u0645\u0624\u0634\u0631\u0627\u062a \u062d\u0631\u0627\u0631\u0629 \u0645\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0645\u0646\u0642\u0648\u0644\u0629\n\n3\ufe0f\u20e3 \u0641\u062d\u0635 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0628\u0639\u062f \u0639\u0648\u062f\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f:\n   \u2022 \u0641\u062d\u0635 VVM \u0644\u0643\u0644 \u0639\u0628\u0648\u0629\n   \u2022 \u0641\u062d\u0635 \u0645\u0624\u0634\u0631 \u0627\u0644\u062a\u062c\u0645\u062f\n   \u2022 \u0625\u0630\u0627 VVM \u0641\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 1-2 \u2190 \u0627\u0644\u0644\u0642\u0627\u062d \u0635\u0627\u0644\u062d \u2705\n   \u2022 \u0625\u0630\u0627 VVM \u0641\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 3-4 \u2190 \u0644\u0627 \u062a\u0633\u062a\u062e\u062f\u0645\u0647 \u274c\n   \u2022 \u0625\u0630\u0627 \u0627\u0644\u0644\u0642\u0627\u062d \u062a\u062c\u0645\u062f \u2190 \u0644\u0627 \u062a\u0633\u062a\u062e\u062f\u0645\u0647 \u274c\n\n4\ufe0f\u20e3 \u0627\u0644\u062a\u0648\u062b\u064a\u0642:\n   \u2022 \u0633\u062c\u0651\u0644 \u0648\u0642\u062a \u0627\u0644\u0627\u0646\u0642\u0637\u0627\u0639 \u0648\u0645\u062f\u062a\u0647\n   \u2022 \u0633\u062c\u0651\u0644 \u0623\u0639\u0644\u0649 \u062f\u0631\u062c\u0629 \u062d\u0631\u0627\u0631\u0629 \u0648\u0635\u0644\u062a \u0625\u0644\u064a\u0647\u0627 \u0627\u0644\u062b\u0644\u0627\u062c\u0629\n   \u2022 \u0633\u062c\u0651\u0644 \u0639\u062f\u062f \u0627\u0644\u0639\u0628\u0648\u0627\u062a \u0627\u0644\u0645\u062a\u0623\u062b\u0631\u0629\n   \u2022 \u0623\u0628\u0644\u063a \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0623\u0639\u0644\u0649\n\n\ud83d\udca1 \u0627\u0644\u0648\u0642\u0627\u064a\u0629 \u0623\u0641\u0636\u0644 \u0645\u0646 \u0627\u0644\u0639\u0644\u0627\u062c \u2014 \u0645\u0648\u0644\u062f \u0643\u0647\u0631\u0628\u0627\u0621 \u0627\u062d\u062a\u064a\u0627\u0637\u064a \u0636\u0631\u0648\u0631\u064a!","\ud83d\udcca \u0646\u0638\u0627\u0645 FIFO \u0648 FEFO \u0644\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062e\u0632\u0648\u0646:\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 FIFO\u061f\nFirst In, First Out \u2014 \u0623\u0648\u0644 \u0645\u0646 \u064a\u062f\u062e\u0644 = \u0623\u0648\u0644 \u0645\u0646 \u064a\u062e\u0631\u062c\n\u2022 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u062a\u064a \u062f\u062e\u0644\u062a \u0627\u0644\u0645\u062e\u0632\u0646 \u0623\u0648\u0644\u0627\u064b \u062a\u064f\u0633\u062a\u062e\u062f\u0645 \u0623\u0648\u0644\u0627\u064b\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 FEFO\u061f\nFirst Expire, First Out \u2014 \u0623\u0648\u0644 \u0645\u0646 \u062a\u0646\u062a\u0647\u064a \u0635\u0644\u0627\u062d\u064a\u062a\u0647 = \u0623\u0648\u0644 \u064a\u064f\u0633\u062a\u062e\u062f\u0645\n\u2022 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0623\u0642\u0631\u0628 \u0644\u0627\u0646\u062a\u0647\u0627\u0621 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629 \u062a\u064f\u0633\u062a\u062e\u062f\u0645 \u0623\u0648\u0644\u0627\u064b\n\n\ud83d\udccb \u0623\u064a \u0646\u0638\u0627\u0645 \u0646\u0633\u062a\u062e\u062f\u0645\u061f\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2705 FEFO \u0647\u0648 \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u064f\u0648\u0635\u0649 \u0628\u0647 \u0644\u0644\u0642\u0627\u062d\u0627\u062a!\n\u2022 \u0644\u0623\u0646 \u0627\u0644\u0644\u0642\u0627\u062d \u0627\u0644\u0630\u064a \u062a\u0646\u062a\u0647\u064a \u0635\u0644\u0627\u062d\u064a\u062a\u0647 \u0623\u0648\u0644\u0627\u064b \u0642\u062f \u0644\u0627 \u064a\u0643\u0648\u0646 \u0627\u0644\u0623\u0648\u0644 \u062f\u062e\u0648\u0644\u0627\u064b\n\u2022 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 FEFO \u064a\u0642\u0644\u0644 \u0627\u0644\u0647\u062f\u0631 \u0628\u0633\u0628\u0628 \u0627\u0646\u062a\u0647\u0627\u0621 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629\n\n\ud83d\udd27 \u0643\u064a\u0641\u064a\u0629 \u062a\u0637\u0628\u064a\u0642 FEFO:\n1. \u0631\u062a\u0651\u0628 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0641\u064a \u0627\u0644\u062b\u0644\u0627\u062c\u0629 \u062d\u0633\u0628 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0627\u0646\u062a\u0647\u0627\u0621\n2. \u0627\u0644\u0623\u0642\u0631\u0628 \u0644\u0627\u0646\u062a\u0647\u0627\u0621 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629 = \u0641\u064a \u0627\u0644\u0645\u0642\u062f\u0645\u0629\n3. \u0627\u0644\u0623\u0628\u0639\u062f \u0639\u0646 \u0627\u0646\u062a\u0647\u0627\u0621 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629 = \u0641\u064a \u0627\u0644\u062e\u0644\u0641\n4. \u0644\u0627 \u062a\u0633\u062a\u062e\u062f\u0645 \u0644\u0642\u0627\u062d\u0627\u064b \u0627\u0646\u062a\u0647\u062a \u0635\u0644\u0627\u062d\u064a\u062a\u0647 \u0623\u0628\u062f\u0627\u064b!\n5. \u0631\u0627\u062c\u0639 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u0634\u0647\u0631\u064a\u0627\u064b \u0648\u0623\u0628\u0644\u063a \u0639\u0646 \u0627\u0644\u0642\u0631\u064a\u0628 \u0645\u0646 \u0627\u0644\u0627\u0646\u062a\u0647\u0627\u0621\n\n\ud83d\udca1 FEFO \u064a\u0636\u0645\u0646: \u0644\u0627 \u0644\u0642\u0627\u062d \u064a\u0646\u062a\u0647\u064a \u062f\u0648\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645!","\ud83d\udd2c \u0627\u0644\u062a\u0631\u0635\u062f \u0627\u0644\u0648\u0628\u0627\u0626\u064a \u0644\u0644\u0623\u0645\u0631\u0627\u0636 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0628\u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 \u0627\u0644\u062a\u0631\u0635\u062f \u0627\u0644\u0648\u0628\u0627\u0626\u064a\u061f\n\u0647\u0648 \u0646\u0638\u0627\u0645 \u0645\u0633\u062a\u0645\u0631 \u0644\u062c\u0645\u0639 \u0648\u062a\u062d\u0644\u064a\u0644 \u0648\u062a\u0641\u0633\u064a\u0631 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0642\u0629 \u0628\u0627\u0644\u0623\u0645\u0631\u0627\u0636\u060c \u0628\u0647\u062f\u0641 \u0627\u0643\u062a\u0634\u0627\u0641 \u0627\u0644\u0623\u0648\u0628\u0626\u0629 \u0645\u0628\u0643\u0631\u0627\u064b \u0648\u0627\u062a\u062e\u0627\u0630 \u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0648\u0642\u0627\u0626\u064a\u0629.\n\n\ud83c\udfaf \u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0628\u0627\u0644\u062a\u0631\u0635\u062f:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 \u0634\u0644\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 (Acute Flaccid Paralysis \u2014 AFP)\n\u2022 \u0627\u0644\u062d\u0635\u0628\u0629 (Measles)\n\u2022 \u0627\u0644\u062d\u0635\u0628\u0629 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064a\u0629 (Rubella/CRS)\n\u2022 \u0627\u0644\u0643\u0632\u0627\u0632 \u0627\u0644\u0648\u0644\u064a\u062f\u064a (Neonatal Tetanus)\n\u2022 \u0627\u0644\u062e\u0646\u0627\u0642 (Diphtheria)\n\u2022 \u0627\u0644\u0633\u0639\u0627\u0644 \u0627\u0644\u062f\u064a\u0643\u064a (Pertussis)\n\n\ud83d\udccb \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062a\u0631\u0635\u062f:\n1\ufe0f\u20e3 \u062a\u0631\u0635\u062f \u0631\u0648\u062a\u064a\u0646\u064a: \u062a\u0642\u0627\u0631\u064a\u0631 \u0623\u0633\u0628\u0648\u0639\u064a\u0629/\u0634\u0647\u0631\u064a\u0629 \u0645\u0646\u062a\u0638\u0645\u0629\n2\ufe0f\u20e3 \u062a\u0631\u0635\u062f \u0641\u0648\u0631\u064a: \u0625\u0628\u0644\u0627\u063a \u0641\u0648\u0631\u064a \u0644\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0645\u0634\u0628\u0648\u0647\u0629 (\u062e\u0644\u0627\u0644 24 \u0633\u0627\u0639\u0629)\n3\ufe0f\u20e3 \u062a\u0631\u0635\u062f \u0646\u0634\u0637: \u0627\u0644\u0628\u062d\u062b \u0627\u0644\u0646\u0634\u0637 \u0639\u0646 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0641\u064a \u0627\u0644\u0645\u062c\u062a\u0645\u0639\n4\ufe0f\u20e3 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u0635\u0641\u0631\u064a (Zero Reporting): \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u062d\u062a\u0649 \u0644\u0648 \u0644\u0645 \u062a\u0643\u0646 \u062d\u0627\u0644\u0627\u062a\n\n\ud83d\udccc \u062a\u0639\u0631\u064a\u0641\u0627\u062a \u0627\u0644\u062d\u0627\u0644\u0627\u062a:\n\u2022 \u062d\u0627\u0644\u0629 \u0645\u0634\u062a\u0628\u0647\u0629: \u0623\u0639\u0631\u0627\u0636 \u0645\u062a\u0648\u0627\u0641\u0642\u0629 \u0628\u062f\u0648\u0646 \u062a\u0623\u0643\u064a\u062f \u0645\u062e\u0628\u0631\u064a\n\u2022 \u062d\u0627\u0644\u0629 \u0645\u0624\u0643\u062f\u0629: \u062a\u0623\u0643\u064a\u062f \u0645\u062e\u0628\u0631\u064a \u0623\u0648 \u0648\u0628\u0627\u0626\u064a\n\u2022 \u062d\u0627\u0644\u0629 \u0645\u062a\u0648\u0627\u0641\u0642\u0629: \u0623\u0639\u0631\u0627\u0636 \u0645\u062a\u0648\u0627\u0641\u0642\u0629 \u0628\u062f\u0648\u0646 \u0639\u064a\u0646\u0629\n\n\ud83d\udca1 \u0627\u0644\u062a\u0631\u0635\u062f \u0627\u0644\u0645\u0628\u0643\u0631 \u064a\u0646\u0642\u0630 \u0627\u0644\u0623\u0631\u0648\u0627\u062d!","\ud83d\udea8 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0644\u0644\u0623\u0648\u0628\u0626\u0629 \u2014 \u062e\u0637\u0648\u0627\u062a \u0639\u0645\u0644\u064a\u0629:\n\n\ud83d\udccc \u062e\u0637\u0648\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u0623\u0643\u062f \u0648\u0627\u0644\u062a\u062d\u0642\u0642:\n   \u2022 \u062a\u0623\u0643\u064a\u062f \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0645\u062e\u0628\u0631\u064a\u0627\u064b\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0639\u062f\u062f \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0648\u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0645\u062a\u0623\u062b\u0631\u0629\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0641\u0626\u0629 \u0627\u0644\u0639\u0645\u0631\u064a\u0629 \u0627\u0644\u0623\u0643\u062b\u0631 \u062a\u0623\u062b\u0631\u0627\u064b\n\n2\ufe0f\u20e3 \u0627\u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0648\u0628\u0627\u0626\u064a:\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0645\u0635\u062f\u0631 \u0627\u0644\u0639\u062f\u0648\u0649\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0641\u062a\u0631\u0629 \u0627\u0644\u0632\u0645\u0646\u064a\u0629 \u0644\u0644\u062a\u0641\u0634\u064a\n   \u2022 \u0631\u0633\u0645 \u062e\u0631\u064a\u0637\u0629 \u0644\u0644\u062d\u0627\u0644\u0627\u062a\n\n3\ufe0f\u20e3 \u0627\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u062a\u0635\u062d\u064a\u062d\u064a\u0629:\n   \u2022 \u062d\u0645\u0644\u0629 \u062a\u062d\u0635\u064a\u0646 \u0627\u0633\u062a\u062c\u0627\u0628\u064a\u0629\n   \u2022 \u062a\u062d\u0635\u064a\u0646 \u062d\u0644\u0642\u064a \u062d\u0648\u0644 \u0627\u0644\u062d\u0627\u0644\u0627\u062a\n   \u2022 \u0639\u0632\u0644 \u0627\u0644\u062d\u0627\u0644\u0627\u062a (\u062d\u0633\u0628 \u0627\u0644\u0645\u0631\u0636)\n   \u2022 \u0627\u0644\u062a\u062b\u0642\u064a\u0641 \u0627\u0644\u0635\u062d\u064a \u0644\u0644\u0645\u062c\u062a\u0645\u0639\n\n4\ufe0f\u20e3 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629:\n   \u2022 \u0631\u0635\u062f \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u064a\u0648\u0645\u064a\u0627\u064b\n   \u2022 \u0645\u0631\u0627\u0642\u0628\u0629 \u0641\u0639\u0627\u0644\u064a\u0629 \u0627\u0644\u062a\u062f\u062e\u0644\n   \u2022 \u062a\u0642\u0631\u064a\u0631 \u0646\u0647\u0627\u0626\u064a \u0628\u0627\u0644\u062f\u0631\u0648\u0633 \u0627\u0644\u0645\u0633\u062a\u0641\u0627\u062f\u0629\n\n\u26a0\ufe0f \u0627\u0644\u0633\u0631\u0639\u0629 \u0641\u064a \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 = \u0627\u062d\u062a\u0648\u0627\u0621 \u0623\u0633\u0631\u0639 \u0644\u0644\u0648\u0628\u0627\u0621!","\u26a0\ufe0f \u0631\u0635\u062f \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0627\u0644\u0636\u0627\u0626\u0631\u0629 \u0628\u0639\u062f \u0627\u0644\u062a\u0637\u0639\u064a\u0645 (AEFI Surveillance):\n\n\ud83d\udccc \u0646\u0638\u0627\u0645 \u0631\u0635\u062f AEFI:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0631\u0641\u0642 \u0627\u0644\u0635\u062d\u064a:\n   \u2022 \u062a\u0633\u062c\u064a\u0644 \u0623\u064a \u062d\u062f\u062b \u0636\u0627\u0626\u0631 \u0628\u0639\u062f \u0627\u0644\u062a\u0637\u0639\u064a\u0645\n   \u2022 \u062a\u0639\u0628\u0626\u0629 \u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0627\u0644\u0623\u0648\u0644\u064a\n   \u2022 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u062e\u0644\u0627\u0644 24 \u0633\u0627\u0639\u0629 \u0644\u0644\u0623\u062d\u062f\u0627\u062b \u0627\u0644\u062e\u0637\u064a\u0631\u0629\n\n2\ufe0f\u20e3 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0629:\n   \u2022 \u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0645\u0646 \u0627\u0644\u0645\u0631\u0627\u0641\u0642\n   \u2022 \u0627\u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0623\u0648\u0644\u064a \u0641\u064a \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0627\u0644\u062e\u0637\u064a\u0631\u0629\n   \u2022 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0644\u0644\u0645\u062d\u0627\u0641\u0638\u0629\n\n3\ufe0f\u20e3 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629:\n   \u2022 \u062a\u062d\u0644\u064a\u0644 \u0628\u064a\u0627\u0646\u0627\u062a AEFI\n   \u2022 \u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u062a\u062d\u0642\u064a\u0642\u0627\u062a \u0627\u0644\u0645\u0639\u0642\u062f\u0629\n   \u2022 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0644\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0648\u0637\u0646\u064a\n\n\ud83d\udccb \u0623\u062d\u062f\u0627\u062b \u062a\u064f\u0628\u0644\u063a \u0641\u0648\u0631\u0627\u064b (\u062e\u0644\u0627\u0644 24 \u0633\u0627\u0639\u0629):\n\u2022 \u0627\u0644\u0648\u0641\u0627\u0629 \u0628\u0639\u062f \u0627\u0644\u062a\u0637\u0639\u064a\u0645\n\u2022 \u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u062e\u0637\u064a\u0631\u0629 \u0627\u0644\u0645\u0647\u062f\u062f\u0629 \u0644\u0644\u062d\u064a\u0627\u0629\n\u2022 \u0627\u0644\u062a\u0634\u0646\u062c\u0627\u062a\n\u2022 \u0631\u062f \u0627\u0644\u0641\u0639\u0644 \u0627\u0644\u062a\u062d\u0633\u0633\u064a \u0627\u0644\u0634\u062f\u064a\u062f (Anaphylaxis)\n\u2022 \u0634\u0644\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0645\u0631\u062a\u0628\u0637 \u0628\u0627\u0644\u0644\u0642\u0627\u062d\n\u2022 \u0627\u0644\u062a\u062c\u0645\u0639 \u063a\u064a\u0631 \u0627\u0644\u0639\u0627\u062f\u064a \u0644\u0623\u062d\u062f\u0627\u062b \u0636\u0627\u0626\u0631\u0629\n\n\ud83d\udca1 \u0627\u0644\u0631\u0635\u062f \u0627\u0644\u062c\u064a\u062f = \u062b\u0642\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 + \u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c!","\ud83c\udfeb \u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0645\u062f\u0627\u0631\u0633 \u2014 \u062f\u0644\u064a\u0644 \u0627\u0644\u062a\u0646\u0641\u064a\u0630:\n\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0645\u062f\u0627\u0631\u0633\u061f\n\u2022 \u0627\u0644\u0645\u062f\u0627\u0631\u0633 \u0623\u0645\u0627\u0643\u0646 \u062a\u062c\u0645\u0639 \u064a\u0633\u0647\u0644 \u0641\u064a\u0647\u0627 \u0627\u0646\u062a\u0634\u0627\u0631 \u0627\u0644\u0639\u062f\u0648\u0649\n\u2022 \u0627\u0644\u062c\u0631\u0639\u0627\u062a \u0627\u0644\u0645\u0639\u0632\u0632\u0629 \u062a\u0636\u0645\u0646 \u0627\u0633\u062a\u0645\u0631\u0627\u0631 \u0627\u0644\u062d\u0645\u0627\u064a\u0629\n\u2022 \u0628\u0639\u0636 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0644\u0645 \u064a\u0643\u0645\u0644\u0648\u0627 \u062a\u062d\u0635\u064a\u0646\u0647\u0645 \u0627\u0644\u0631\u0648\u062a\u064a\u0646\u064a\n\u2022 \u062a\u0648\u0641\u064a\u0631 \u062d\u0645\u0627\u064a\u0629 \u0645\u062c\u062a\u0645\u0639\u064a\u0629 \u0641\u064a \u0627\u0644\u0628\u064a\u0626\u0629 \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629\n\n\ud83d\udccb \u0627\u0644\u062a\u0637\u0639\u064a\u0645\u0627\u062a \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0639\u0646\u062f \u062f\u062e\u0648\u0644 \u0627\u0644\u0645\u062f\u0631\u0633\u0629 (5-7 \u0633\u0646\u0648\u0627\u062a):\n   \u2022 Penta4 (\u062e\u0645\u0627\u0633\u064a \u062a\u0639\u0632\u064a\u0632\u064a\u0629) \u2014 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u064a\u0633\u0631\n   \u2022 MR \u0645\u0639\u0632\u0632\u0629 \u2014 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u064a\u0645\u0646\n   \u2022 \u0641\u064a\u062a\u0627\u0645\u064a\u0646 \u0623 (200,000 \u0648.\u062f)\n\n2\ufe0f\u20e3 \u0644\u0644\u0628\u0646\u0627\u062a (12 \u0633\u0646\u0629):\n   \u2022 Td (\u0627\u0644\u0643\u0632\u0627\u0632 \u0648\u0627\u0644\u062e\u0646\u0627\u0642)\n\n\ud83c\udfaf \u0622\u0644\u064a\u0629 \u0627\u0644\u062a\u0646\u0641\u064a\u0630:\n   \u2022 \u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0645\u0639 \u0642\u0637\u0627\u0639 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\n   \u2022 \u0625\u0639\u0644\u0627\u0645 \u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u0623\u0645\u0648\u0631 \u0645\u0633\u0628\u0642\u0627\u064b\n   \u2022 \u062a\u062f\u0631\u064a\u0628 \u0641\u0631\u0642 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0645\u062f\u0631\u0633\u064a\n   \u2022 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0641\u064a \u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u062a\u0644\u0645\u064a\u0630\n\n\u26a0\ufe0f \u062a\u062d\u062f\u064a\u0627\u062a:\n\u2022 \u0639\u062f\u0645 \u062a\u0639\u0627\u0648\u0646 \u0628\u0639\u0636 \u0627\u0644\u0645\u062f\u0627\u0631\u0633\n\u2022 \u0631\u0641\u0636 \u0628\u0639\u0636 \u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u0623\u0645\u0648\u0631\n\u2022 \u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0645\u062f\u0627\u0631\u0633 \u0641\u064a \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0646\u0627\u0626\u064a\u0629\n\n\ud83d\udca1 \u0627\u0644\u0645\u062f\u0631\u0633\u0629 = \u0623\u0641\u0636\u0644 \u0645\u0643\u0627\u0646 \u0644\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0623\u0637\u0641\u0627\u0644!","\ud83d\udcca \u062c\u0648\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0641\u064a \u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0623\u0628\u0639\u0627\u062f \u062c\u0648\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062f\u0642\u0629 (Accuracy):\n   \u2022 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0645\u0637\u0627\u0628\u0642\u0629 \u0644\u0644\u0648\u0627\u0642\u0639\n   \u2022 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0645\u0646 \u0645\u0635\u0627\u062f\u0631 \u0645\u062a\u0639\u062f\u062f\u0629\n   \u2022 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u062a\u0646\u0627\u0633\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0631\u0639\u0627\u062a\n\n2\ufe0f\u20e3 \u0627\u0644\u0627\u0643\u062a\u0645\u0627\u0644 (Completeness):\n   \u2022 \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0642\u0648\u0644 \u0645\u0645\u0644\u0648\u0621\u0629\n   \u2022 \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u0623\u0628\u0644\u063a\u062a\n   \u2022 \u062c\u0645\u064a\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0645\u064f\u0633\u062c\u0644\u0629\n\n3\ufe0f\u20e3 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 (Timeliness):\n   \u2022 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u062a\u064f\u0633\u0644\u0651\u0645 \u0641\u064a \u0627\u0644\u0645\u0648\u0639\u062f\n   \u2022 \u0644\u0627 \u062a\u0623\u062e\u064a\u0631 \u0641\u064a \u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\n\n4\ufe0f\u20e3 \u0627\u0644\u0627\u062a\u0633\u0627\u0642 (Consistency):\n   \u2022 Penta1 \u2265 Penta2 \u2265 Penta3 (\u0639\u0627\u062f\u0629)\n   \u2022 \u0644\u0627 \u062a\u063a\u0637\u064a\u0629 \u0623\u0639\u0644\u0649 \u0645\u0646 100% \u0628\u062f\u0648\u0646 \u062a\u0641\u0633\u064a\u0631\n   \u2022 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0645\u062a\u0637\u0627\u0628\u0642\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u0635\u0627\u062f\u0631\n\n\ud83d\udccb \u0641\u062d\u0648\u0635 \u062c\u0648\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a:\n\u2022 \u0641\u062d\u0635 \u0627\u0644\u062a\u0646\u0627\u0633\u0628: Penta1 > Penta2 > Penta3\n\u2022 \u0641\u062d\u0635 \u0627\u0644\u0642\u064a\u0645 \u0627\u0644\u0634\u0627\u0630\u0629: \u062a\u063a\u0637\u064a\u0629 >120% \u0623\u0648 <20%\n\u2022 \u0641\u062d\u0635 \u0627\u0644\u0627\u0643\u062a\u0645\u0627\u0644: \u0647\u0644 \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u0623\u0628\u0644\u063a\u062a\u061f\n\u2022 \u0641\u062d\u0635 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645: \u0647\u0644 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0641\u064a \u0627\u0644\u0645\u0648\u0639\u062f\u061f\n\n\ud83d\udca1 \u0628\u064a\u0627\u0646\u0627\u062a \u062c\u064a\u062f\u0629 = \u0642\u0631\u0627\u0631\u0627\u062a \u0635\u062d\u064a\u062d\u0629 = \u062a\u063a\u0637\u064a\u0629 \u0623\u0639\u0644\u0649!","\ud83d\udce2 \u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u0637\u0644\u0628 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 (Demand Generation):\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 \u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u0637\u0644\u0628\u061f\n\u0647\u0648 \u0645\u062c\u0645\u0648\u0639\u0629 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u064a \u062a\u0647\u062f\u0641 \u0625\u0644\u0649 \u0632\u064a\u0627\u062f\u0629 \u0625\u0642\u0628\u0627\u0644 \u0627\u0644\u0623\u0633\u0631 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u062a\u062d\u0648\u064a\u0644\u0647 \u0645\u0646 \u062e\u062f\u0645\u0629 \u0645\u062a\u0627\u062d\u0629 \u0641\u0642\u0637 \u0625\u0644\u0649 \u062e\u062f\u0645\u0629 \u0645\u0637\u0644\u0648\u0628\u0629 \u0628\u0634\u062f\u0629.\n\n\ud83c\udfaf \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u0637\u0644\u0628:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u0648\u0639\u064a\u0629 \u0627\u0644\u0635\u062d\u064a\u0629:\n   \u2022 \u0645\u062d\u0627\u0636\u0631\u0627\u062a \u0641\u064a \u0627\u0644\u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u0635\u062d\u064a\u0629\n   \u2022 \u0646\u0634\u0631\u0627\u062a \u0648\u0645\u0637\u0648\u064a\u0627\u062a \u0628\u0644\u063a\u0629 \u0628\u0633\u064a\u0637\u0629\n   \u2022 \u0628\u0631\u0627\u0645\u062c \u0625\u0630\u0627\u0639\u064a\u0629 \u0648\u062a\u0644\u0641\u0632\u064a\u0648\u0646\u064a\u0629\n   \u2022 \u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\n\n2\ufe0f\u20e3 \u0625\u0634\u0631\u0627\u0643 \u0642\u0627\u062f\u0629 \u0627\u0644\u0631\u0623\u064a:\n   \u2022 \u0627\u0644\u0645\u0634\u0627\u064a\u062e \u064a\u062a\u062d\u062f\u062b\u0648\u0646 \u0639\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0641\u064a \u0627\u0644\u062e\u0637\u0628\n   \u2022 \u0627\u0644\u0645\u0639\u0644\u0645\u0648\u0646 \u064a\u062b\u0642\u0641\u0648\u0646 \u0627\u0644\u0637\u0644\u0627\u0628\n   \u2022 \u0627\u0644\u0646\u0633\u0627\u0621 \u0627\u0644\u0642\u064a\u0627\u062f\u064a\u0627\u062a \u064a\u0646\u0634\u0631\u0646 \u0627\u0644\u0648\u0639\u064a\n\n3\ufe0f\u20e3 \u0627\u0644\u062a\u0630\u0643\u064a\u0631 \u0648\u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629:\n   \u2022 \u0631\u0633\u0627\u0626\u0644 SMS \u0642\u0628\u0644 \u0645\u0648\u0639\u062f \u0627\u0644\u062a\u0637\u0639\u064a\u0645\n   \u2022 \u0632\u064a\u0627\u0631\u0627\u062a \u0645\u0646\u0632\u0644\u064a\u0629 \u0645\u0646 \u0627\u0644\u0645\u062a\u0637\u0648\u0639\u064a\u0646\n   \u2022 \u0628\u0637\u0627\u0642\u0627\u062a \u062a\u0630\u0643\u064a\u0631 \u0645\u0644\u0648\u0646\u0629\n\n4\ufe0f\u20e3 \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u062a\u0631\u062f\u062f:\n   \u2022 \u0641\u0647\u0645 \u0623\u0633\u0628\u0627\u0628 \u0627\u0644\u062a\u0631\u062f\u062f\n   \u2022 \u062a\u0642\u062f\u064a\u0645 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0645\u0648\u062b\u0648\u0642\u0629\n   \u2022 \u0625\u0634\u0631\u0627\u0643 \u0623\u0637\u0628\u0627\u0621 \u0645\u0648\u062b\u0648\u0642\u064a\u0646\n\n\ud83d\udca1 \u0637\u0644\u0628 \u0645\u0631\u062a\u0641\u0639 = \u062a\u063a\u0637\u064a\u0629 \u0623\u0639\u0644\u0649 = \u0645\u062c\u062a\u0645\u0639 \u0623\u0643\u062b\u0631 \u0623\u0645\u0627\u0646\u0627\u064b!","\ud83e\udd1d \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629 \u0641\u064a \u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629\u061f\n\u0647\u064a \u0625\u0634\u0631\u0627\u0643 \u0623\u0641\u0631\u0627\u062f \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0648\u0642\u0627\u062f\u062a\u0647 \u0641\u064a \u062a\u062e\u0637\u064a\u0637 \u0648\u062a\u0646\u0641\u064a\u0630 \u0648\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\u060c \u0628\u062d\u064a\u062b \u064a\u0635\u0628\u062d\u0648\u0646 \u0634\u0631\u0643\u0627\u0621 \u0641\u0627\u0639\u0644\u064a\u0646 \u0648\u0644\u064a\u0633\u0648\u0627 \u0645\u0633\u062a\u0641\u064a\u062f\u064a\u0646 \u0641\u0642\u0637.\n\n\ud83c\udfaf \u0634\u0631\u0627\u0643\u0627\u062a \u0645\u0647\u0645\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u0645\u0634\u0627\u064a\u062e \u0648\u0627\u0644\u0623\u0626\u0645\u0629:\n   \u2022 \u0627\u0644\u062d\u062f\u064a\u062b \u0639\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0641\u064a \u0627\u0644\u062e\u0637\u0628\n   \u2022 \u0641\u0636 \u0627\u0644\u0634\u0627\u0626\u0639\u0627\u062a \u0627\u0644\u062f\u064a\u0646\u064a\u0629\n   \u2022 \u062a\u0634\u062c\u064a\u0639 \u0627\u0644\u0623\u0633\u0631 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\n2\ufe0f\u20e3 \u0627\u0644\u0642\u0627\u0628\u0644\u0627\u062a \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a\u0627\u062a:\n   \u2022 \u0625\u062d\u0627\u0644\u0629 \u0627\u0644\u0645\u0648\u0627\u0644\u064a\u062f \u0627\u0644\u062c\u062f\u062f \u0644\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u062a\u062a\u0628\u0639 \u0627\u0644\u0623\u0645\u0647\u0627\u062a \u0627\u0644\u062d\u0648\u0627\u0645\u0644\n   \u2022 \u0627\u0644\u062a\u0648\u0639\u064a\u0629 \u0641\u064a \u0627\u0644\u0623\u062d\u064a\u0627\u0621 \u0627\u0644\u0646\u0627\u0626\u064a\u0629\n\n3\ufe0f\u20e3 \u0627\u0644\u0645\u0639\u0644\u0645\u0648\u0646 \u0648\u0627\u0644\u0645\u0639\u0644\u0645\u0627\u062a:\n   \u2022 \u062a\u062b\u0642\u064a\u0641 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0639\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0644\u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0645\u062f\u0631\u0633\u064a\n   \u2022 \u0645\u062a\u0627\u0628\u0639\u0629 \u0628\u0637\u0627\u0642\u0627\u062a \u062a\u0637\u0639\u064a\u0645 \u0627\u0644\u0637\u0644\u0627\u0628\n\n4\ufe0f\u20e3 \u0644\u062c\u0627\u0646 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0627\u0644\u0645\u062d\u0644\u064a:\n   \u2022 \u0644\u062c\u0627\u0646 \u0627\u0644\u0635\u062d\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629\n   \u2022 \u0645\u062a\u0637\u0648\u0639\u0648\u0646 \u0644\u062a\u062a\u0628\u0639 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u064a\u0646\n   \u2022 \u0648\u0633\u0637\u0627\u0621 \u0628\u064a\u0646 \u0627\u0644\u0645\u0631\u0641\u0642 \u0627\u0644\u0635\u062d\u064a \u0648\u0627\u0644\u0645\u062c\u062a\u0645\u0639\n\n\ud83d\udca1 \u0645\u062c\u062a\u0645\u0639 \u0645\u064f\u0634\u0627\u0631\u0643 = \u0628\u0631\u0646\u0627\u0645\u062c \u062a\u062d\u0635\u064a\u0646 \u0623\u0642\u0648\u0649 \u0648\u0623\u0633\u062a\u0645\u0631!",'\ud83d\uded1 \u0645\u0643\u0627\u0641\u062d\u0629 \u0627\u0644\u0634\u0627\u0626\u0639\u0627\u062a \u0639\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0634\u0627\u0626\u0639\u0627\u062a \u0627\u0644\u0634\u0627\u0626\u0639\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u274c "\u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u062a\u0633\u0628\u0628 \u0627\u0644\u0639\u0642\u0645"\n\u274c "\u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0645\u064f\u0633\u0645\u0645\u0629"\n\u274c "\u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0645\u0624\u0627\u0645\u0631\u0629 \u0623\u062c\u0646\u0628\u064a\u0629"\n\u274c "\u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u062a\u062d\u062a\u0648\u064a \u0639\u0644\u0649 \u062e\u0646\u0627\u0632\u064a\u0631"\n\u274c "\u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u064a\u0633\u0628\u0628 \u0627\u0644\u062a\u0648\u062d\u062f"\n\n\ud83d\udccb \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0644\u0645\u0643\u0627\u0641\u062d\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0648\u0627\u0644\u062a\u0641\u0647\u0645:\n   \u2022 \u0644\u0627 \u062a\u0633\u062e\u0631 \u0645\u0646 \u0627\u0644\u0645\u062e\u0627\u0648\u0641\n   \u2022 \u0627\u0633\u0645\u0639 \u062c\u064a\u062f\u0627\u064b \u062b\u0645 \u0631\u062f\u0651\n   \u2022 \u0627\u0641\u0647\u0645 \u0645\u0635\u062f\u0631 \u0627\u0644\u0642\u0644\u0642\n\n2\ufe0f\u20e3 \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062d\u0642\u0627\u0626\u0642:\n   \u2022 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0628\u0633\u064a\u0637\u0629 \u0648\u0645\u0628\u0627\u0634\u0631\u0629\n   \u2022 \u0644\u063a\u0629 \u064a\u0641\u0647\u0645\u0647\u0627 \u0627\u0644\u062c\u0645\u064a\u0639\n   \u2022 \u0623\u062f\u0644\u0629 \u0645\u0646 \u0645\u0635\u0627\u062f\u0631 \u0645\u0648\u062b\u0648\u0642\u0629 (WHO, Quran)\n\n3\ufe0f\u20e3 \u0625\u0634\u0631\u0627\u0643 \u0639\u0644\u0645\u0627\u0621 \u0627\u0644\u062f\u064a\u0646:\n   \u2022 \u0641\u062a\u0627\u0648\u0649 \u062a\u062f\u0639\u0645 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0625\u0633\u0644\u0627\u0645\u064a\u0627\u064b: \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u062d\u0641\u0638 \u0644\u0644\u0646\u0641\u0633 (\u0636\u0631\u0648\u0631\u0629)\n   \u2022 \u0627\u0644\u0645\u0634\u0627\u064a\u062e \u064a\u0624\u062b\u0631\u0648\u0646 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a\n\n4\ufe0f\u20e3 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0633\u0631\u064a\u0639\u0629:\n   \u2022 \u0631\u0635\u062f \u0627\u0644\u0634\u0627\u0626\u0639\u0627\u062a \u0641\u0648\u0631 \u0638\u0647\u0648\u0631\u0647\u0627\n   \u2022 \u0627\u0644\u0631\u062f \u0627\u0644\u0633\u0631\u064a\u0639 \u0642\u0628\u0644 \u0627\u0646\u062a\u0634\u0627\u0631\u0647\u0627\n   \u2022 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0642\u0646\u0648\u0627\u062a \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\n\n\ud83d\udca1 \u0634\u0627\u0626\u0639\u0629 \u0628\u062f\u0648\u0646 \u0631\u062f\u0651 = \u062e\u0637\u0631 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0627\u0644\u0645\u0631\u0636 \u0646\u0641\u0633\u0647!',"\ud83d\udcda \u0627\u0644\u062a\u062b\u0642\u064a\u0641 \u0627\u0644\u0635\u062d\u064a \u0644\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u062f\u0644\u064a\u0644 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629:\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 \u0627\u0644\u062a\u062b\u0642\u064a\u0641 \u0627\u0644\u0635\u062d\u064a\u061f\n\u0647\u0648 \u0639\u0645\u0644\u064a\u0629 \u0646\u0642\u0644 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0635\u062d\u064a\u0629 \u0644\u0644\u0623\u0641\u0631\u0627\u062f \u0648\u0627\u0644\u0645\u062c\u062a\u0645\u0639\u0627\u062a \u0628\u0637\u0631\u064a\u0642\u0629 \u062a\u0641\u0627\u0639\u0644\u064a\u0629 \u062a\u064f\u063a\u064a\u0651\u0631 \u0627\u0644\u0633\u0644\u0648\u0643 \u0648\u062a\u0639\u0632\u0632 \u0627\u0644\u0635\u062d\u0629.\n\n\ud83c\udfaf \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u062a\u062b\u0642\u064a\u0641 \u0627\u0644\u0641\u0639\u0627\u0644:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u062c\u0645\u0647\u0648\u0631:\n   \u2022 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0648\u0627\u0644\u0648\u0639\u064a\n   \u2022 \u0627\u0644\u0645\u0639\u062a\u0642\u062f\u0627\u062a \u0648\u0627\u0644\u0642\u064a\u0645\n   \u2022 \u0627\u0644\u0644\u063a\u0629 \u0648\u0627\u0644\u0645\u0635\u0637\u0644\u062d\u0627\u062a\n\n2\ufe0f\u20e3 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u0648\u0627\u0636\u062d\u0629:\n   \u2022 \u0628\u0633\u064a\u0637\u0629 \u0648\u0645\u0628\u0627\u0634\u0631\u0629\n   \u2022 \u0625\u064a\u062c\u0627\u0628\u064a\u0629 (\u0644\u0627 \u062a\u062e\u0648\u064a\u0641)\n   \u2022 \u0639\u0645\u0644\u064a\u0629 \u0648\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062a\u0637\u0628\u064a\u0642\n   \u2022 \u0645\u0639 \u0623\u0645\u062b\u0644\u0629 \u0645\u062d\u0644\u064a\u0629\n\n3\ufe0f\u20e3 \u0627\u0644\u0648\u0633\u064a\u0644\u0629 \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629:\n   \u2022 \u0648\u062c\u0647\u0627\u064b \u0644\u0648\u062c\u0647 (\u0627\u0644\u0623\u0643\u062b\u0631 \u062a\u0623\u062b\u064a\u0631\u0627\u064b)\n   \u2022 \u0645\u062c\u0645\u0648\u0639\u0627\u062a \u0635\u063a\u064a\u0631\u0629 (\u0623\u0645\u0647\u0627\u062a\u060c \u0646\u0633\u0627\u0621)\n   \u2022 \u0648\u0633\u0627\u0626\u0644 \u0625\u0639\u0644\u0627\u0645 (\u0631\u0627\u062f\u064a\u0648\u060c \u062a\u0644\u0641\u0632\u064a\u0648\u0646)\n   \u2022 \u0645\u0648\u0627\u062f \u0645\u0637\u0628\u0648\u0639\u0629 (\u0645\u0637\u0648\u064a\u0627\u062a\u060c \u0645\u0644\u0635\u0642\u0627\u062a)\n\n4\ufe0f\u20e3 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629:\n   \u2022 \u0647\u0644 \u062a\u063a\u064a\u0631 \u0627\u0644\u0633\u0644\u0648\u0643 \u0641\u0639\u0644\u0627\u064b\u061f\n   \u2022 \u0647\u0644 \u0632\u0627\u062f\u062a \u0646\u0633\u0628\u0629 \u0627\u0644\u0625\u0642\u0628\u0627\u0644\u061f\n   \u2022 \u0645\u0627 \u0627\u0644\u0630\u064a \u064a\u062d\u062a\u0627\u062c \u062a\u062d\u0633\u064a\u0646\u061f\n\n\ud83d\udca1 \u062a\u062b\u0642\u064a\u0641 \u0641\u0639\u0651\u0627\u0644 = \u0633\u0644\u0648\u0643 \u0645\u062a\u063a\u064a\u0631 = \u062a\u063a\u0637\u064a\u0629 \u0623\u0639\u0644\u0649!","\ud83d\udd17 \u0627\u0644\u062a\u0643\u0627\u0645\u0644 \u0628\u064a\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u0627\u0644\u0628\u0631\u0627\u0645\u062c \u0627\u0644\u0635\u062d\u064a\u0629 \u0627\u0644\u0623\u062e\u0631\u0649:\n\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u0627\u0644\u062a\u0643\u0627\u0645\u0644 \u0645\u0647\u0645\u061f\n\u2022 \u0632\u064a\u0627\u062f\u0629 \u0641\u0631\u0635 \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0623\u0637\u0641\u0627\u0644\n\u2022 \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u062a\u0643\u0627\u0644\u064a\u0641 \u0648\u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a\n\u2022 \u062a\u0639\u0632\u064a\u0632 \u0634\u0645\u0648\u0644\u064a\u0629 \u0627\u0644\u062e\u062f\u0645\u0627\u062a\n\n\ud83c\udfaf \u0641\u0631\u0635 \u0627\u0644\u062a\u0643\u0627\u0645\u0644:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 + \u0627\u0644\u062a\u063a\u0630\u064a\u0629:\n   \u2022 \u062a\u0643\u0645\u064a\u0645 \u0641\u064a\u062a\u0627\u0645\u064a\u0646 \u0623 \u0645\u0639 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0641\u062d\u0635 \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0623\u062b\u0646\u0627\u0621 \u062c\u0644\u0633\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0625\u062d\u0627\u0644\u0629 \u0633\u0648\u0621 \u0627\u0644\u062a\u063a\u0630\u064a\u0629\n\n2\ufe0f\u20e3 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 + \u0635\u062d\u0629 \u0627\u0644\u0623\u0645:\n   \u2022 Td \u0644\u0644\u062d\u0645\u0644 \u0645\u0639 \u0627\u0644\u0631\u0639\u0627\u064a\u0629 \u0642\u0628\u0644 \u0627\u0644\u0648\u0644\u0627\u062f\u0629\n   \u2022 \u062a\u0637\u0639\u064a\u0645 \u0627\u0644\u0623\u0645\u0647\u0627\u062a \u0641\u064a \u0632\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629\n   \u2022 \u0627\u0633\u062a\u0647\u062f\u0627\u0641 \u0627\u0644\u062d\u0648\u0627\u0645\u0644 \u0644\u0644\u062a\u0648\u0639\u064a\u0629\n\n3\ufe0f\u20e3 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 + \u0645\u0643\u0627\u0641\u062d\u0629 \u0627\u0644\u0645\u0644\u0627\u0631\u064a\u0627:\n   \u2022 \u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0646\u0627\u0645\u0648\u0633\u064a\u0627\u062a \u0645\u0639 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0641\u062d\u0635 \u0627\u0644\u0645\u0644\u0627\u0631\u064a\u0627 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062c\u0644\u0633\u0627\u062a\n\n4\ufe0f\u20e3 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 + \u0641\u064a\u062a\u0627\u0645\u064a\u0646 \u0623:\n   \u2022 \u062a\u0643\u0645\u064a\u0645 \u0641\u064a\u062a\u0627\u0645\u064a\u0646 \u0623 \u0645\u0639 \u062a\u0637\u0639\u064a\u0645\u0627\u062a 12 \u064818 \u0634\u0647\u0631\n   \u2022 \u062d\u0645\u0644\u0627\u062a \u0645\u0634\u062a\u0631\u0643\u0629\n\n\ud83d\udca1 \u062a\u0643\u0627\u0645\u0644 \u0627\u0644\u062e\u062f\u0645\u0627\u062a = \u062a\u063a\u0637\u064a\u0629 \u0623\u0634\u0645\u0644 + \u0643\u0641\u0627\u0621\u0629 \u0623\u0639\u0644\u0649!","\ud83d\udcdd \u062a\u0648\u062b\u064a\u0642 \u0627\u0644\u062a\u0637\u0639\u064a\u0645\u0627\u062a \u2014 \u0623\u0647\u0645\u064a\u0629 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0648\u0627\u0644\u0633\u062c\u0644\u0627\u062a:\n\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u0627\u0644\u062a\u0648\u062b\u064a\u0642 \u0645\u0647\u0645\u061f\n\u2022 \u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u0644\u0642\u0627\u0647\u0627 \u0627\u0644\u0637\u0641\u0644\n\u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0645\u062a\u0628\u0642\u064a\u0629\n\u2022 \u062a\u062c\u0646\u0628 \u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u062c\u0631\u0639\u0627\u062a\n\u2022 \u0625\u062b\u0628\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0639\u0646\u062f \u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0628\u0627\u0644\u0645\u062f\u0631\u0633\u0629\n\u2022 \u0628\u064a\u0627\u0646\u0627\u062a \u0644\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u0631\u0635\u062f\n\n\ud83d\udccb \u0623\u062f\u0648\u0627\u062a \u0627\u0644\u062a\u0648\u062b\u064a\u0642:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 (Vaccination Card):\n   \u2022 \u062a\u062d\u0645\u0644 \u0643\u0644 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0637\u0641\u0644\n   \u2022 \u062a\u064f\u062d\u0641\u0638 \u0639\u0646\u062f \u0627\u0644\u0623\u0645\n   \u2022 \u062a\u064f\u0631\u0627\u062c\u0639 \u0641\u064a \u0643\u0644 \u0632\u064a\u0627\u0631\u0629\n   \u2022 \u26a0\ufe0f \u064a\u062c\u0628 \u0625\u062d\u0636\u0627\u0631\u0647\u0627 \u0641\u064a \u0643\u0644 \u0632\u064a\u0627\u0631\u0629!\n\n2\ufe0f\u20e3 \u0633\u062c\u0644 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 (Register):\n   \u2022 \u0641\u064a \u0627\u0644\u0645\u0631\u0641\u0642 \u0627\u0644\u0635\u062d\u064a\n   \u2022 \u064a\u064f\u062d\u062f\u0651\u062b \u064a\u0648\u0645\u064a\u0627\u064b\n   \u2022 \u0645\u0631\u062c\u0639 \u0623\u0633\u0627\u0633\u064a \u0644\u0644\u0628\u064a\u0627\u0646\u0627\u062a\n\n3\ufe0f\u20e3 \u0646\u0638\u0627\u0645 DHIS2:\n   \u2022 \u0627\u0644\u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u0634\u0647\u0631\u064a \u0644\u0644\u0628\u064a\u0627\u0646\u0627\u062a\n   \u2022 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0648\u0627\u0644\u062a\u062d\u0644\u064a\u0644\n\n\ud83d\udca1 \u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 = \u062c\u0648\u0627\u0632 \u0633\u0641\u0631 \u0635\u062d\u064a \u0644\u0637\u0641\u0644\u0643!","\ud83c\udfda\ufe0f \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0641\u064a \u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0637\u0648\u0627\u0631\u0626 \u0648\u0627\u0644\u0646\u0632\u0648\u062d:\n\n\ud83d\udccc \u0627\u0644\u062a\u062d\u062f\u064a\u0627\u062a:\n\u2022 \u062a\u062f\u0645\u064a\u0631 \u0627\u0644\u0645\u0631\u0627\u0641\u0642 \u0627\u0644\u0635\u062d\u064a\u0629\n\u2022 \u0627\u0646\u0642\u0637\u0627\u0639 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n\u2022 \u0646\u0632\u0648\u062d \u0627\u0644\u0633\u0643\u0627\u0646 \u0648\u0641\u0642\u062f\u0627\u0646 \u0627\u0644\u0633\u062c\u0644\u0627\u062a\n\u2022 \u0627\u0632\u062f\u062d\u0627\u0645 \u0627\u0644\u0645\u062e\u064a\u0645\u0627\u062a \u0648\u0627\u0646\u062a\u0634\u0627\u0631 \u0627\u0644\u0639\u062f\u0648\u0649\n\n\ud83c\udfaf \u0623\u0648\u0644\u0648\u064a\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0641\u064a \u0627\u0644\u0637\u0648\u0627\u0631\u0626:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062d\u0635\u0628\u0629 (\u0623\u0648\u0644\u0648\u064a\u0629 \u0642\u0635\u0648\u0649!):\n   \u2022 \u0627\u0644\u0623\u0643\u062b\u0631 \u0641\u062a\u0643\u0627\u064b \u0641\u064a \u0627\u0644\u0645\u062e\u064a\u0645\u0627\u062a\n   \u2022 \u062a\u063a\u0637\u064a\u0629 \u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u226595%\n   \u2022 \u0645\u0646 \u0639\u0645\u0631 6 \u0623\u0634\u0647\u0631 \u0625\u0644\u0649 15 \u0633\u0646\u0629\n\n2\ufe0f\u20e3 \u0634\u0644\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 (OPV):\n   \u2022 \u062d\u0645\u0644\u0627\u062a \u0648\u0637\u0646\u064a\u0629 \u0641\u064a \u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0637\u0648\u0627\u0631\u0626\n   \u2022 \u0641\u0631\u0642 \u0645\u0646 \u0628\u064a\u062a \u0644\u0628\u064a\u062a\n\n3\ufe0f\u20e3 \u0627\u0644\u0643\u0632\u0627\u0632 \u0627\u0644\u0648\u0644\u064a\u062f\u064a (Td):\n   \u2022 \u0644\u0644\u062d\u0648\u0627\u0645\u0644 \u0641\u064a \u0627\u0644\u0645\u062e\u064a\u0645\u0627\u062a\n   \u2022 \u0627\u0644\u0648\u0644\u0627\u062f\u0629 \u063a\u064a\u0631 \u0627\u0644\u0622\u0645\u0646\u0629 \u0634\u0627\u0626\u0639\u0629\n\n4\ufe0f\u20e3 \u0627\u0644\u0643\u0648\u0644\u064a\u0631\u0627:\n   \u2022 \u0644\u0642\u0627\u062d \u0641\u0645\u0648\u064a \u0641\u064a \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0645\u0648\u0628\u0648\u0621\u0629\n   \u2022 \u062d\u0645\u0644\u0627\u062a \u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0633\u0631\u064a\u0639\u0629\n\n\ud83d\udca1 \u062d\u062a\u0649 \u0641\u064a \u0627\u0644\u0637\u0648\u0627\u0631\u0626 \u2014 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0644\u064a\u0633 \u0631\u0641\u0627\u0647\u064a\u0629 \u0628\u0644 \u0636\u0631\u0648\u0631\u0629!","\ud83c\udf10 \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0627\u0644\u062f\u0648\u0644\u064a\u0629 \u0644\u0644\u062a\u0637\u0639\u064a\u0645 (International Certificate of Vaccination):\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0627\u0644\u062f\u0648\u0644\u064a\u0629\u061f\n\u0648\u062b\u064a\u0642\u0629 \u0631\u0633\u0645\u064a\u0629 \u062a\u064f\u062b\u0628\u062a \u062a\u0644\u0642\u064a \u0627\u0644\u0634\u062e\u0635 \u0644\u062a\u0637\u0639\u064a\u0645\u0627\u062a \u0645\u0639\u064a\u0646\u0629\u060c \u0645\u0639\u062a\u0631\u0641 \u0628\u0647\u0627 \u062f\u0648\u0644\u064a\u0627\u064b \u0648\u0641\u0642\u0627\u064b \u0644\u0644\u0648\u0627\u0626\u062d \u0627\u0644\u0635\u062d\u064a\u0629 \u0627\u0644\u062f\u0648\u0644\u064a\u0629 (IHR).\n\n\ud83d\udccb \u0645\u062d\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0634\u0647\u0627\u062f\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0634\u062e\u0635 (\u0627\u0644\u0627\u0633\u0645\u060c \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0645\u064a\u0644\u0627\u062f\u060c \u0627\u0644\u062c\u0646\u0633\u064a\u0629)\n\u2022 \u0627\u0644\u062a\u0637\u0639\u064a\u0645\u0627\u062a \u0627\u0644\u0645\u062a\u0644\u0642\u0627\u0629 \u0648\u062a\u0648\u0627\u0631\u064a\u062e\u0647\u0627\n\u2022 \u062e\u062a\u0645 \u0648\u062a\u0648\u0642\u064a\u0639 \u0627\u0644\u0637\u0628\u064a\u0628 \u0627\u0644\u0645\u0639\u062a\u0645\u062f\n\u2022 \u062e\u062a\u0645 \u0627\u0644\u0645\u0631\u0641\u0642 \u0627\u0644\u0635\u062d\u064a\n\n\ud83c\udfaf \u0645\u062a\u0649 \u062a\u062d\u062a\u0627\u062c \u0627\u0644\u0634\u0647\u0627\u062f\u0629\u061f\n\u2022 \u0639\u0646\u062f \u0627\u0644\u0633\u0641\u0631 \u0627\u0644\u062f\u0648\u0644\u064a\n\u2022 \u0628\u0639\u0636 \u0627\u0644\u062f\u0648\u0644 \u062a\u0637\u0644\u0628 \u062a\u0637\u0639\u064a\u0645 \u0627\u0644\u062d\u0645\u0649 \u0627\u0644\u0635\u0641\u0631\u0627\u0621\n\u2022 \u062d\u062c\u0627\u062c \u0628\u064a\u062a \u0627\u0644\u0644\u0647 (\u0645\u062a\u0637\u0644\u0628\u0627\u062a \u062e\u0627\u0635\u0629)\n\u2022 \u0628\u0639\u0636 \u0627\u0644\u062f\u0648\u0644 \u062a\u0637\u0644\u0628 \u062a\u0637\u0639\u064a\u0645 \u0643\u0648\u0641\u064a\u062f-19\n\n\u26a0\ufe0f \u0645\u0644\u0627\u062d\u0638\u0627\u062a:\n\u2022 \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0635\u0627\u0644\u062d\u0629 \u0645\u062f\u0649 \u0627\u0644\u062d\u064a\u0627\u0629 \u0644\u0628\u0639\u0636 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a\n\u2022 \u062a\u0637\u0639\u064a\u0645 \u0627\u0644\u062d\u0645\u0649 \u0627\u0644\u0635\u0641\u0631\u0627\u0621 \u0635\u0627\u0644\u062d 10 \u0623\u064a\u0627\u0645 \u0628\u0639\u062f \u0627\u0644\u0625\u0639\u0637\u0627\u0621\n\u2022 \u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0645\u0639 \u062c\u0648\u0627\u0632 \u0627\u0644\u0633\u0641\u0631\n\u2022 \u064a\u0645\u0643\u0646 \u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u0635\u062d\u064a\u0629 \u0627\u0644\u0645\u0639\u062a\u0645\u062f\u0629\n\n\ud83d\udca1 \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0627\u0644\u062f\u0648\u0644\u064a\u0629 = \u062a\u0623\u0634\u064a\u0631\u0629 \u0635\u062d\u064a\u0629 \u0644\u0644\u0633\u0641\u0631!","\ud83d\udc41\ufe0f \u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0628\u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629:\n\u2022 \u0627\u0643\u062a\u0634\u0627\u0641 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0645\u0628\u0643\u0631\u0627\u064b\n\u2022 \u0642\u064a\u0627\u0633 \u0623\u062b\u0631 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0639\u0644\u0649 \u0639\u0628\u0621 \u0627\u0644\u0645\u0631\u0636\n\u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0639\u0627\u0644\u064a\u0629 \u0627\u0644\u0645\u062e\u0627\u0637\u0631\n\u2022 \u062a\u0648\u062c\u064a\u0647 \u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\n\ud83d\udccb \u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0634\u0644\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 (AFP Surveillance):\n   \u2022 \u0623\u064a \u0634\u0644\u0644 \u0631\u062e\u0648 \u062d\u0627\u062f \u0639\u0646\u062f \u0623\u0637\u0641\u0627\u0644 <15 \u0633\u0646\u0629\n   \u2022 \u0625\u0628\u0644\u0627\u063a \u0641\u0648\u0631\u064a \u062e\u0644\u0627\u0644 24 \u0633\u0627\u0639\u0629\n   \u2022 \u0623\u062e\u0630 \u0639\u064a\u0646\u062a\u064a\u0646 \u0628\u0631\u0627\u0632\u064a\u062a\u064a\u0646\n   \u2022 \u0645\u0639\u062f\u0644 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0627\u0644\u0645\u0637\u0644\u0648\u0628: \u22652/100,000 \u0623\u0637\u0641\u0627\u0644\n\n2\ufe0f\u20e3 \u0627\u0644\u062d\u0635\u0628\u0629:\n   \u2022 \u0637\u0641\u062d + \u062d\u0631\u0627\u0631\u0629 \u226538\xb0 + \u0633\u0639\u0627\u0644/\u0631\u0634\u062d/\u0627\u0644\u062a\u0647\u0627\u0628 \u0645\u0644\u062a\u062d\u0645\u0629\n   \u2022 \u0625\u0628\u0644\u0627\u063a \u062e\u0644\u0627\u0644 48 \u0633\u0627\u0639\u0629\n   \u2022 \u0623\u062e\u0630 \u0639\u064a\u0646\u0629 \u062f\u0645 \u0644\u0644\u062a\u0623\u0643\u064a\u062f \u0627\u0644\u0645\u062e\u0628\u0631\u064a\n\n3\ufe0f\u20e3 \u0627\u0644\u0643\u0632\u0627\u0632 \u0627\u0644\u0648\u0644\u064a\u062f\u064a:\n   \u2022 \u0623\u064a \u0648\u0644\u064a\u062f \u064a\u0639\u0627\u0646\u064a \u062a\u0634\u0646\u062c\u0627\u062a \u0641\u064a \u0627\u0644\u0623\u064a\u0627\u0645 3-28 \u0627\u0644\u0623\u0648\u0644\u0649\n   \u2022 \u0639\u062f\u0645 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u0635 \u0648\u0627\u0644\u0628\u0644\u0639\n   \u2022 \u0625\u0628\u0644\u0627\u063a \u0648\u062a\u062d\u0642\u064a\u0642\n\n\ud83d\udca1 \u0645\u0631\u0627\u0642\u0628\u0629 \u0641\u0639\u0627\u0644\u0629 = \u0627\u0643\u062a\u0634\u0627\u0641 \u0645\u0628\u0643\u0631 = \u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0633\u0631\u064a\u0639\u0629!","\ud83c\udfaf \u0627\u0644\u062a\u062e\u0644\u0635 \u0645\u0646 \u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0628\u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \u0627\u0644\u0645\u0635\u0637\u0644\u062d\u0627\u062a:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 \u0627\u0644\u062a\u062d\u0643\u0645 (Control): \u062a\u0642\u0644\u064a\u0644 \u0639\u0628\u0621 \u0627\u0644\u0645\u0631\u0636 \u0644\u0645\u0633\u062a\u0648\u0649 \u0645\u0642\u0628\u0648\u0644\n\u2022 \u0627\u0644\u062a\u062e\u0644\u0635 (Elimination): \u0639\u062f\u0645 \u0648\u062c\u0648\u062f \u062d\u0627\u0644\u0627\u062a \u0641\u064a \u0645\u0646\u0637\u0642\u0629 \u062c\u063a\u0631\u0627\u0641\u064a\u0629\n\u2022 \u0627\u0644\u0627\u0633\u062a\u0626\u0635\u0627\u0644 (Eradication): \u0639\u062f\u0645 \u0648\u062c\u0648\u062f \u062d\u0627\u0644\u0627\u062a \u0639\u0627\u0644\u0645\u064a\u0627\u064b\n\n\ud83c\udfc6 \u0627\u0644\u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0629:\n\u2022 \u0627\u0644\u062c\u062f\u0631\u064a: \u0645\u0633\u062a\u0623\u0635\u0644 \u0639\u0627\u0644\u0645\u064a\u0627\u064b \u0645\u0646\u0630 1979 \ud83c\udf89\n\u2022 \u0634\u0644\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644: \u0639\u0644\u0649 \u0648\u0634\u0643 \u0627\u0644\u0627\u0633\u062a\u0626\u0635\u0627\u0644 (2 \u0628\u0644\u062f \u0645\u062a\u0628\u0642\u064a)\n\u2022 \u0627\u0644\u062d\u0635\u0628\u0629: \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062a\u062e\u0644\u0635 \u0625\u0642\u0644\u064a\u0645\u064a\u0627\u064b\n\u2022 \u0627\u0644\u0643\u0632\u0627\u0632 \u0627\u0644\u0648\u0644\u064a\u062f\u064a: \u0642\u0627\u0628\u0644 \u0644\u0644\u062a\u062e\u0644\u0635\n\n\ud83c\uddfe\ud83c\uddea \u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0627\u0644\u064a\u0645\u0646:\n\u2022 \u0634\u0644\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644: \u062e\u0627\u0644\u064d \u0645\u0646\u0630 2006 \ud83c\udf89\n\u2022 \u0627\u0644\u0643\u0632\u0627\u0632 \u0627\u0644\u0648\u0644\u064a\u062f\u064a: \u0627\u0646\u062e\u0641\u0627\u0636 \u0643\u0628\u064a\u0631\n\u2022 \u0627\u0644\u062d\u0635\u0628\u0629: \u062a\u062d\u062a \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 (\u062d\u0627\u0644\u0627\u062a \u0645\u062a\u0641\u0631\u0642\u0629)\n\n\ud83d\udccb \u0634\u0631\u0648\u0637 \u0627\u0644\u062a\u062e\u0644\u0635:\n\u2022 \u062a\u063a\u0637\u064a\u0629 \u062a\u062d\u0635\u064a\u0646\u064a\u0629 \u0639\u0627\u0644\u064a\u0629 (\u226595%)\n\u2022 \u0646\u0638\u0627\u0645 \u062a\u0631\u0635\u062f \u0642\u0648\u064a\n\u2022 \u0642\u062f\u0631\u0629 \u0645\u062e\u062a\u0628\u0631\u064a\u0629 \u0644\u0644\u062a\u0623\u0643\u064a\u062f\n\u2022 \u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0633\u0631\u064a\u0639\u0629 \u0644\u0644\u0641\u0644\u0642\u0627\u062a\n\n\ud83d\udca1 \u0627\u0644\u062a\u062e\u0644\u0635 \u0645\u0646 \u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0645\u0645\u0643\u0646 \u0628\u0627\u0644\u062a\u062d\u0635\u064a\u0646!",'\ud83d\udeab \u0645\u0639\u0627\u0644\u062c\u0629 \u062d\u0627\u0644\u0627\u062a \u0631\u0641\u0636 \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0623\u0633\u0628\u0627\u0628 \u0627\u0644\u0631\u0641\u0636:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u062f\u064a\u0646\u064a\u0629:\n   \u2022 \u0627\u0639\u062a\u0642\u0627\u062f \u0623\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u062d\u0631\u0627\u0645\n   \u2022 "\u0627\u0644\u062a\u0648\u0643\u0644 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u064a\u0643\u0641\u064a"\n   \u2022 \u0634\u0627\u0626\u0639\u0627\u062a \u0639\u0646 \u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0644\u0642\u0627\u062d\n\n2\ufe0f\u20e3 \u062b\u0642\u0627\u0641\u064a\u0629:\n   \u2022 \u0639\u0627\u062f\u0627\u062a \u0648\u062a\u0642\u0627\u0644\u064a\u062f \u0636\u062f \u0627\u0644\u0637\u0628 \u0627\u0644\u062d\u062f\u064a\u062b\n   \u2022 \u062a\u0623\u062b\u064a\u0631 \u0627\u0644\u0639\u0627\u0626\u0644\u0629 \u0648\u0627\u0644\u0623\u0642\u0627\u0631\u0628\n   \u2022 \u062a\u0641\u0636\u064a\u0644 \u0627\u0644\u0637\u0628 \u0627\u0644\u0634\u0639\u0628\u064a\n\n3\ufe0f\u20e3 \u062a\u062c\u0631\u064a\u0628\u064a\u0629:\n   \u2022 \u062a\u062c\u0631\u0628\u0629 \u0633\u0644\u0628\u064a\u0629 \u0633\u0627\u0628\u0642\u0629\n   \u2022 \u0633\u0645\u0627\u0639 \u0639\u0646 \u0622\u062b\u0627\u0631 \u062c\u0627\u0646\u0628\u064a\u0629\n   \u2022 \u0641\u0642\u062f\u0627\u0646 \u0627\u0644\u062b\u0642\u0629\n\n\ud83d\udccb \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0628\u0627\u062d\u062a\u0631\u0627\u0645:\n   \u2022 \u0644\u0627 \u062a\u064f\u062c\u0628\u0631 \u0623\u0648 \u062a\u064f\u0647\u062f\u062f\n   \u2022 \u0627\u0633\u0623\u0644 \u0639\u0646 \u0627\u0644\u0633\u0628\u0628 \u0628\u0627\u0644\u062a\u062d\u062f\u064a\u062f\n   \u2022 \u0623\u0638\u0647\u0631 \u0627\u0644\u062a\u0641\u0647\u0645\n\n2\ufe0f\u20e3 \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a:\n   \u2022 \u062d\u0642\u0627\u0626\u0642 \u0639\u0644\u0645\u064a\u0629 \u0628\u0633\u064a\u0637\u0629\n   \u2022 \u0641\u062a\u0627\u0648\u0649 \u0645\u0646 \u0639\u0644\u0645\u0627\u0621 \u0645\u0648\u062b\u0648\u0642\u064a\u0646\n   \u2022 \u0642\u0635\u0635 \u0646\u062c\u0627\u062d \u0645\u0646 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\n\n3\ufe0f\u20e3 \u0625\u0634\u0631\u0627\u0643 \u0648\u0633\u0637\u0627\u0621 \u0645\u0648\u062b\u0648\u0642\u064a\u0646:\n   \u2022 \u0634\u064a\u062e \u0627\u0644\u062d\u064a \u0623\u0648 \u0627\u0644\u0625\u0645\u0627\u0645\n   \u2022 \u0637\u0628\u064a\u0628 \u0623\u0648 \u0645\u0645\u0631\u0636\u0629 \u0645\u062d\u062a\u0631\u0645\u0629\n   \u2022 \u0642\u0631\u064a\u0628\u0629 \u0645\u064f\u0637\u0639\u0651\u0645\u0629 \u0648\u0645\u0642\u062a\u0646\u0639\u0629\n\n\ud83d\udca1 \u0627\u0644\u0625\u0642\u0646\u0627\u0639 \u0623\u0641\u0636\u0644 \u0645\u0646 \u0627\u0644\u0625\u062c\u0628\u0627\u0631!',"\ud83d\ude4b \u0627\u0644\u062a\u0637\u0648\u0639 \u0641\u064a \u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u062f\u0648\u0631 \u0627\u0644\u0645\u062a\u0637\u0648\u0639\u064a\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 \u062a\u0648\u0639\u064a\u0629 \u0627\u0644\u0623\u0633\u0631 \u0628\u0623\u0647\u0645\u064a\u0629 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\u2022 \u0627\u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0641\u064a \u062a\u062a\u0628\u0639 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u064a\u0646\n\u2022 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0641\u064a \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\u2022 \u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u062a\u0648\u0639\u0648\u064a\u0629\n\u2022 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\n\n\ud83c\udfaf \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0645\u062a\u0637\u0648\u0639\u064a\u0646:\n1\ufe0f\u20e3 \u0645\u062a\u0637\u0648\u0639\u0648 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0627\u0644\u0645\u062d\u0644\u064a:\n   \u2022 \u0645\u0646 \u0646\u0641\u0633 \u0627\u0644\u062d\u064a/\u0627\u0644\u0642\u0631\u064a\u0629\n   \u2022 \u064a\u0639\u0631\u0641\u0648\u0646 \u0627\u0644\u0639\u0627\u0626\u0644\u0627\u062a\n   \u2022 \u0645\u0648\u062b\u0648\u0642\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\n\n2\ufe0f\u20e3 \u0645\u062a\u0637\u0648\u0639\u0648 \u0627\u0644\u0635\u062d\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629:\n   \u2022 \u0645\u062f\u0631\u0628\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0635\u062d\u064a\u0629\n   \u2022 \u064a\u0631\u0628\u0637\u0648\u0646 \u0628\u064a\u0646 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0648\u0627\u0644\u0645\u0631\u0641\u0642\n   \u2022 \u064a\u0632\u0648\u0631\u0648\u0646 \u0627\u0644\u0645\u0646\u0627\u0632\u0644 \u062f\u0648\u0631\u064a\u0627\u064b\n\n3\ufe0f\u20e3 \u0645\u062a\u0637\u0648\u0639\u0648 \u0627\u0644\u0645\u0646\u0638\u0645\u0627\u062a:\n   \u2022 \u0645\u0646\u0638\u0645\u0627\u062a \u0645\u062c\u062a\u0645\u0639 \u0645\u062f\u0646\u064a\n   \u2022 \u062c\u0645\u0639\u064a\u0627\u062a \u0634\u0628\u0627\u0628\u064a\u0629\n   \u2022 \u0643\u0634\u0627\u0641\u0629 \u0648\u0645\u0631\u0634\u062f\u0627\u062a\n\n\ud83d\udca1 \u0627\u0644\u0645\u062a\u0637\u0648\u0639\u0648\u0646 = \u062c\u0633\u0631 \u0628\u064a\u0646 \u0627\u0644\u0645\u0631\u0641\u0642 \u0627\u0644\u0635\u062d\u064a \u0648\u0627\u0644\u0645\u062c\u062a\u0645\u0639!","\ud83c\udfe2 \u0627\u0644\u0634\u0631\u0627\u0643\u0629 \u0645\u0639 \u0627\u0644\u0642\u0637\u0627\u0639 \u0627\u0644\u062e\u0627\u0635 \u0641\u064a \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u0646\u062d\u062a\u0627\u062c \u0627\u0644\u0642\u0637\u0627\u0639 \u0627\u0644\u062e\u0627\u0635\u061f\n\u2022 \u062a\u0648\u0633\u064a\u0639 \u0646\u0637\u0627\u0642 \u0627\u0644\u0648\u0635\u0648\u0644\n\u2022 \u062a\u0648\u0641\u064a\u0631 \u0645\u0648\u0627\u0631\u062f \u0625\u0636\u0627\u0641\u064a\u0629\n\u2022 \u062f\u0639\u0645 \u0627\u0644\u062d\u0645\u0644\u0627\u062a\n\u2022 \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0634\u0631\u0627\u0626\u062d \u0627\u0644\u0645\u062a\u0648\u0633\u0637\u0629 \u0648\u0627\u0644\u0639\u0627\u0644\u064a\u0629\n\n\ud83c\udfaf \u0623\u0634\u0643\u0627\u0644 \u0627\u0644\u0634\u0631\u0627\u0643\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u0645\u0633\u062a\u0634\u0641\u064a\u0627\u062a \u0648\u0627\u0644\u0639\u064a\u0627\u062f\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629:\n   \u2022 \u062a\u0637\u0639\u064a\u0645 \u0627\u0644\u0645\u0648\u0627\u0644\u064a\u062f (BCG + HepB0 + OPV0)\n   \u2022 \u062a\u0637\u0639\u064a\u0645\u0627\u062a \u0631\u0648\u062a\u064a\u0646\u064a\u0629 \u062d\u0633\u0628 \u0627\u0644\u062c\u062f\u0648\u0644 \u0627\u0644\u0648\u0637\u0646\u064a\n   \u2022 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0639\u0646 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0644\u0648\u0632\u0627\u0631\u0629 \u0627\u0644\u0635\u062d\u0629\n\n2\ufe0f\u20e3 \u0642\u0637\u0627\u0639 \u0627\u0644\u0623\u0639\u0645\u0627\u0644:\n   \u2022 \u0631\u0639\u0627\u064a\u0629 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u062a\u0628\u0631\u0639 \u0628\u0645\u0639\u062f\u0627\u062a \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n   \u2022 \u062f\u0639\u0645 \u0627\u0644\u0646\u0642\u0644 \u0644\u0644\u0641\u0631\u0642 \u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629\n\n3\ufe0f\u20e3 \u0642\u0637\u0627\u0639 \u0627\u0644\u0627\u062a\u0635\u0627\u0644\u0627\u062a:\n   \u2022 \u0631\u0633\u0627\u0626\u0644 SMS \u0644\u0644\u062a\u0630\u0643\u064a\u0631 \u0628\u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u062e\u0637\u0648\u0637 \u0633\u0627\u062e\u0646\u0629 \u0644\u0644\u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a\n   \u2022 \u062a\u0637\u0628\u064a\u0642\u0627\u062a \u0647\u0627\u062a\u0641\u064a\u0629\n\n\u26a0\ufe0f \u0634\u0631\u0648\u0637 \u0627\u0644\u0634\u0631\u0627\u0643\u0629:\n\u2022 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0645\u0646 \u0645\u0635\u0627\u062f\u0631 \u0645\u0639\u062a\u0645\u062f\u0629\n\u2022 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f \u0645\u0636\u0645\u0648\u0646\u0629\n\u2022 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0645\u064f\u0628\u0644\u0651\u063a\u0629 \u0644\u0648\u0632\u0627\u0631\u0629 \u0627\u0644\u0635\u062d\u0629\n\u2022 \u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u0645\u0646\u0627\u0633\u0628\u0629 \u0623\u0648 \u0645\u062c\u0627\u0646\u064a\u0629\n\n\ud83d\udca1 \u0634\u0631\u0627\u0643\u0629 \u0645\u0646\u0638\u0645\u0629 = \u062a\u0623\u062b\u064a\u0631 \u0623\u0648\u0633\u0639!","\ud83d\udc68\u200d\ud83c\udfeb \u0628\u0646\u0627\u0621 \u0642\u062f\u0631\u0627\u062a \u0627\u0644\u0639\u0627\u0645\u0644\u064a\u0646 \u0627\u0644\u0635\u062d\u064a\u064a\u0646 \u0641\u064a \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u0628\u0646\u0627\u0621 \u0627\u0644\u0642\u062f\u0631\u0627\u062a\u061f\n\u2022 \u0636\u0645\u0627\u0646 \u062c\u0648\u062f\u0629 \u062e\u062f\u0645\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\u2022 \u062a\u062d\u062f\u064a\u062b \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a\n\u2022 \u0645\u0639\u0627\u0644\u062c\u0629 \u0646\u0642\u0627\u0637 \u0627\u0644\u0636\u0639\u0641\n\u2022 \u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u062b\u0642\u0629 \u0648\u0627\u0644\u062a\u062d\u0641\u064a\u0632\n\n\ud83c\udfaf \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062a\u062f\u0631\u064a\u0628:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u062a\u0623\u0647\u064a\u0644\u064a (Pre-service):\n   \u2022 \u0644\u0644\u0639\u0627\u0645\u0644\u064a\u0646 \u0627\u0644\u062c\u062f\u062f \u0642\u0628\u0644 \u0628\u062f\u0621 \u0627\u0644\u0639\u0645\u0644\n   \u2022 \u0645\u062f\u0629 5 \u0623\u064a\u0627\u0645 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644\n   \u2022 \u064a\u0634\u0645\u0644 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0646\u0638\u0631\u064a \u0648\u0627\u0644\u0639\u0645\u0644\u064a\n\n2\ufe0f\u20e3 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062e\u062f\u0645\u0629 (In-service):\n   \u2022 \u062a\u062d\u062f\u064a\u062b \u062f\u0648\u0631\u064a \u0644\u0644\u0639\u0627\u0645\u0644\u064a\u0646\n   \u2022 \u0639\u0646\u062f \u0625\u062f\u062e\u0627\u0644 \u0644\u0642\u0627\u062d\u0627\u062a \u0623\u0648 \u0633\u064a\u0627\u0633\u0627\u062a \u062c\u062f\u064a\u062f\u0629\n   \u2022 \u0648\u0631\u0634 \u0639\u0645\u0644 \u0648\u062f\u0648\u0631\u0627\u062a \u062a\u0646\u0634\u064a\u0637\u064a\u0629\n\n3\ufe0f\u20e3 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0639\u0645\u0644 (OJT):\n   \u2022 \u062e\u0644\u0627\u0644 \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0625\u0634\u0631\u0627\u0641\u064a\u0629\n   \u2022 \u062a\u0639\u0644\u064a\u0645 \u0645\u0646 \u0627\u0644\u0645\u0648\u0627\u0642\u0641 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u0629\n   \u2022 \u062a\u063a\u0630\u064a\u0629 \u0631\u0627\u062c\u0639\u0629 \u0641\u0648\u0631\u064a\u0629\n\n\ud83d\udccb \u0645\u062d\u0627\u0648\u0631 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629:\n\u2022 \u062c\u062f\u0648\u0644 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0645\u062d\u062f\u062b\n\u2022 \u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u062d\u0642\u0646 \u0627\u0644\u0622\u0645\u0646\n\u2022 \u0625\u062f\u0627\u0631\u0629 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n\u2022 \u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0648\u0627\u0644\u0625\u0628\u0644\u0627\u063a\n\u2022 \u0627\u0644\u062a\u062b\u0642\u064a\u0641 \u0627\u0644\u0635\u062d\u064a \u0648\u0627\u0644\u062a\u0648\u0627\u0635\u0644\n\n\ud83d\udca1 \u0639\u0627\u0645\u0644 \u0635\u062d\u064a \u0645\u062f\u0631\u0628 = \u062e\u062f\u0645\u0629 \u0623\u0641\u0636\u0644 = \u0623\u0637\u0641\u0627\u0644 \u0623\u0643\u062b\u0631 \u062d\u0645\u0627\u064a\u0629!","\ud83c\udfc6 \u062a\u062d\u0641\u064a\u0632 \u0627\u0644\u0639\u0627\u0645\u0644\u064a\u0646 \u0627\u0644\u0635\u062d\u064a\u064a\u0646 \u0648\u0645\u062a\u0627\u0628\u0639\u062a\u0647\u0645:\n\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u0627\u0644\u062a\u062d\u0641\u064a\u0632 \u0645\u0647\u0645\u061f\n\u2022 \u0631\u0641\u0639 \u0627\u0644\u0631\u0648\u062d \u0627\u0644\u0645\u0639\u0646\u0648\u064a\u0629\n\u2022 \u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u0625\u0646\u062a\u0627\u062c\u064a\u0629 \u0648\u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645\n\u2022 \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u062f\u0648\u0631\u0627\u0646 \u0627\u0644\u0648\u0638\u064a\u0641\u064a\n\u2022 \u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u0627\u0628\u062a\u0643\u0627\u0631 \u0648\u0627\u0644\u0645\u0628\u0627\u062f\u0631\u0629\n\n\ud83c\udfaf \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062a\u062d\u0641\u064a\u0632:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u062d\u0641\u064a\u0632 \u0627\u0644\u0645\u0639\u0646\u0648\u064a:\n   \u2022 \u0627\u0644\u062a\u0642\u062f\u064a\u0631 \u0627\u0644\u0639\u0644\u0646\u064a \u0648\u0627\u0644\u0634\u0643\u0631\n   \u2022 \u0634\u0647\u0627\u062f\u0627\u062a \u0627\u0644\u062a\u0642\u062f\u064a\u0631\n   \u2022 \u0641\u0631\u0635 \u0627\u0644\u062a\u0631\u0642\u064a \u0648\u0627\u0644\u062a\u0637\u0648\u064a\u0631\n   \u2022 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0641\u064a \u0627\u062a\u062e\u0627\u0630 \u0627\u0644\u0642\u0631\u0627\u0631\n\n2\ufe0f\u20e3 \u0627\u0644\u062a\u062d\u0641\u064a\u0632 \u0627\u0644\u0645\u0627\u062f\u064a:\n   \u2022 \u062d\u0648\u0627\u0641\u0632 \u0645\u0627\u0644\u064a\u0629 \u0644\u0644\u0645\u062a\u0645\u064a\u0632\u064a\u0646\n   \u2022 \u0628\u062f\u0644 \u0646\u0642\u0644 \u0644\u0644\u0641\u0631\u0642 \u0627\u0644\u0645\u062a\u0646\u0642\u0644\u0629\n   \u2022 \u0645\u0639\u062f\u0627\u062a \u0639\u0645\u0644 \u0645\u0646\u0627\u0633\u0628\u0629\n\n3\ufe0f\u20e3 \u0628\u064a\u0626\u0629 \u0627\u0644\u0639\u0645\u0644:\n   \u2022 \u0638\u0631\u0648\u0641 \u0639\u0645\u0644 \u0622\u0645\u0646\u0629\n   \u2022 \u0623\u062f\u0648\u0627\u062a \u0648\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a \u0643\u0627\u0641\u064a\u0629\n   \u2022 \u0633\u0627\u0639\u0627\u062a \u0639\u0645\u0644 \u0645\u0639\u0642\u0648\u0644\u0629\n\n\ud83d\udccb \u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629:\n\u2022 \u062a\u0642\u064a\u064a\u0645 \u0623\u062f\u0627\u0621 \u062f\u0648\u0631\u064a (\u0634\u0647\u0631\u064a/\u0631\u0628\u0639\u064a)\n\u2022 \u0627\u062c\u062a\u0645\u0627\u0639\u0627\u062a \u0645\u0631\u0627\u062c\u0639\u0629 \u0645\u0646\u062a\u0638\u0645\u0629\n\u2022 \u062a\u063a\u0630\u064a\u0629 \u0631\u0627\u062c\u0639\u0629 \u0628\u0646\u0627\u0621\u0629\n\u2022 \u062e\u0637\u0637 \u062a\u0637\u0648\u064a\u0631 \u0641\u0631\u062f\u064a\u0629\n\n\ud83d\udca1 \u0639\u0627\u0645\u0644 \u0645\u062d\u0641\u0651\u0632 = \u0623\u062f\u0627\u0621 \u0645\u062a\u0645\u064a\u0632 = \u062a\u063a\u0637\u064a\u0629 \u0623\u0639\u0644\u0649!","\ud83e\udd1d \u0627\u062c\u062a\u0645\u0627\u0639\u0627\u062a \u0645\u0631\u0627\u062c\u0639\u0629 \u0623\u062f\u0627\u0621 \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u0627\u062a:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u0627\u062a \u0627\u0644\u0634\u0647\u0631\u064a\u0629:\n   \u2022 \u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0634\u0647\u0631\u064a\u0629\n   \u2022 \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0648\u0627\u0644\u062a\u0633\u0631\u0628\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a \u0648\u0627\u0644\u062d\u0644\u0648\u0644\n   \u2022 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0648\u0646: \u0645\u062f\u064a\u0631 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 + \u0627\u0644\u0645\u0634\u0631\u0641\u0648\u0646\n\n2\ufe0f\u20e3 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u0627\u062a \u0627\u0644\u0631\u0628\u0639\u064a\u0629:\n   \u2022 \u0645\u0631\u0627\u062c\u0639\u0629 \u0634\u0627\u0645\u0644\u0629 \u0644\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0631\u0628\u0639\u064a\n   \u2022 \u062a\u0642\u064a\u064a\u0645 \u062a\u0642\u062f\u0645 \u062e\u0637\u0629 \u0627\u0644\u0639\u0645\u0644\n   \u2022 \u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u062e\u0637\u0637 \u062d\u0633\u0628 \u0627\u0644\u062d\u0627\u062c\u0629\n   \u2022 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0648\u0646: \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0639\u0646\u064a\u064a\u0646 + \u0627\u0644\u0634\u0631\u0643\u0627\u0621\n\n3\ufe0f\u20e3 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u0627\u062a \u0627\u0644\u0633\u0646\u0648\u064a\u0629:\n   \u2022 \u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0633\u0646\u0648\u064a \u0627\u0644\u0634\u0627\u0645\u0644\n   \u2022 \u0627\u0644\u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0648\u0627\u0644\u062a\u062d\u062f\u064a\u0627\u062a\n   \u2022 \u062e\u0637\u0629 \u0627\u0644\u0639\u0627\u0645 \u0627\u0644\u0642\u0627\u062f\u0645\n   \u2022 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0648\u0646: \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a + \u0627\u0644\u0634\u0631\u0643\u0627\u0621\n\n\ud83d\udccb \u0645\u062d\u0648\u0631 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639 \u0627\u0644\u062c\u064a\u062f:\n\u2022 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0623\u0648\u0644\u0627\u064b (Data-driven)\n\u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a \u0628\u0648\u0636\u0648\u062d\n\u2022 \u0627\u0642\u062a\u0631\u0627\u062d \u062d\u0644\u0648\u0644 \u0639\u0645\u0644\u064a\u0629\n\u2022 \u062a\u0639\u064a\u064a\u0646 \u0645\u0633\u0624\u0648\u0644\u064a\u0627\u062a \u0648\u062c\u062f\u0627\u0648\u0644 \u0632\u0645\u0646\u064a\u0629\n\u2022 \u062a\u0648\u062b\u064a\u0642 \u0627\u0644\u0642\u0631\u0627\u0631\u0627\u062a \u0648\u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629\n\n\ud83d\udca1 \u0627\u062c\u062a\u0645\u0627\u0639 \u0628\u062f\u0648\u0646 \u0645\u062a\u0627\u0628\u0639\u0629 = \u0645\u0636\u064a\u0639\u0629 \u0644\u0644\u0648\u0642\u062a!","\ud83d\udcca \u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0631\u0628\u0639\u064a \u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 \u0627\u0644\u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u0631\u0628\u0639\u064a\u061f\n\u0645\u0631\u0627\u062c\u0639\u0629 \u0634\u0627\u0645\u0644\u0629 \u0644\u0623\u062f\u0627\u0621 \u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0643\u0644 \u062b\u0644\u0627\u062b\u0629 \u0623\u0634\u0647\u0631\u060c \u0644\u0642\u064a\u0627\u0633 \u0627\u0644\u062a\u0642\u062f\u0645 \u0646\u062d\u0648 \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0648\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0641\u062c\u0648\u0627\u062a.\n\n\ud83c\udfaf \u0645\u062d\u0627\u0648\u0631 \u0627\u0644\u062a\u0642\u064a\u064a\u0645:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u062a\u0637\u0639\u064a\u0645\u064a\u0629:\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0644\u0643\u0644 \u0644\u0642\u0627\u062d \u0645\u0642\u0627\u0631\u0646\u0629 \u0628\u0627\u0644\u0647\u062f\u0641\n   \u2022 \u0627\u062a\u062c\u0627\u0647 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 (\u0645\u062a\u0635\u0627\u0639\u062f\u0629 \u0623\u0645 \u0645\u062a\u0646\u0627\u0642\u0635\u0629)\n   \u2022 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0627\u062a \u0627\u0644\u0623\u0639\u0644\u0649 \u0648\u0627\u0644\u0623\u062f\u0646\u0649 \u0623\u062f\u0627\u0621\u064b\n\n2\ufe0f\u20e3 \u0627\u0644\u062a\u0633\u0631\u0628:\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u0633\u0631\u0628 Penta1\u2192Penta3\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u0633\u0631\u0628 MR1\u2192MR2\n   \u2022 \u0645\u0642\u0627\u0631\u0646\u0629 \u0645\u0639 \u0627\u0644\u0631\u0628\u0639 \u0627\u0644\u0633\u0627\u0628\u0642\n\n3\ufe0f\u20e3 \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a:\n   \u2022 \u062d\u0627\u0644\u0627\u062a \u0646\u0641\u0627\u062f \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u0647\u062f\u0631\n   \u2022 \u0633\u0644\u0627\u0645\u0629 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n\n4\ufe0f\u20e3 \u0627\u0644\u0625\u0634\u0631\u0627\u0641 \u0627\u0644\u062f\u0627\u0639\u0645:\n   \u2022 \u0639\u062f\u062f \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0646\u0641\u0630\u0629 / \u0627\u0644\u0645\u062e\u0637\u0637\u0629\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u062e\u0637\u0637 \u0627\u0644\u062a\u062d\u0633\u064a\u0646\n\n5\ufe0f\u20e3 \u0627\u0644\u0625\u0628\u0644\u0627\u063a:\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0643\u062a\u0645\u0627\u0644 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631\n   \u2022 \u0646\u0633\u0628\u0629 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u0645\u0648\u0627\u0639\u064a\u062f\n\n\ud83d\udca1 \u0627\u0644\u062a\u0642\u064a\u064a\u0645 \u0644\u064a\u0633 \u0639\u0642\u0627\u0628\u0627\u064b \u0628\u0644 \u0641\u0631\u0635\u0629 \u0644\u0644\u062a\u062d\u0633\u064a\u0646!","\ud83c\udfda\ufe0f \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0644\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0646\u0627\u0632\u062d\u064a\u0646 \u0648\u0627\u0644\u0645\u062a\u0623\u062b\u0631\u064a\u0646 \u0628\u0627\u0644\u0646\u0632\u0627\u0639\u0627\u062a:\n\n\ud83d\udccc \u0627\u0644\u062a\u062d\u062f\u064a\u0627\u062a:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 \u0641\u0642\u062f\u0627\u0646 \u0633\u062c\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0646\u0632\u0648\u062d\n\u2022 \u0627\u0646\u0642\u0637\u0627\u0639 \u062e\u062f\u0645\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0631\u0648\u062a\u064a\u0646\u064a\u0629\n\u2022 \u0627\u0632\u062f\u062d\u0627\u0645 \u0627\u0644\u0645\u062e\u064a\u0645\u0627\u062a \u0648\u0627\u0646\u062a\u0634\u0627\u0631 \u0627\u0644\u0623\u0645\u0631\u0627\u0636\n\u2022 \u0636\u0639\u0641 \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0648\u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u0642\u0627\u0628\u0644\u064a\u0629 \u0644\u0644\u0639\u062f\u0648\u0649\n\u2022 \u0627\u0646\u0642\u0637\u0627\u0639 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f\n\n\ud83c\udfaf \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0644\u0644\u0646\u0627\u0632\u062d\u064a\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0646\u0642\u0627\u0637 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0641\u064a \u0627\u0644\u0645\u062e\u064a\u0645\u0627\u062a:\n   \u2022 \u0646\u0642\u0627\u0637 \u062b\u0627\u0628\u062a\u0629 \u0639\u0646\u062f \u0645\u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u062e\u064a\u0645\u0627\u062a\n   \u2022 \u0641\u062d\u0635 \u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0639\u0646\u062f \u0627\u0644\u062a\u0633\u062c\u064a\u0644\n   \u2022 \u062a\u0637\u0639\u064a\u0645 \u0627\u0644\u0641\u0626\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0641\u0648\u0631\u0627\u064b\n\n2\ufe0f\u20e3 \u062a\u0639\u0648\u064a\u0636 \u0627\u0644\u0628\u0637\u0627\u0642\u0627\u062a \u0627\u0644\u0645\u0641\u0642\u0648\u062f\u0629:\n   \u2022 \u0625\u0635\u062f\u0627\u0631 \u0628\u0637\u0627\u0642\u0629 \u062c\u062f\u064a\u062f\u0629\n   \u2022 \u0627\u0644\u0628\u062d\u062b \u0641\u064a \u0627\u0644\u0633\u062c\u0644\u0627\u062a \u0627\u0644\u0635\u062d\u064a\u0629 \u0627\u0644\u0645\u062a\u0627\u062d\u0629\n   \u2022 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u0639\u0644\u0649 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0623\u0645 \u0625\u0630\u0627 \u0644\u0645 \u062a\u062a\u0648\u0641\u0631 \u0633\u062c\u0644\u0627\u062a\n\n3\ufe0f\u20e3 \u062d\u0645\u0644\u0627\u062a \u0645\u0643\u062b\u0641\u0629:\n   \u2022 \u062d\u0645\u0644\u0627\u062a \u062d\u0635\u0628\u0629 \u0634\u0627\u0645\u0644\u0629 \u0641\u064a \u0627\u0644\u0645\u062e\u064a\u0645\u0627\u062a\n   \u2022 OPV \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0637\u0641\u0627\u0644\n   \u2022 Td \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0648\u0627\u0645\u0644\n\n\ud83d\udca1 \u0627\u0644\u0646\u0627\u0632\u062d\u0648\u0646 \u0623\u0643\u062b\u0631 \u062d\u0627\u062c\u0629 \u0644\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u0644\u0627 \u0646\u062a\u0631\u0643\u0647\u0645 \u0628\u062f\u0648\u0646 \u062d\u0645\u0627\u064a\u0629!","\ud83c\udfaf \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0634\u0627\u0645\u0644\u0629 \u0644\u0644\u062a\u062d\u0635\u064a\u0646 (Universal Coverage):\n\n\ud83d\udccc \u0645\u0627 \u0647\u064a \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0634\u0627\u0645\u0644\u0629\u061f\n\u0648\u0635\u0648\u0644 \u062e\u062f\u0645\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0644\u0643\u0644 \u0637\u0641\u0644 \u0641\u064a \u0643\u0644 \u0645\u0643\u0627\u0646\u060c \u0628\u063a\u0636 \u0627\u0644\u0646\u0638\u0631 \u0639\u0646 \u0627\u0644\u0645\u0648\u0642\u0639 \u0627\u0644\u062c\u063a\u0631\u0627\u0641\u064a \u0623\u0648 \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u062f\u064a \u0623\u0648 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a.\n\n\ud83c\udfaf \u0631\u0643\u0627\u0626\u0632 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0634\u0627\u0645\u0644\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u0648\u0641\u0631 (Availability):\n   \u2022 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0648\u0627\u0644\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a \u0645\u062a\u0648\u0641\u0631\u0629 \u062f\u0627\u0626\u0645\u0627\u064b\n   \u2022 \u0645\u0631\u0627\u0641\u0642 \u0635\u062d\u064a\u0629 \u0643\u0627\u0641\u064a\u0629 \u0648\u0645\u062c\u0647\u0632\u0629\n   \u2022 \u0643\u0648\u0627\u062f\u0631 \u0645\u062f\u0631\u0628\u0629 \u0648\u0630\u0627\u062a \u0643\u0641\u0627\u0621\u0629\n\n2\ufe0f\u20e3 \u0627\u0644\u0648\u0635\u0648\u0644 (Accessibility):\n   \u2022 \u062e\u062f\u0645\u0627\u062a \u0642\u0631\u064a\u0628\u0629 \u0645\u0646 \u0627\u0644\u0633\u0643\u0627\u0646\n   \u2022 \u0623\u0648\u0642\u0627\u062a \u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u0644\u062c\u0644\u0633\u0627\u062a\n   \u2022 \u0641\u0631\u0642 \u0645\u062a\u0646\u0642\u0644\u0629 \u0644\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0646\u0627\u0626\u064a\u0629\n\n3\ufe0f\u20e3 \u0627\u0644\u0642\u0628\u0648\u0644 (Acceptability):\n   \u2022 \u062b\u0642\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0628\u0627\u0644\u062e\u062f\u0645\u0627\u062a\n   \u2022 \u0627\u062d\u062a\u0631\u0627\u0645 \u0627\u0644\u0639\u0627\u062f\u0627\u062a \u0648\u0627\u0644\u062a\u0642\u0627\u0644\u064a\u062f\n   \u2022 \u062a\u0648\u0627\u0635\u0644 \u0641\u0639\u0651\u0627\u0644 \u0645\u0639 \u0627\u0644\u0623\u0633\u0631\n\n4\ufe0f\u20e3 \u0627\u0644\u062c\u0648\u062f\u0629 (Quality):\n   \u2022 \u0645\u0645\u0627\u0631\u0633\u0627\u062a \u0622\u0645\u0646\u0629 \u0648\u0635\u062d\u064a\u062d\u0629\n   \u2022 \u0644\u0642\u0627\u062d\u0627\u062a \u0641\u0639\u0627\u0644\u0629 \u0648\u0622\u0645\u0646\u0629\n   \u2022 \u062a\u0633\u062c\u064a\u0644 \u062f\u0642\u064a\u0642\n\n\ud83d\udcca \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0629 (IA2030):\n\u2022 \u062a\u063a\u0637\u064a\u0629 \u226590% \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a\n\u2022 \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0628\u062c\u0631\u0639\u0629 \u0635\u0641\u0631 \u0628\u0646\u0633\u0628\u0629 50%\n\u2022 \u0625\u062f\u062e\u0627\u0644 500 \u0644\u0642\u0627\u062d \u062c\u062f\u064a\u062f \u0623\u0648 \u0645\u0639\u062f\u0644\n\n\ud83d\udca1 \u0644\u0627 \u0637\u0641\u0644 \u064a\u064f\u062d\u0631\u0645 \u0645\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u0647\u0630\u0627 \u062d\u0642 \u0623\u0633\u0627\u0633\u064a!","\ud83d\udc69\u200d\ud83d\udc67 \u0635\u062d\u0629 \u0627\u0644\u0623\u0645 \u0648\u0627\u0644\u0637\u0641\u0644 \u0648\u0639\u0644\u0627\u0642\u062a\u0647\u0627 \u0628\u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0627\u0644\u0631\u0628\u0637 \u0628\u064a\u0646 \u0635\u062d\u0629 \u0627\u0644\u0623\u0645 \u0648\u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062d\u0645\u0644:\n   \u2022 \u062a\u0637\u0639\u064a\u0645 Td \u064a\u062d\u0645\u064a \u0627\u0644\u0623\u0645 \u0648\u0627\u0644\u0645\u0648\u0644\u0648\u062f \u0645\u0646 \u0627\u0644\u0643\u0632\u0627\u0632\n   \u2022 \u0643\u0644 \u0632\u064a\u0627\u0631\u0629 \u0644\u0644\u0631\u0639\u0627\u064a\u0629 \u0642\u0628\u0644 \u0627\u0644\u0648\u0644\u0627\u062f\u0629 \u0641\u0631\u0635\u0629 \u0644\u0644\u062a\u0637\u0639\u064a\u0645\n   \u2022 \u062a\u0648\u0639\u064a\u0629 \u0627\u0644\u0623\u0645 \u0628\u0623\u0647\u0645\u064a\u0629 \u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0637\u0641\u0644 \u0628\u0639\u062f \u0627\u0644\u0648\u0644\u0627\u062f\u0629\n\n2\ufe0f\u20e3 \u0639\u0646\u062f \u0627\u0644\u0648\u0644\u0627\u062f\u0629:\n   \u2022 BCG + HepB0 + OPV0 \u0641\u064a \u0623\u0648\u0644 24 \u0633\u0627\u0639\u0629\n   \u2022 \u0627\u0644\u0648\u0644\u0627\u062f\u0629 \u0641\u064a \u0645\u0631\u0641\u0642 \u0635\u062d\u064a = \u0641\u0631\u0635\u0629 \u0644\u0644\u062a\u0637\u0639\u064a\u0645\n   \u2022 \u0631\u0628\u0637 \u0627\u0644\u062a\u0637\u0639\u064a\u0646 \u0628\u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0645\u062f\u0646\u064a\n\n3\ufe0f\u20e3 \u0628\u0639\u062f \u0627\u0644\u0648\u0644\u0627\u062f\u0629:\n   \u2022 \u062c\u062f\u0648\u0644 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629 \u0628\u0639\u062f \u0627\u0644\u0648\u0644\u0627\u062f\u0629 \u064a\u062a\u0636\u0645\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0627\u0644\u0631\u0636\u0627\u0639\u0629 \u0627\u0644\u0637\u0628\u064a\u0639\u064a\u0629 + \u0627\u0644\u062a\u062d\u0635\u064a\u0646 = \u062d\u0645\u0627\u064a\u0629 \u0645\u0632\u062f\u0648\u062c\u0629\n   \u2022 \u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0623\u0633\u0631\u0629 + \u0627\u0644\u062a\u062d\u0635\u064a\u0646 = \u062a\u0643\u0627\u0645\u0644 \u0627\u0644\u062e\u062f\u0645\u0627\u062a\n\n4\ufe0f\u20e3 \u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0644\u062a\u0637\u0648\u0631:\n   \u2022 \u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u0646\u0645\u0648 \u0645\u0639 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0632\u064a\u0627\u0631\u0629\n   \u2022 \u0641\u064a\u062a\u0627\u0645\u064a\u0646 \u0623 \u0645\u0639 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0641\u062d\u0635 \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0645\u0639 \u0643\u0644 \u0632\u064a\u0627\u0631\u0629 \u062a\u062d\u0635\u064a\u0646\n\n\ud83d\udca1 \u0623\u0645 \u0635\u062d\u064a\u0629 = \u0637\u0641\u0644 \u0645\u062d\u0635\u0646 = \u0645\u0633\u062a\u0642\u0628\u0644 \u0623\u0641\u0636\u0644!","\ud83d\udde3\ufe0f \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0641\u0639\u0627\u0644 \u0645\u0639 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0641\u064a \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0641\u0639\u0627\u0644:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u0628\u0633\u0627\u0637\u0629:\n   \u2022 \u0627\u0633\u062a\u062e\u062f\u0645 \u0644\u063a\u0629 \u0628\u0633\u064a\u0637\u0629 \u064a\u0641\u0647\u0645\u0647\u0627 \u0627\u0644\u062c\u0645\u064a\u0639\n   \u2022 \u062a\u062c\u0646\u0628 \u0627\u0644\u0645\u0635\u0637\u0644\u062d\u0627\u062a \u0627\u0644\u0637\u0628\u064a\u0629 \u0627\u0644\u0645\u0639\u0642\u062f\u0629\n   \u2022 \u0623\u0645\u062b\u0644\u0629 \u0645\u0646 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u064a\u0648\u0645\u064a\u0629\n\n2\ufe0f\u20e3 \u0627\u0644\u0627\u062d\u062a\u0631\u0627\u0645:\n   \u2022 \u0627\u062d\u062a\u0631\u0627\u0645 \u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0648\u0639\u0627\u062f\u0627\u062a\u0647\n   \u2022 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0642\u0628\u0644 \u0627\u0644\u062a\u062d\u062f\u062b\n   \u2022 \u0639\u062f\u0645 \u0627\u0644\u062a\u0642\u0644\u064a\u0644 \u0645\u0646 \u0627\u0644\u0645\u062e\u0627\u0648\u0641\n\n3\ufe0f\u20e3 \u0627\u0644\u0635\u062f\u0642:\n   \u2022 \u0644\u0627 \u062a\u0628\u0627\u0644\u063a \u0641\u064a \u0627\u0644\u0641\u0648\u0627\u0626\u062f\n   \u2022 \u0644\u0627 \u062a\u062e\u0641\u0651 \u0627\u0644\u0622\u062b\u0627\u0631 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0629\n   \u2022 \u0643\u0646 \u0635\u0627\u062f\u0642\u0627\u064b \u062d\u0648\u0644 \u0627\u0644\u0645\u062e\u0627\u0637\u0631 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u0629\n\n4\ufe0f\u20e3 \u0627\u0644\u062a\u0641\u0627\u0639\u0644:\n   \u2022 \u0634\u062c\u0639 \u0627\u0644\u0623\u0633\u0626\u0644\u0629\n   \u2022 \u0627\u0633\u062a\u0645\u0639 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0627\u062a\n   \u2022 \u0627\u0633\u062a\u062c\u0628 \u0644\u0644\u0645\u062e\u0627\u0648\u0641\n\n\ud83c\udfaf \u0642\u0646\u0648\u0627\u062a \u0627\u0644\u062a\u0648\u0627\u0635\u0644:\n\u2022 \u0627\u0644\u0645\u0633\u0627\u062c\u062f \u0648\u0627\u0644\u062c\u0648\u0627\u0645\u0639\n\u2022 \u0627\u0644\u0645\u062f\u0627\u0631\u0633 \u0648\u0627\u0644\u0631\u0648\u0636\u0627\u062a\n\u2022 \u0627\u0644\u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u0635\u062d\u064a\u0629\n\u2022 \u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\n\u2022 \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0646\u0632\u0644\u064a\u0629\n\n\ud83d\udca1 \u062a\u0648\u0627\u0635\u0644 \u0641\u0639\u0651\u0627\u0644 = \u0645\u062c\u062a\u0645\u0639 \u0648\u0627\u0639\u064d = \u062a\u062d\u0635\u064a\u0646 \u0623\u0641\u0636\u0644!","\u2b50 \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629 \u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\n\ud83d\udccc \u062f\u0648\u0631 \u0642\u0627\u062f\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u0645\u0634\u0627\u064a\u062e \u0648\u0627\u0644\u0623\u0626\u0645\u0629:\n   \u2022 \u062a\u0648\u0639\u064a\u0629 \u062f\u064a\u0646\u064a\u0629 \u0628\u0623\u0647\u0645\u064a\u0629 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0641\u0636 \u0627\u0644\u0634\u0627\u0626\u0639\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0646\u0628\u0631\n   \u2022 \u062f\u0639\u0645 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0641\u062a\u0627\u0648\u0649 \u062a\u062f\u0639\u0645 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\n2\ufe0f\u20e3 \u0631\u0624\u0633\u0627\u0621 \u0627\u0644\u0623\u062d\u064a\u0627\u0621 \u0648\u0627\u0644\u0642\u0631\u0649:\n   \u2022 \u062d\u0635\u0631 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646\n   \u2022 \u062a\u062a\u0628\u0639 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u064a\u0646\n   \u2022 \u062a\u0646\u0638\u064a\u0645 \u062c\u0644\u0633\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0641\u064a \u0627\u0644\u0645\u0646\u0637\u0642\u0629\n\n3\ufe0f\u20e3 \u0627\u0644\u0646\u0633\u0627\u0621 \u0627\u0644\u0642\u064a\u0627\u062f\u064a\u0627\u062a:\n   \u2022 \u0627\u0644\u062a\u0623\u062b\u064a\u0631 \u0639\u0644\u0649 \u0627\u0644\u0623\u0645\u0647\u0627\u062a\n   \u2022 \u0646\u0634\u0631 \u0627\u0644\u0648\u0639\u064a \u0628\u064a\u0646 \u0627\u0644\u0646\u0633\u0627\u0621\n   \u2022 \u0645\u0639\u0627\u0644\u062c\u0629 \u062d\u0648\u0627\u062c\u0632 \u0627\u0644\u062b\u0642\u0627\u0641\u0629\n\n4\ufe0f\u20e3 \u0627\u0644\u0645\u0639\u0644\u0645\u0648\u0646:\n   \u2022 \u062a\u062b\u0642\u064a\u0641 \u0627\u0644\u0637\u0644\u0627\u0628\n   \u2022 \u0645\u062a\u0627\u0628\u0639\u0629 \u0628\u0637\u0627\u0642\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0644\u0644\u062d\u0645\u0644\u0627\u062a \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629\n\n\ud83d\udccb \u0643\u064a\u0641 \u062a\u064f\u0641\u0639\u0651\u0644 \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064a\u0629:\n\u2022 \u0639\u0642\u062f \u0627\u062c\u062a\u0645\u0627\u0639\u0627\u062a \u062f\u0648\u0631\u064a\u0629 \u0645\u0639 \u0627\u0644\u0642\u0627\u062f\u0629\n\u2022 \u0625\u0634\u0631\u0627\u0643\u0647\u0645 \u0641\u064a \u0627\u0644\u062a\u062e\u0637\u064a\u0637\n\u2022 \u062a\u0642\u062f\u064a\u0645 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0645\u062d\u062f\u062b\u0629 \u0644\u0647\u0645\n\u2022 \u062a\u0642\u062f\u064a\u0631 \u062c\u0647\u0648\u062f\u0647\u0645 \u0648\u0625\u0646\u062c\u0627\u0632\u0627\u062a\u0647\u0645\n\n\ud83d\udca1 \u0642\u0627\u062f\u0629 \u0645\u062c\u062a\u0645\u0639 \u0645\u064f\u0644\u062a\u0632\u0645\u0648\u0646 = \u0645\u062c\u062a\u0645\u0639 \u0645\u062d\u0635\u0646!","\ud83d\udcde \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0639\u0646 \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0627\u0644\u0636\u0627\u0626\u0631\u0629 \u0628\u0639\u062f \u0627\u0644\u062a\u0637\u0639\u064a\u0645:\n\n\ud83d\udccc \u0645\u062a\u0649 \u062a\u064f\u0628\u0644\u0651\u063a\u061f\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\ud83d\udea8 \u0625\u0628\u0644\u0627\u063a \u0641\u0648\u0631\u064a (\u062e\u0644\u0627\u0644 24 \u0633\u0627\u0639\u0629):\n   \u2022 \u0627\u0644\u0648\u0641\u0627\u0629 \u0628\u0639\u062f \u0627\u0644\u062a\u0637\u0639\u064a\u0645\n   \u2022 \u0631\u062f \u0641\u0639\u0644 \u062a\u062d\u0633\u0633\u064a \u0634\u062f\u064a\u062f (Anaphylaxis)\n   \u2022 \u062a\u0634\u0646\u062c\u0627\u062a\n   \u2022 \u0634\u0644\u0644 \u0631\u062e\u0648 \u062d\u0627\u062f\n   \u2022 \u062a\u062c\u0645\u0639 \u063a\u064a\u0631 \u0639\u0627\u062f\u064a \u0644\u0623\u062d\u062f\u0627\u062b \u0636\u0627\u0626\u0631\u0629\n\n\ud83d\udccb \u0625\u0628\u0644\u0627\u063a \u0631\u0648\u062a\u064a\u0646\u064a (\u0634\u0647\u0631\u064a):\n   \u2022 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0627\u0644\u0636\u0627\u0626\u0631\u0629 \u0627\u0644\u0628\u0633\u064a\u0637\u0629\n   \u2022 \u062d\u0631\u0627\u0631\u0629\u060c \u0627\u062d\u0645\u0631\u0627\u0631\u060c \u062a\u0648\u0631\u0645\n   \u2022 \u0628\u0643\u0627\u0621 \u0645\u0633\u062a\u0645\u0631\n\n\ud83d\udcdd \u0645\u062d\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u062a\u0642\u0631\u064a\u0631:\n   \u2022 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0631\u064a\u0636 (\u0627\u0644\u0639\u0645\u0631\u060c \u0627\u0644\u062c\u0646\u0633)\n   \u2022 \u0627\u0644\u0644\u0642\u0627\u062d \u0627\u0644\u0645\u064f\u0639\u0637\u0649 (\u0627\u0644\u0627\u0633\u0645\u060c \u0627\u0644\u062f\u0641\u0639\u0629\u060c VVM)\n   \u2022 \u0648\u0635\u0641 \u0627\u0644\u062d\u062f\u062b \u0648\u0623\u0639\u0631\u0627\u0636\u0647\n   \u2022 \u0648\u0642\u062a \u0638\u0647\u0648\u0631 \u0627\u0644\u0623\u0639\u0631\u0627\u0636\n   \u2022 \u0627\u0644\u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u0645\u062a\u062e\u0630\n\n\ud83d\udcca \u0645\u0633\u0627\u0631 \u0627\u0644\u0625\u0628\u0644\u0627\u063a:\n\u0627\u0644\u0645\u0631\u0641\u0642 \u0627\u0644\u0635\u062d\u064a \u2190 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0629 \u2190 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629 \u2190 \u0627\u0644\u0648\u0637\u0646\u064a \u2190 WHO\n\n\ud83d\udca1 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0644\u064a\u0633 \u0625\u062f\u0627\u0646\u0629 \u0628\u0644 \u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0645\u0647\u0646\u064a\u0629!","\ud83d\udcdc \u0627\u0644\u0631\u0628\u0637 \u0628\u064a\u0646 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u0627\u0644\u0633\u062c\u0644 \u0627\u0644\u0645\u062f\u0646\u064a:\n\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u0627\u0644\u0631\u0628\u0637 \u0645\u0647\u0645\u061f\n\u2022 \u062d\u0635\u0631 \u0627\u0644\u0645\u0648\u0627\u0644\u064a\u062f \u0627\u0644\u062c\u062f\u062f \u0628\u062f\u0642\u0629\n\u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646\n\u2022 \u062a\u062a\u0628\u0639 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u063a\u064a\u0631 \u0627\u0644\u0645\u0637\u0639\u0645\u064a\u0646\n\u2022 \u062d\u0633\u0627\u0628 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0628\u062f\u0642\u0629\n\n\ud83c\udfaf \u0622\u0644\u064a\u0627\u062a \u0627\u0644\u0631\u0628\u0637:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0639\u0646\u062f \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0645\u0648\u0644\u0648\u062f:\n   \u2022 \u0627\u0644\u0633\u062c\u0644 \u0627\u0644\u0645\u062f\u0646\u064a \u064a\u064f\u0628\u0644\u063a \u0627\u0644\u0645\u0631\u0641\u0642 \u0627\u0644\u0635\u062d\u064a\n   \u2022 \u0627\u0644\u0645\u0631\u0641\u0642 \u064a\u0636\u064a\u0641 \u0627\u0644\u0637\u0641\u0644 \u0644\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646\n   \u2022 \u064a\u062d\u062f\u062f \u0645\u0648\u0639\u062f \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0623\u0648\u0644\n\n2\ufe0f\u20e3 \u0639\u0646\u062f \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n   \u2022 \u0627\u0644\u0645\u0631\u0641\u0642 \u064a\u0637\u0644\u0628 \u0634\u0647\u0627\u062f\u0629 \u0627\u0644\u0645\u064a\u0644\u0627\u062f\n   \u2022 \u064a\u064f\u0633\u062c\u0644 \u0631\u0642\u0645 \u0634\u0647\u0627\u062f\u0629 \u0627\u0644\u0645\u064a\u0644\u0627\u062f \u0641\u064a \u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u064a\u064f\u0628\u0644\u063a \u0627\u0644\u0633\u062c\u0644 \u0627\u0644\u0645\u062f\u0646\u064a \u0628\u0625\u062a\u0645\u0627\u0645 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\n3\ufe0f\u20e3 \u062a\u0628\u0627\u062f\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a:\n   \u2022 \u062a\u0642\u0627\u0631\u064a\u0631 \u062f\u0648\u0631\u064a\u0629 \u0645\u0646 \u0627\u0644\u0633\u062c\u0644 \u0627\u0644\u0645\u062f\u0646\u064a\n   \u2022 \u0645\u0642\u0627\u0631\u0646\u0629 \u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0645\u0648\u0627\u0644\u064a\u062f \u0645\u0639 \u0627\u0644\u0645\u0637\u0639\u0645\u064a\u0646\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0641\u062c\u0648\u0627\u062a\n\n\ud83d\udca1 \u062a\u0643\u0627\u0645\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a = \u062a\u063a\u0637\u064a\u0629 \u0623\u0634\u0645\u0644!","\ud83d\udcca \u0645\u0624\u0634\u0631 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a (Vaccine Utilization Rate):\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 \u0645\u0624\u0634\u0631 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645\u061f\n\u0647\u0648 \u0646\u0633\u0628\u0629 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u0629 \u0641\u0639\u0644\u064a\u0627\u064b \u0641\u064a \u0627\u0644\u062a\u0637\u0639\u064a\u0645 \u0645\u0642\u0627\u0631\u0646\u0629 \u0628\u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0645\u0648\u0632\u0639\u0629.\n\n\ud83d\udd22 \u0645\u0639\u0627\u062f\u0644\u0629 \u0627\u0644\u062d\u0633\u0627\u0628:\n\u0646\u0633\u0628\u0629 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 = (\u0627\u0644\u062c\u0631\u0639\u0627\u062a \u0627\u0644\u0645\u0639\u0637\u0627\u0629 \xf7 \u0627\u0644\u062c\u0631\u0639\u0627\u062a \u0627\u0644\u0645\u0648\u0632\u0639\u0629) \xd7 100\n\n\ud83d\udcca \u0627\u0644\u0645\u0639\u062f\u0644\u0627\u062a \u0627\u0644\u0645\u0631\u062c\u0639\u064a\u0629:\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 \u0627\u0644\u0644\u0642\u0627\u062d                     \u2502 \u0646\u0633\u0628\u0629 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645\u2502\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\n\u2502 Penta (ADS)                \u2502 \u226585%         \u2502\n\u2502 PCV (ADS)                  \u2502 \u226585%         \u2502\n\u2502 OPV (\u0645\u062a\u0639\u062f\u062f \u0627\u0644\u062c\u0631\u0639\u0627\u062a)        \u2502 \u226550%         \u2502\n\u2502 BCG (\u0645\u062a\u0639\u062f\u062f \u0627\u0644\u062c\u0631\u0639\u0627\u062a)        \u2502 \u226550%         \u2502\n\u2502 MR (\u0645\u062a\u0639\u062f\u062f \u0627\u0644\u062c\u0631\u0639\u0627\u062a)         \u2502 \u226550%         \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n\u26a0\ufe0f \u0645\u0624\u0634\u0631 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u0646\u062e\u0641\u0636 \u064a\u0639\u0646\u064a:\n\u2022 \u0647\u062f\u0631 \u0645\u0631\u062a\u0641\u0639\n\u2022 \u062a\u0648\u0632\u064a\u0639 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0627\u0644\u062d\u0627\u062c\u0629\n\u2022 \u0639\u062f\u0645 \u062a\u0637\u0628\u064a\u0642 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0642\u0627\u0631\u0648\u0631\u0629 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629\n\n\ud83d\udca1 \u0631\u0627\u0642\u0628 \u0627\u0644\u0645\u0624\u0634\u0631 \u0634\u0647\u0631\u064a\u0627\u064b \u0648\u0639\u062f\u0651\u0644 \u0627\u0644\u0637\u0644\u0628\u0627\u062a \u062d\u0633\u0628 \u0627\u0644\u0627\u0633\u062a\u0647\u0644\u0627\u0643 \u0627\u0644\u0641\u0639\u0644\u064a!","\u2696\ufe0f \u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0639\u0627\u062f\u0644 \u0644\u0644\u0642\u0627\u062d\u0627\u062a:\n\n\ud83d\udccc \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u062a\u0648\u0632\u064a\u0639:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u0639\u062f\u0627\u0644\u0629: \u0643\u0644 \u0645\u0646\u0637\u0642\u0629 \u062a\u062d\u0635\u0644 \u0639\u0644\u0649 \u062d\u0635\u062a\u0647\u0627 \u062d\u0633\u0628 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646\n2\ufe0f\u20e3 \u0627\u0644\u0634\u0641\u0627\u0641\u064a\u0629: \u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u0648\u0627\u0636\u062d\u0629 \u0648\u0645\u0639\u0644\u0646\u0629\n3\ufe0f\u20e3 \u0627\u0644\u0643\u0641\u0627\u0621\u0629: \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u062a\u0630\u0647\u0628 \u062d\u064a\u062b \u0627\u0644\u062d\u0627\u062c\u0629 \u0627\u0644\u0623\u0643\u0628\u0631\n4\ufe0f\u20e3 \u0627\u0644\u0623\u0648\u0644\u0648\u064a\u0629: \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0630\u0627\u062a \u0627\u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0645\u0646\u062e\u0641\u0636\u0629 \u0623\u0648\u0644\u0627\u064b\n\n\ud83d\udccb \u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0644\u062a\u0648\u0632\u064a\u0639:\n   \u2022 \u0639\u062f\u062f \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646\n   \u2022 \u0645\u0639\u062f\u0644 \u0627\u0644\u0627\u0633\u062a\u0647\u0644\u0627\u0643 \u0627\u0644\u0633\u0627\u0628\u0642\n   \u2022 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u0627\u0644\u062d\u0627\u0644\u064a\n   \u2022 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0645\u062e\u0637\u0637\u0629 (\u062d\u0645\u0644\u0627\u062a)\n   \u2022 \u0645\u0648\u0633\u0645 \u0627\u0644\u062d\u0645\u0644\u0627\u062a\n\n\u26a0\ufe0f \u062a\u062d\u062f\u064a\u0627\u062a \u0627\u0644\u062a\u0648\u0632\u064a\u0639:\n   \u2022 \u0646\u0642\u0635 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062f\u0642\u064a\u0642\u0629 \u0639\u0646 \u0627\u0644\u0633\u0643\u0627\u0646\n   \u2022 \u0627\u0644\u0646\u0632\u0648\u062d \u0627\u0644\u0633\u0643\u0627\u0646\u064a\n   \u2022 \u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u0646\u0642\u0644 \u0644\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0646\u0627\u0626\u064a\u0629\n   \u2022 \u0627\u0646\u0639\u062f\u0627\u0645 \u0627\u0644\u0623\u0645\u0646 \u0641\u064a \u0628\u0639\u0636 \u0627\u0644\u0645\u0646\u0627\u0637\u0642\n\n\ud83d\udca1 \u062a\u0648\u0632\u064a\u0639 \u0639\u0627\u062f\u0644 = \u0644\u0627 \u0645\u0631\u0641\u0642 \u064a\u0646\u0641\u062f \u0645\u0646\u0647 \u0627\u0644\u0644\u0642\u0627\u062d \u0648\u0644\u0627 \u0645\u0631\u0641\u0642 \u064a\u062e\u0632\u0646 \u0641\u0627\u0626\u0636\u0627\u064b!","\ud83c\udfe5 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0643\u062c\u0632\u0621 \u0645\u0646 \u0627\u0644\u0631\u0639\u0627\u064a\u0629 \u0627\u0644\u0635\u062d\u064a\u0629 \u0627\u0644\u0623\u0648\u0644\u064a\u0629:\n\n\ud83d\udccc \u0645\u0648\u0642\u0639 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0641\u064a \u0627\u0644\u0631\u0639\u0627\u064a\u0629 \u0627\u0644\u0623\u0648\u0644\u064a\u0629:\n\u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0647\u0648 \u0623\u062d\u062f \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0627\u0644\u062b\u0645\u0627\u0646\u064a\u0629 \u0644\u0644\u0631\u0639\u0627\u064a\u0629 \u0627\u0644\u0635\u062d\u064a\u0629 \u0627\u0644\u0623\u0648\u0644\u064a\u0629 (\u0625\u0639\u0644\u0627\u0646 \u0623\u0644\u0645\u0627 \u0622\u062a\u0627 1978).\n\n\ud83c\udfaf \u0627\u0644\u062a\u0643\u0627\u0645\u0644 \u0645\u0639 \u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0631\u0639\u0627\u064a\u0629 \u0627\u0644\u0623\u0648\u0644\u064a\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0635\u062d\u0629 \u0627\u0644\u0637\u0641\u0644:\n   \u2022 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 + \u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u0646\u0645\u0648\n   \u2022 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 + \u0645\u0639\u0627\u0644\u062c\u0629 \u0633\u0648\u0621 \u0627\u0644\u062a\u063a\u0630\u064a\u0629\n   \u2022 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 + \u0641\u064a\u062a\u0627\u0645\u064a\u0646 \u0623\n\n2\ufe0f\u20e3 \u0635\u062d\u0629 \u0627\u0644\u0623\u0645:\n   \u2022 Td \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062d\u0645\u0644\n   \u2022 \u0627\u0644\u062a\u0648\u0639\u064a\u0629 \u0628\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0645\u0648\u0644\u0648\u062f\n   \u2022 \u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0623\u0633\u0631\u0629 + \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n\n3\ufe0f\u20e3 \u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0627\u0644\u0645\u0639\u062f\u064a\u0629:\n   \u2022 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 + \u0627\u0644\u062a\u0631\u0635\u062f \u0627\u0644\u0648\u0628\u0627\u0626\u064a\n   \u2022 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 + \u0645\u0643\u0627\u0641\u062d\u0629 \u0627\u0644\u0645\u0644\u0627\u0631\u064a\u0627\n   \u2022 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 + \u0645\u0643\u0627\u0641\u062d\u0629 \u0627\u0644\u0625\u0633\u0647\u0627\u0644\n\n4\ufe0f\u20e3 \u0627\u0644\u062a\u062b\u0642\u064a\u0641 \u0627\u0644\u0635\u062d\u064a:\n   \u2022 \u0627\u0644\u062a\u0648\u0639\u064a\u0629 \u0628\u0623\u0647\u0645\u064a\u0629 \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0645\u0643\u0627\u0641\u062d\u0629 \u0627\u0644\u0634\u0627\u0626\u0639\u0627\u062a\n   \u2022 \u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u0633\u0644\u0648\u0643 \u0627\u0644\u0635\u062d\u064a\n\n\ud83d\udca1 \u062a\u062d\u0635\u064a\u0646 \u0645\u062a\u0643\u0627\u0645\u0644 = \u0631\u0639\u0627\u064a\u0629 \u0634\u0627\u0645\u0644\u0629 = \u0635\u062d\u0629 \u0623\u0641\u0636\u0644!","\ud83c\udfd9\ufe0f \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0641\u064a \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u062d\u0636\u0631\u064a\u0629:\n\n\ud83d\udccc \u062a\u062d\u062f\u064a\u0627\u062a \u062e\u0627\u0635\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 \u0623\u062d\u064a\u0627\u0621 \u0639\u0634\u0648\u0627\u0626\u064a\u0629 \u063a\u064a\u0631 \u0645\u062e\u0637\u0637\u0629\n\u2022 \u0633\u0643\u0627\u0646 \u0645\u062a\u0646\u0642\u0644\u0648\u0646 (\u0646\u0632\u0648\u062d \u062f\u0627\u062e\u0644\u064a)\n\u2022 \u0641\u0642\u0631 \u0645\u062f\u0642\u0639 \u064a\u0645\u0646\u0639 \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u062e\u062f\u0645\u0627\u062a\n\u2022 \u0645\u0631\u0627\u0641\u0642 \u0635\u062d\u064a\u0629 \u0645\u0632\u062f\u062d\u0645\u0629\n\u2022 \u0645\u062c\u062a\u0645\u0639\u0627\u062a \u0645\u062a\u0646\u0648\u0639\u0629 \u062b\u0642\u0627\u0641\u064a\u0627\u064b\n\n\ud83c\udfaf \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u062d\u0636\u0631\u064a:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0645\u0633\u062d \u0627\u0644\u0623\u062d\u064a\u0627\u0621:\n   \u2022 \u062d\u0635\u0631 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u064a\u0646\n   \u2022 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0645\u062d\u0631\u0648\u0645\u0629\n   \u2022 \u062a\u062d\u062f\u064a\u062b \u0627\u0644\u062e\u0631\u0627\u0626\u0637\n\n2\ufe0f\u20e3 \u0646\u0642\u0627\u0637 \u062a\u062d\u0635\u064a\u0646 \u0645\u062a\u0639\u062f\u062f\u0629:\n   \u2022 \u0645\u0631\u0627\u0643\u0632 \u0635\u062d\u064a\u0629 \u062b\u0627\u0628\u062a\u0629\n   \u2022 \u0646\u0642\u0627\u0637 \u062a\u062d\u0635\u064a\u0646 \u0645\u0624\u0642\u062a\u0629 \u0641\u064a \u0627\u0644\u0623\u062d\u064a\u0627\u0621\n   \u2022 \u062c\u0644\u0633\u0627\u062a \u0645\u0633\u0627\u0626\u064a\u0629 \u0644\u0644\u0639\u0627\u0645\u0644\u064a\u0646\n\n3\ufe0f\u20e3 \u0634\u0631\u0627\u0643\u0627\u062a \u0645\u062c\u062a\u0645\u0639\u064a\u0629:\n   \u2022 \u062a\u0639\u0627\u0648\u0646 \u0645\u0639 \u0631\u0624\u0633\u0627\u0621 \u0627\u0644\u0623\u062d\u064a\u0627\u0621\n   \u2022 \u0645\u062a\u0637\u0648\u0639\u0648\u0646 \u0645\u062d\u0644\u064a\u0648\u0646\n   \u2022 \u0639\u064a\u0627\u062f\u0627\u062a \u062e\u0627\u0635\u0629 \u0645\u0634\u0627\u0631\u0643\u0629\n\n\ud83d\udca1 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0644\u064a\u0633\u062a \u062f\u0627\u0626\u0645\u0627\u064b \u0645\u064a\u0632\u0629 \u2014 \u0628\u0639\u0636 \u0627\u0644\u0623\u062d\u064a\u0627\u0621 \u0623\u0633\u0648\u0623 \u0645\u0646 \u0627\u0644\u0631\u064a\u0641!","\ud83d\udca7 \u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u0645\u062e\u0641\u0641 (Diluent) \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d:\n\n\ud83d\udccc \u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u062e\u0641\u0641\u061f\n\u0633\u0627\u0626\u0644 \u062e\u0627\u0635 \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0644\u0625\u0639\u0627\u062f\u0629 \u062a\u062d\u0636\u064a\u0631 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0645\u062c\u0641\u0641\u0629 (BCG, MR) \u0642\u0628\u0644 \u0627\u0644\u0625\u0639\u0637\u0627\u0621.\n\n\u26a0\ufe0f \u0642\u0648\u0627\u0639\u062f \u062d\u0631\u062c\u0629:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0644\u0627 \u062a\u064f\u062c\u0645\u0651\u062f \u0627\u0644\u0645\u062e\u0641\u0641 \u0623\u0628\u062f\u0627\u064b!\n   \u2022 \u0627\u0644\u062a\u062c\u0645\u064a\u062f \u064a\u0643\u0633\u0631 \u0627\u0644\u0632\u062c\u0627\u062c \u0623\u0648 \u064a\u063a\u064a\u0651\u0631 \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u0629\n   \u2022 \u064a\u064f\u062e\u0632\u0646 \u0641\u064a \u062f\u0631\u062c\u0629 2-8\xb0\u0645 \u0623\u0648 \u0641\u064a \u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u063a\u0631\u0641\u0629\n   \u2022 \u0644\u0643\u0646 \u064a\u064f\u0628\u0631\u0651\u062f \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0628\u0640 24 \u0633\u0627\u0639\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644\n\n2\ufe0f\u20e3 \u0643\u0644 \u0644\u0642\u0627\u062d \u0644\u0647 \u0645\u062e\u0641\u0641 \u062e\u0627\u0635:\n   \u2022 \u0645\u062e\u0641\u0641 BCG \u2260 \u0645\u062e\u0641\u0641 MR\n   \u2022 \u0644\u0627 \u062a\u0633\u062a\u062e\u062f\u0645 \u0645\u062e\u0641\u0641 \u0644\u0642\u0627\u062d \u0645\u0639 \u0644\u0642\u0627\u062d \u0622\u062e\u0631 \u0623\u0628\u062f\u0627\u064b!\n   \u2022 \u0627\u0633\u062a\u062e\u062f\u0645 \u0641\u0642\u0637 \u0627\u0644\u0645\u062e\u0641\u0641 \u0645\u0646 \u0646\u0641\u0633 \u0627\u0644\u0634\u0631\u0643\u0629 \u0627\u0644\u0645\u0635\u0646\u0639\u0629\n\n3\ufe0f\u20e3 \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645:\n   \u2022 \u0628\u0631\u0651\u062f \u0627\u0644\u0645\u062e\u0641\u0641 \u0644\u062f\u0631\u062c\u0629 2-8\xb0\u0645 \u0642\u0628\u0644 24 \u0633\u0627\u0639\u0629\n   \u2022 \u0645\u062e\u0641\u0641 \u0628\u0627\u0631\u062f + \u0644\u0642\u0627\u062d \u0628\u0627\u0631\u062f = \u0625\u0639\u0627\u062f\u0629 \u062a\u062d\u0636\u064a\u0631 \u0622\u0645\u0646\u0629\n   \u2022 \u0645\u062e\u0641\u0641 \u062f\u0627\u0641\u0626 + \u0644\u0642\u0627\u062d \u0628\u0627\u0631\u062f = \u0635\u062f\u0645\u0629 \u062d\u0631\u0627\u0631\u064a\u0629 \u0644\u0644\u0642\u0627\u062d!\n\n4\ufe0f\u20e3 \u0639\u0646\u062f \u0627\u0644\u062a\u062d\u0636\u064a\u0631:\n   \u2022 \u062d\u0642\u0646 \u0627\u0644\u0645\u062e\u0641\u0641 \u0628\u0628\u0637\u0621 \u0641\u064a \u0627\u0644\u0642\u0627\u0631\u0648\u0631\u0629\n   \u2022 \u0644\u0627 \u062a\u0647\u0632 \u0628\u0639\u0646\u0641 \u2014 \u062d\u0631\u0643\u0629 \u062f\u0627\u0626\u0631\u064a\u0629 \u0644\u0637\u064a\u0641\u0629\n   \u2022 \u0627\u0646\u062a\u0638\u0631 \u062d\u062a\u0649 \u064a\u0630\u0648\u0628 \u0627\u0644\u0645\u0633\u062d\u0648\u0642 \u062a\u0645\u0627\u0645\u0627\u064b\n\n\ud83d\udca1 \u0645\u062e\u0641\u0641 \u062e\u0627\u0637\u0626 = \u0644\u0642\u0627\u062d \u0645\u062f\u0645\u0631!","\ud83e\uddca \u0623\u0646\u0648\u0627\u0639 \u0623\u0643\u064a\u0627\u0633 \u0627\u0644\u062b\u0644\u062c \u0648\u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u0627:\n\n\ud83d\udccc \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0623\u0643\u064a\u0627\u0633:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0623\u0643\u064a\u0627\u0633 \u0627\u0644\u062b\u0644\u062c \u0627\u0644\u0645\u0627\u0626\u064a\u0629 (Ice Packs):\n   \u2022 \u062a\u064f\u0645\u0644\u0623 \u0628\u0627\u0644\u0645\u0627\u0621 \u0648\u062a\u064f\u062c\u0645\u0651\u062f \u0641\u064a \u0627\u0644\u0641\u0631\u064a\u0632\u0631\n   \u2022 \u062a\u064f\u0633\u062a\u062e\u062f\u0645 \u0641\u064a \u0635\u0646\u0627\u062f\u064a\u0642 \u0627\u0644\u062a\u0628\u0631\u064a\u062f \u0648\u062d\u0627\u0641\u0638\u0627\u062a \u0627\u0644\u0644\u0642\u0627\u062d\n   \u2022 \u064a\u062c\u0628 \u062a\u0631\u0648\u064a\u0636\u0647\u0627 (Conditioning) \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645\n\n2\ufe0f\u20e3 \u0623\u0643\u064a\u0627\u0633 \u0627\u0644\u062a\u0628\u0631\u064a\u062f \u0627\u0644\u062c\u064a\u0644\u0627\u062a\u064a\u0646\u064a\u0629 (Gel Packs):\n   \u2022 \u062a\u062d\u062a\u0648\u064a \u0639\u0644\u0649 \u0645\u0627\u062f\u0629 \u062c\u064a\u0644\u0627\u062a\u064a\u0646\u064a\u0629\n   \u2022 \u062a\u0628\u0642\u0649 \u0628\u0627\u0631\u062f\u0629 \u0644\u0641\u062a\u0631\u0629 \u0623\u0637\u0648\u0644\n   \u2022 \u0644\u0627 \u062a\u062d\u062a\u0627\u062c \u062a\u0631\u0648\u064a\u0636\n\n\ud83d\udccb \u062a\u0631\u0648\u064a\u0636 \u0623\u0643\u064a\u0627\u0633 \u0627\u0644\u062b\u0644\u062c (Conditioning):\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\ud83d\udccc \u0644\u0645\u0627\u0630\u0627 \u0627\u0644\u062a\u0631\u0648\u064a\u0636\u061f\n\u2022 \u0623\u0643\u064a\u0627\u0633 \u0627\u0644\u062b\u0644\u062c \u0645\u0646 \u0627\u0644\u0641\u0631\u064a\u0632\u0631 (-20\xb0\u0645) \u0642\u062f \u062a\u064f\u062c\u0645\u062f \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a!\n\u2022 \u0627\u0644\u062a\u0631\u0648\u064a\u0636 \u064a\u0630\u064a\u0628 \u0627\u0644\u062c\u0644\u064a\u062f \u0627\u0644\u0633\u0637\u062d\u064a \u0641\u0642\u0637\n\u2022 \u064a\u0645\u0646\u0639 \u062a\u062c\u0645\u064a\u062f \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0646\u0642\u0644\n\n\ud83d\udd27 \u0643\u064a\u0641\u064a\u0629 \u0627\u0644\u062a\u0631\u0648\u064a\u0636:\n1. \u0623\u062e\u0631\u062c \u0627\u0644\u0623\u0643\u064a\u0627\u0633 \u0645\u0646 \u0627\u0644\u0641\u0631\u064a\u0632\u0631\n2. \u0627\u062a\u0631\u0643\u0647\u0627 \u0641\u064a \u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u063a\u0631\u0641\u0629 (60-90 \u062f\u0642\u064a\u0642\u0629)\n3. \u0647\u0632 \u0627\u0644\u0643\u064a\u0633 \u2014 \u0625\u0630\u0627 \u062a\u062d\u0631\u0643\u062a \u0642\u0637\u0639\u0629 \u0627\u0644\u062b\u0644\u062c \u062f\u0627\u062e\u0644\u0647 \u2190 \u062c\u0627\u0647\u0632 \u2705\n4. \u0625\u0630\u0627 \u0643\u0627\u0646 \u062c\u0627\u0645\u062f\u0627\u064b \u062a\u0645\u0627\u0645\u0627\u064b \u2190 \u064a\u062d\u062a\u0627\u062c \u0648\u0642\u062a\u0627\u064b \u0623\u0643\u062b\u0631 \u274c\n\n\ud83d\udca1 \u0627\u0644\u062a\u0631\u0648\u064a\u0636 \u062e\u0637\u0648\u0629 \u062d\u0631\u062c\u0629 \u2014 \u0644\u0627 \u062a\u062a\u062e\u0637\u0647\u0627 \u0623\u0628\u062f\u0627\u064b!","\ud83d\udcf1 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u0627\u0644\u062a\u062d\u0648\u0644 \u0627\u0644\u0631\u0642\u0645\u064a:\n\n\ud83d\udccc \u0623\u062f\u0627\u0629\u062a \u0631\u0642\u0645\u064a\u0629 \u0641\u064a \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 DHIS2:\n   \u2022 \u0646\u0638\u0627\u0645 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0635\u062d\u064a \u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a\n   \u2022 \u0625\u062f\u062e\u0627\u0644 \u0648\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\n   \u2022 \u0644\u0648\u062d\u0627\u062a \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u062a\u0641\u0627\u0639\u0644\u064a\u0629\n\n2\ufe0f\u20e3 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u0627\u062a \u0627\u0644\u0630\u0643\u064a\u0629:\n   \u2022 \u062a\u0637\u0628\u064a\u0642\u0627\u062a \u062a\u0630\u0643\u064a\u0631 \u0628\u0645\u0648\u0627\u0639\u064a\u062f \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0628\u0637\u0627\u0642\u0627\u062a \u062a\u0637\u0639\u064a\u0645 \u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a\u0629\n   \u2022 \u0627\u0633\u062a\u0634\u0627\u0631\u0627\u062a \u0639\u0646 \u0628\u0639\u062f\n\n3\ufe0f\u20e3 \u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0646\u0635\u064a\u0629 (SMS):\n   \u2022 \u062a\u0630\u0643\u064a\u0631 \u0628\u0645\u0648\u0627\u0639\u064a\u062f \u0627\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u0625\u0639\u0644\u0627\u0646 \u0639\u0646 \u062d\u0645\u0644\u0627\u062a\n   \u2022 \u0627\u0633\u062a\u0628\u064a\u0627\u0646\u0627\u062a \u0631\u0636\u0627\n\n4\ufe0f\u20e3 \u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a:\n   \u2022 \u0645\u062c\u0645\u0648\u0639\u0627\u062a \u0648\u0627\u062a\u0633\u0627\u0628 \u0644\u0644\u0623\u0645\u0647\u0627\u062a\n   \u2022 \u0635\u0641\u062d\u0627\u062a \u0641\u064a\u0633\u0628\u0648\u0643 \u0644\u0644\u062a\u0648\u0639\u064a\u0629\n   \u2022 \u0645\u0642\u0627\u0637\u0639 \u0641\u064a\u062f\u064a\u0648 \u062a\u0639\u0644\u064a\u0645\u064a\u0629\n\n5\ufe0f\u20e3 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f/QR:\n   \u2022 \u062a\u062a\u0628\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0635\u0646\u0639 \u0644\u0644\u0645\u0631\u0641\u0642\n   \u2022 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629\n   \u2022 \u0645\u0646\u0639 \u0627\u0644\u062a\u0632\u0648\u064a\u0631\n\n\ud83d\udca1 \u0627\u0644\u062a\u0642\u0646\u064a\u0629 \u062a\u0633\u0647\u0651\u0644 \u0627\u0644\u0648\u0635\u0648\u0644 \u0648\u062a\u062d\u0633\u0651\u0646 \u0627\u0644\u062c\u0648\u062f\u0629!","\u2744\ufe0f \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0644\u0642\u0627\u062d \u0627\u0644\u0630\u064a \u062a\u0639\u0631\u0636 \u0644\u0644\u062a\u062c\u0645\u062f:\n\n\ud83d\udccc \u0643\u064a\u0641 \u062a\u0639\u0631\u0641 \u0623\u0646 \u0627\u0644\u0644\u0642\u0627\u062d \u062a\u062c\u0645\u062f\u061f\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0645\u0624\u0634\u0631 \u0627\u0644\u062a\u062c\u0645\u062f (Freeze Indicator):\n   \u2022 \u062c\u0647\u0627\u0632 \u0635\u063a\u064a\u0631 \u062f\u0627\u062e\u0644 \u0627\u0644\u062b\u0644\u0627\u062c\u0629\n   \u2022 \u0625\u0630\u0627 \u062a\u063a\u064a\u0631 \u0644\u0648\u0646\u0647 \u0645\u0646 \u0627\u0644\u0623\u0632\u0631\u0642 \u0644\u0644\u0623\u0628\u064a\u0636 \u2190 \u062d\u062f\u062b \u062a\u062c\u0645\u062f!\n\n2\ufe0f\u20e3 \u0627\u062e\u062a\u0628\u0627\u0631 \u0627\u0644\u0647\u0632 (Shake Test):\n   \u2022 \u0647\u0632 \u0639\u0628\u0648\u0629 \u0645\u0634\u062a\u0628\u0647\u0629 \u0648\u0639\u0628\u0648\u0629 \u062c\u062f\u064a\u062f\u0629 \u0645\u0639\u0627\u064b\n   \u2022 \u0625\u0630\u0627 \u062a\u0631\u0633\u0628 \u0627\u0644\u0644\u0642\u0627\u062d \u0627\u0644\u0645\u0634\u062a\u0628\u0647 \u0628\u0633\u0631\u0639\u0629 \u2190 \u0645\u062a\u062c\u0645\u062f!\n   \u2022 \u0625\u0630\u0627 \u0628\u0642\u064a \u0645\u0639\u0643\u0631\u0627\u064b \u0645\u062b\u0644 \u0627\u0644\u062c\u062f\u064a\u062f \u2190 \u0633\u0644\u064a\u0645\n\n\u26a0\ufe0f \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0627\u0644\u0623\u0643\u062b\u0631 \u0639\u0631\u0636\u0629 \u0644\u0644\u062a\u062c\u0645\u062f:\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 \u0627\u0644\u0644\u0642\u0627\u062d                     \u2502 \u062d\u0633\u0627\u0633\u064a\u0629 \u0627\u0644\u062a\u062c\u0645\u062f\u2502\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\n\u2502 Penta (DTP-HepB-Hib)      \u2502 \u0639\u0627\u0644\u064a\u0629 \u062c\u062f\u0627\u064b   \u2502\n\u2502 PCV                        \u2502 \u0639\u0627\u0644\u064a\u0629        \u2502\n\u2502 IPV                        \u2502 \u0639\u0627\u0644\u064a\u0629        \u2502\n\u2502 HepB                       \u2502 \u0639\u0627\u0644\u064a\u0629        \u2502\n\u2502 Td/TT                      \u2502 \u0639\u0627\u0644\u064a\u0629        \u2502\n\u2502 BCG, OPV, MR              \u2502 \u0644\u0627 \u062a\u062a\u0623\u062b\u0631     \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n\ud83d\udeab \u0627\u0644\u0625\u062c\u0631\u0627\u0621:\n\u2022 \u0644\u0627 \u062a\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0644\u0642\u0627\u062d \u0627\u0644\u0645\u062a\u062c\u0645\u062f \u0623\u0628\u062f\u0627\u064b!\n\u2022 \u0623\u0648\u0642\u0641 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647 \u0641\u0648\u0631\u0627\u064b\n\u2022 \u0627\u0641\u062d\u0635 \u062c\u0645\u064a\u0639 \u0627\u0644\u0639\u0628\u0648\u0627\u062a \u0641\u064a \u0627\u0644\u062b\u0644\u0627\u062c\u0629\n\u2022 \u0623\u0628\u0644\u063a \u0627\u0644\u0645\u0634\u0631\u0641 \u0648\u0623\u0631\u0633\u0644 \u062a\u0642\u0631\u064a\u0631\u0627\u064b\n\n\ud83d\udca1 \u0627\u0644\u0648\u0642\u0627\u064a\u0629: \u0644\u0627 \u062a\u0636\u0639 \u0627\u0644\u0644\u0642\u0627\u062d\u0627\u062a \u0642\u0631\u064a\u0628\u0629 \u0645\u0646 \u0627\u0644\u0645\u0628\u062e\u0631 \u0623\u0648 \u0627\u0644\u0641\u0631\u064a\u0632\u0631!","\ud83c\udf0d \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0648\u062a\u063a\u064a\u0631 \u0627\u0644\u0645\u0646\u0627\u062e:\n\n\ud83d\udccc \u062a\u0623\u062b\u064a\u0631 \u062a\u063a\u064a\u0631 \u0627\u0644\u0645\u0646\u0627\u062e \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0635\u064a\u0646:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0639\u0644\u0649 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062a\u0628\u0631\u064a\u062f:\n   \u2022 \u0627\u0631\u062a\u0641\u0627\u0639 \u062f\u0631\u062c\u0627\u062a \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u064a\u0632\u064a\u062f \u0627\u0644\u0639\u0628\u0621 \u0639\u0644\u0649 \u0627\u0644\u062b\u0644\u0627\u062c\u0627\u062a\n   \u2022 \u0627\u0646\u0642\u0637\u0627\u0639 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621 \u0623\u0643\u062b\u0631 \u062a\u0643\u0631\u0627\u0631\u0627\u064b\n   \u2022 \u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 2-8\xb0\u0645 \u0641\u064a \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u062d\u0627\u0631\u0629\n\n2\ufe0f\u20e3 \u0639\u0644\u0649 \u0627\u0644\u0623\u0645\u0631\u0627\u0636:\n   \u2022 \u062a\u063a\u064a\u0631 \u0623\u0646\u0645\u0627\u0637 \u0627\u0646\u062a\u0634\u0627\u0631 \u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0627\u0644\u0645\u0639\u062f\u064a\u0629\n   \u2022 \u0638\u0647\u0648\u0631 \u0623\u0645\u0631\u0627\u0636 \u0641\u064a \u0645\u0646\u0627\u0637\u0642 \u062c\u062f\u064a\u062f\u0629\n   \u2022 \u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u0641\u064a\u0636\u0627\u0646\u0627\u062a \u0648\u0627\u0644\u0623\u0648\u0628\u0626\u0629\n\n3\ufe0f\u20e3 \u0639\u0644\u0649 \u0627\u0644\u0648\u0635\u0648\u0644:\n   \u2022 \u0641\u064a\u0636\u0627\u0646\u0627\u062a \u062a\u0642\u0637\u0639 \u0627\u0644\u0637\u0631\u0642\n   \u2022 \u0645\u0648\u062c\u0627\u062a \u062d\u0631 \u0634\u062f\u064a\u062f\u0629\n   \u2022 \u062c\u0641\u0627\u0641 \u064a\u0624\u062b\u0631 \u0639\u0644\u0649 \u0627\u0644\u062a\u0646\u0642\u0644\n\n\ud83c\udfaf \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0644\u062a\u0643\u064a\u0641:\n   \u2022 \u062b\u0644\u0627\u062c\u0627\u062a \u062a\u0639\u0645\u0644 \u0628\u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u0634\u0645\u0633\u064a\u0629\n   \u2022 \u0623\u0646\u0638\u0645\u0629 \u0637\u0627\u0642\u0629 \u0627\u062d\u062a\u064a\u0627\u0637\u064a\u0629\n   \u2022 \u062e\u0637\u0637 \u0637\u0648\u0627\u0631\u0626 \u0645\u062a\u0642\u062f\u0645\u0629\n   \u2022 \u0641\u0631\u0642 \u0645\u062a\u0646\u0642\u0644\u0629 \u0628\u0645\u0631\u0643\u0628\u0627\u062a \u0645\u0646\u0627\u0633\u0628\u0629\n\n\ud83d\udca1 \u0627\u0644\u062a\u0643\u064a\u0641 \u0645\u0639 \u0627\u0644\u0645\u0646\u0627\u062e = \u0636\u0645\u0627\u0646 \u0627\u0633\u062a\u0645\u0631\u0627\u0631 \u0627\u0644\u062a\u062d\u0635\u064a\u0646!","\ud83d\udcc5 \u062c\u062f\u0648\u0644 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0627\u0644\u0645\u062d\u062f\u062b 2026 \u2014 \u0627\u0644\u062a\u063a\u064a\u064a\u0631\u0627\u062a \u0627\u0644\u062c\u062f\u064a\u062f\u0629:\n\n\ud83d\udccc \u0623\u0628\u0631\u0632 \u0627\u0644\u062a\u062d\u062f\u064a\u062b\u0627\u062a:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0627\u0644\u062a\u0623\u0643\u064a\u062f \u0639\u0644\u0649 \u062c\u0631\u0639\u0629 \u0627\u0644\u0648\u0644\u0627\u062f\u0629 HepB0:\n   \u2022 \u064a\u062c\u0628 \u0625\u0639\u0637\u0627\u0624\u0647\u0627 \u062e\u0644\u0627\u0644 \u0623\u0648\u0644 24 \u0633\u0627\u0639\u0629 \u0645\u0646 \u0627\u0644\u0648\u0644\u0627\u062f\u0629\n   \u2022 \u0623\u0647\u0645\u064a\u0629 \u0642\u0635\u0648\u0649 \u0644\u0645\u0646\u0639 \u0627\u0646\u062a\u0642\u0627\u0644 \u0627\u0644\u0639\u062f\u0648\u0649 \u0645\u0646 \u0627\u0644\u0623\u0645\n\n2\ufe0f\u20e3 \u0627\u0644\u062a\u0623\u0643\u064a\u062f \u0639\u0644\u0649 IPV \u0645\u0639 OPV:\n   \u2022 IPV \u0641\u064a \u0639\u0645\u0631 14 \u0623\u0633\u0628\u0648\u0639 \u0645\u0639 OPV3\n   \u2022 \u0636\u0631\u0648\u0631\u064a \u0644\u0644\u0642\u0636\u0627\u0621 \u0639\u0644\u0649 \u0634\u0644\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644\n\n3\ufe0f\u20e3 MR \u0641\u064a \u0639\u0645\u0631 9 \u0623\u0634\u0647\u0631 \u0648 18 \u0634\u0647\u0631:\n   \u2022 \u062c\u0631\u0639\u062a\u0627\u0646 \u0623\u0633\u0627\u0633\u064a\u062a\u0627\u0646 + \u062c\u0631\u0639\u0629 \u0645\u0639\u0632\u0632\u0629 \u0639\u0646\u062f \u0627\u0644\u0645\u062f\u0631\u0633\u0629\n   \u2022 \u0645\u0647\u0645 \u0644\u0644\u0642\u0636\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u062d\u0635\u0628\u0629 \u0648\u0627\u0644\u062d\u0635\u0628\u0629 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064a\u0629\n\n4\ufe0f\u20e3 \u0641\u064a\u062a\u0627\u0645\u064a\u0646 \u0623:\n   \u2022 100,000 \u0648\u062d\u062f\u0629 \u062f\u0648\u0644\u064a\u0629 \u0641\u064a 9 \u0623\u0634\u0647\u0631 (\u0643\u0628\u0633\u0648\u0644\u0629 \u0632\u0631\u0642\u0627\u0621)\n   \u2022 200,000 \u0648\u062d\u062f\u0629 \u062f\u0648\u0644\u064a\u0629 \u0641\u064a 18 \u0634\u0647\u0631 \u0648 6 \u0633\u0646\u0648\u0627\u062a (\u0643\u0628\u0633\u0648\u0644\u0629 \u062d\u0645\u0631\u0627\u0621)\n   \u2022 \u0645\u0639 \u0627\u0644\u062a\u0637\u0639\u064a\u0645\u0627\u062a \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0632\u064a\u0627\u0631\u0629\n\n\ud83d\udcca \u0627\u0644\u062c\u062f\u0648\u0644 \u0627\u0644\u0643\u0627\u0645\u0644:\n\u0627\u0644\u0648\u0644\u0627\u062f\u0629: BCG + OPV0 + HepB0\n6 \u0623\u0633\u0627\u0628\u064a\u0639: OPV1 + Penta1 + PCV1 + Rota1\n10 \u0623\u0633\u0627\u0628\u064a\u0639: OPV2 + Penta2 + PCV2 + Rota2\n14 \u0623\u0633\u0628\u0648\u0639: OPV3 + Penta3 + PCV3 + IPV1\n9 \u0623\u0634\u0647\u0631: MR1 + OPV4 + IPV2 + \u0641\u064a\u062a\u0627\u0645\u064a\u0646 \u0623 (100,000 \u0648.\u062f)\n18 \u0634\u0647\u0631: MR2 + Penta4 + OPV5 + \u0641\u064a\u062a\u0627\u0645\u064a\u0646 \u0623 (200,000 \u0648.\u062f)\n5-7 \u0633\u0646\u0648\u0627\u062a: Td + MR \u062a\u0639\u0632\u064a\u0632\u064a\u0629 + \u0641\u064a\u062a\u0627\u0645\u064a\u0646 \u0623 (200,000 \u0648.\u062f)\n\n\ud83d\udca1 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u062c\u062f\u0648\u0644 = \u062d\u0645\u0627\u064a\u0629 \u0643\u0627\u0645\u0644\u0629 \u0644\u0637\u0641\u0644\u0643!","\u2694\ufe0f \u0625\u062f\u0627\u0631\u0629 \u062d\u0645\u0644\u0627\u062a \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u0641\u064a \u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0646\u0632\u0627\u0639\u0627\u062a:\n\n\ud83d\udccc \u0627\u0644\u062a\u062d\u062f\u064a\u0627\u062a:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\u2022 \u0627\u0646\u0639\u062f\u0627\u0645 \u0627\u0644\u0623\u0645\u0646 \u064a\u0645\u0646\u0639 \u0648\u0635\u0648\u0644 \u0627\u0644\u0641\u0631\u0642\n\u2022 \u062a\u062f\u0645\u064a\u0631 \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u062a\u062d\u062a\u064a\u0629 \u0627\u0644\u0635\u062d\u064a\u0629\n\u2022 \u0646\u0632\u0648\u062d \u0645\u0633\u062a\u0645\u0631 \u0644\u0644\u0633\u0643\u0627\u0646\n\u2022 \u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0645\u0648\u0627\u0641\u0642\u0629 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0637\u0631\u0627\u0641\n\n\ud83c\udfaf \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0644\u0639\u0645\u0644 \u0641\u064a \u0627\u0644\u0646\u0632\u0627\u0639\u0627\u062a:\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n1\ufe0f\u20e3 \u0623\u064a\u0627\u0645 \u0627\u0644\u0647\u062f\u0646\u0629 (Days of Tranquility):\n   \u2022 \u0627\u062a\u0641\u0627\u0642 \u0648\u0642\u0641 \u0625\u0637\u0644\u0627\u0642 \u0646\u0627\u0631 \u0645\u0624\u0642\u062a \u0644\u0644\u062a\u062d\u0635\u064a\u0646\n   \u2022 \u062a\u062c\u0631\u0628\u0629 \u0646\u0627\u062c\u062d\u0629 \u0641\u064a \u062f\u0648\u0644 \u0639\u062f\u064a\u062f\u0629\n   \u2022 \u062a\u062d\u062a\u0627\u062c \u0648\u0633\u0627\u0637\u0629 \u0645\u0646 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0645\u062a\u062d\u062f\u0629\n\n2\ufe0f\u20e3 \u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0645\u0639 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0637\u0631\u0627\u0641:\n   \u2022 \u0627\u0644\u062d\u064a\u0627\u062f \u0627\u0644\u062a\u0627\u0645 (\u0644\u0627 \u0627\u0646\u062d\u064a\u0627\u0632)\n   \u2022 \u0625\u0628\u0644\u0627\u063a \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0637\u0631\u0627\u0641 \u0628\u0645\u0648\u0627\u0639\u064a\u062f \u0627\u0644\u062d\u0645\u0644\u0627\u062a\n   \u2022 \u0636\u0645\u0627\u0646 \u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u0635\u062d\u064a\u0629\n\n3\ufe0f\u20e3 \u0645\u0631\u0648\u0646\u0629 \u0627\u0644\u062a\u0646\u0641\u064a\u0630:\n   \u2022 \u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0645\u0648\u0627\u0639\u064a\u062f \u062d\u0633\u0628 \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0623\u0645\u0646\u064a\n   \u2022 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0641\u0631\u0642 \u0645\u062d\u0644\u064a\u0629 \u0645\u0646 \u0646\u0641\u0633 \u0627\u0644\u0645\u0646\u0637\u0642\u0629\n   \u2022 \u0627\u0644\u0627\u0633\u062a\u0641\u0627\u062f\u0629 \u0645\u0646 \u0627\u0644\u0645\u0646\u0638\u0645\u0627\u062a \u0627\u0644\u0645\u062d\u0644\u064a\u0629\n\n4\ufe0f\u20e3 \u0627\u0644\u0623\u0648\u0644\u0648\u064a\u0627\u062a:\n   \u2022 \u0627\u0644\u062d\u0635\u0645\u0629 \u0623\u0648\u0644\u0627\u064b (\u0627\u0644\u0623\u0643\u062b\u0631 \u0641\u062a\u0643\u0627\u064b)\n   \u2022 OPV \u062b\u0627\u0646\u064a\u0627\u064b\n   \u2022 Td \u0644\u0644\u062d\u0648\u0627\u0645\u0644 \u062b\u0627\u0644\u062b\u0627\u064b\n\n\ud83d\udca1 \u062d\u062a\u0649 \u0627\u0644\u062d\u0631\u0628 \u0644\u0627 \u062a\u0645\u0646\u0639 \u0627\u0644\u062a\u062d\u0635\u064a\u0646 \u2014 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0644\u064a\u0633\u0648\u0627 \u0637\u0631\u0641\u0627\u064b \u0641\u064a \u0627\u0644\u0635\u0631\u0627\u0639!"],t.w)
